# Einzeldatei: FL-Studio-Parser und Update-Module sind eingebettet.
import base64 as _emb64, zlib as _embz, types as _embtypes, sys as _embsys
def _install_embedded_module(name, payload):
    module = _embtypes.ModuleType(name)
    module.__file__ = __file__ + ":" + name
    _embsys.modules[name] = module
    source = _embz.decompress(_emb64.b85decode(payload)).decode("utf-8")
    exec(compile(source, module.__file__, "exec"), module.__dict__)

