def initialize_test_database():
    """Eine konsistente Kopie anlegen und erst nach erfolgreichem Backup übernehmen."""
    from contextlib import closing
    import os
    import tempfile

    # Performance 2 used the Performance 1 database; import that state with
    # SQLite's online backup API into a NEW database, never share/write it.
    predecessors = ("15_performance9", "15_performance8", "15_performance7", "15_performance6", "15_performance5", "15_performance4", "15_performance3", "15_performance2", "15_performance1", "15", "13", "9", "8", "7", "6_menuefix", "6", "5", "4", "3")
    previous = next((path for number in predecessors
                     if (path := Path.home() / f".meine_mediathek_v1_9_31_test{number}.db").is_file()),
                    None)
    if DB_PATH.exists() or previous is None:
        return
    with tempfile.TemporaryDirectory(prefix=".mediathek_test15_", dir=DB_PATH.parent) as directory:
        snapshot = Path(directory) / "snapshot.db"
        with closing(sqlite3.connect(previous.as_uri() + "?mode=ro", uri=True)) as original:
            with closing(sqlite3.connect(snapshot)) as copy:
                original.backup(copy)
        try:
            # Der Hardlink veröffentlicht die vollständige Kopie ohne Überschreiben.
            os.link(snapshot, DB_PATH)
        except FileExistsError:
            pass


