def fmt_time(sec):
    sec = int(sec or 0)
    return f"{sec // 60}:{sec % 60:02d}"


def fmt_bpm(bpm):
    """Immer nur eine ganzzahlige BPM-Zahl anzeigen, ohne Slash oder Dezimalstellen."""
    if bpm is None or bpm == "":
        return ""
    try:
        value = float(bpm)
        return str(int(round(value))) if math.isfinite(value) and value > 0 else ""
    except (ValueError, TypeError):
        return ""


def fold_bpm(bpm, lo=70.0, hi=180.0):
    """Halb-/Doppeltempo-Fehler in den üblichen Bereich falten."""
    if bpm <= 0:
        return 0.0
    while bpm < lo:
        bpm *= 2
    while bpm >= hi:
        bpm /= 2
    return bpm


def refine_bpm(envs, fps, bpm0, span=0.05, step=0.05):
    """Verfeinert eine grobe BPM-Schätzung über die Autokorrelation der Onset-Kurve(n).
    Mehrere Kurven (Ausschnitte) werden gemittelt, außerdem werden die Korrelationen
    bei 1-4 Taktschlägen kombiniert. Das macht den Wert genauer und robuster."""
    import numpy as np

    if isinstance(envs, np.ndarray) and envs.ndim == 1:
        envs = [envs]
    acs = []
    for env in envs:
        env = np.asarray(env, float)
        env = env - env.mean()
        n = len(env)
        f = np.fft.rfft(env, 2 * n)
        ac = np.fft.irfft(f * np.conj(f))[:n]
        if ac[0] <= 0:
            continue
        acs.append(ac / ac[0] / (1.0 - np.arange(n) / n + 1e-9))
    if not acs:
        return bpm0
    m = min(len(a) for a in acs)
    ac = np.mean([a[:m] for a in acs], axis=0)
    lags = np.arange(m)
    grid = np.arange(bpm0 * (1 - span), bpm0 * (1 + span), step)
    scores = []
    for b in grid:
        lag = 60.0 * fps / b
        scores.append(sum(np.interp(k * lag, lags, ac) for k in (1, 2, 3, 4)))
    return float(grid[int(np.argmax(scores))])


KEY_LABELS = [f"{KEY_NAMES[i]} {mode}" for i in range(12) for mode in ("Major", "Minor")]


def key_scores(chroma):
    """Passung (Korrelation) eines Chroma-Vektors zu allen 24 Tonarten."""
    import numpy as np

    chroma = np.asarray(chroma, float)
    if chroma.std() == 0:
        return np.zeros(24)
    out = []
    for i in range(12):
        for idx in (0, 1):        # 0 = Dur, 1 = Moll
            out.append(float(np.mean([np.corrcoef(chroma, np.roll(p[idx], i))[0, 1]
                                      for p in KEY_PROFILES])))
    return np.array(out)


def key_from_chroma(chroma):
    import numpy as np

    sc = key_scores(chroma)
    return KEY_LABELS[int(np.argmax(sc))] if sc.any() else ""


def key_from_windows(chromas, weights=None):
    """Summiert die Tonart-Werte vieler Zeitfenster (laute Fenster zählen mehr).
    Einzelne Ausreißer-Passagen fallen dadurch kaum ins Gewicht."""
    import numpy as np

    total = np.zeros(24)
    for k, c in enumerate(chromas):
        total += (1.0 if weights is None else weights[k]) * key_scores(c)
    return KEY_LABELS[int(np.argmax(total))] if total.any() else ""


def pick_segments(length):
    """(Start, Dauer) der Ausschnitte: 3 x 30 s verteilt über den Titel,
    bei kurzen Titeln der Anfang bis maximal 75 s."""
    if not length or length < 100:
        return [(0.0, min(float(length or 75), 75.0))]
    seg = 30.0
    return [(max(0.0, min(length * f - seg / 2, length - seg)), seg)
            for f in (0.2, 0.5, 0.8)]


def estimate_bpm_from_envelopes(envs, fps, weights=None):
    """Vergleicht echte Beat-Perioden, statt alle Hi-Hat-Unterteilungen gleich zu bewerten.

    Mehrere getrennte Ausschnitte und unterschiedliche Frequenzbereiche liefern
    unabhängige Stimmen. Der tieffrequente Kick-Impuls erhält dabei mehr Gewicht.
    Die Periodizität ist grundsätzlich nur eine Schätzung, insbesondere bei
    Triplets, Halftime und reinen Melodie-Beats.
    """
    import numpy as np
    from scipy.signal import find_peaks

    fps = float(fps)
    candidate_grid = np.arange(60., 190.01, .25)
    votes, total_weight = np.zeros_like(candidate_grid), 0.0
    weights = list(weights) if weights is not None else [1.0] * len(envs)
    for envelope, weight in zip(envs, weights):
        env = np.asarray(envelope, dtype=np.float64)
        if len(env) < fps * 6 or not np.all(np.isfinite(env)):
            continue
        env = np.maximum(env, 0)
        env = np.minimum(env, np.quantile(env, .98))
        if np.max(env) < 1e-8:
            continue
        env = env / (np.max(env) + 1e-10)
        events, _ = find_peaks(env, height=.22, distance=max(1, round(fps * .12)))
        if len(events) < 7:
            continue
        env -= env.mean()
        n = len(env)
        freq = np.fft.rfft(env, 2*n)
        ac = np.fft.irfft(freq * np.conj(freq))[:n]
        ac /= np.maximum(n - np.arange(n), 1)
        ac /= max(float(ac[0]), 1e-10)
        lag = 60 * fps / candidate_grid
        x = np.arange(n)
        sample = lambda target: np.interp(target, x, ac, left=0, right=0)
        # Die Primärperiode ist wichtiger als die Hihat-Unterteilung.
        scores = (sample(lag) + .32 * sample(2*lag) +
                  .13 * sample(4*lag) + .05 * sample(lag/2))
        scores = np.maximum(scores, 0)
        high = float(scores.max())
        if high < .09:
            continue
        votes += float(weight) * scores / high
        total_weight += float(weight)
    if not total_weight:
        return 0.0
    votes /= total_weight
    peaks, _ = find_peaks(votes, distance=10)
    if not len(peaks):
        peaks = np.array([int(np.argmax(votes))])
    strongest = sorted(peaks, key=lambda idx: votes[idx], reverse=True)
    best = int(strongest[0])
    bpm = float(candidate_grid[best])
    # Halftime-Mehrdeutigkeit nicht blind auf Doubletime hochfalten.
    if bpm < 80 and 2*bpm <= 190:
        double = int(np.argmin(abs(candidate_grid - 2*bpm)))
        if votes[double] >= votes[best] * .88:
            bpm = float(candidate_grid[double])
    # Der Vergleich mit 3:4-Alternativen ist bewusst nicht als starre Regel
    # kodiert: sowohl 93 als auch 124 BPM können reale Tempi sein.
    return float(round(bpm))


def _low_frequency_onsets(y, sr, hop):
    """Separater Kick-/Subbass-Attack-Detektor für 808s und elektronische Beats."""
    import numpy as np
    import librosa

    n_fft = 2048
    spectrum = np.abs(librosa.stft(y=y, n_fft=n_fft, hop_length=hop))
    bins = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
    low = spectrum[(bins >= 38) & (bins <= 205)]
    if low.size == 0:
        return np.zeros(spectrum.shape[1], dtype=float)
    energy = np.sqrt(np.mean(low * low, axis=0))
    log_energy = np.log1p(12 * energy)
    # positive Energieänderungen zeigen den Beginn eines Kicks, nicht das
    # lange Ausschwingen des 808-Basses.
    attack = np.maximum(0, np.diff(log_energy, prepend=log_energy[0]))
    return attack


def estimate_key_from_chromas(chroma_groups):
    """Consensus key detection: normalized harmonic CQT, segment voting.

    CQT-Pitch-Energien werden erst pro Frame normalisiert. Das verhindert,
    dass Bassnoten oder laute Abschnitte die gesamte Tonart dominieren.
    """
    import numpy as np
    segment_scores = []
    for chroma in chroma_groups:
        c = np.asarray(chroma, dtype=float)
        if c.ndim != 2 or c.shape[0] != 12 or c.shape[1] < 8:
            continue
        sums = np.sum(c, axis=0)
        active = sums > max(float(np.quantile(sums, .20)), 1e-8)
        if active.sum() < 8:
            continue
        c = c[:, active] / np.maximum(sums[active], 1e-10)
        # Reduktion dominanter Töne und kurzzeitiger, sehr hoher Peaks.
        c = np.sqrt(np.maximum(c, 0.0))
        win = max(16, min(96, c.shape[1]//5))
        scores = []
        for first in range(0, c.shape[1], win):
            frame = c[:, first:first+win]
            if frame.shape[1] < 8:
                continue
            scores.append(key_scores(np.mean(frame, axis=1)))
        if scores:
            segment_scores.append(np.mean(scores, axis=0))
    if not segment_scores:
        return ""
    scores = np.mean(segment_scores, axis=0)
    winner = int(np.argmax(scores))
    sorted_scores = np.sort(scores)[::-1]
    # Bei sehr unklaren Tonarten leeres Feld statt willkürlichem Ergebnis.
    if sorted_scores[0] < .12 or (sorted_scores[0]-sorted_scores[1] < .012
                                 and sorted_scores[0] < .30):
        return ""
    return KEY_LABELS[winner]



def _beat_envelopes_198(y, sr=11025, hop=256):
    """Bandweise Transienten und breitbandiger Onset für stabile Beat-Kandidaten.

    Die Schätzung ist unabhängig von den bekannten Referenz-BPM. Verschiedene
    Frequenzbänder helfen, wenn ein Subbass einen Offbeat betont.
    """
    import librosa
    import numpy as np

    spectrum = np.abs(librosa.stft(y=y, n_fft=1024, hop_length=hop))
    frequencies = librosa.fft_frequencies(sr=sr, n_fft=1024)

    def band(low, high):
        part = spectrum[(frequencies >= low) & (frequencies < high)]
        if not part.size:
            return np.zeros(spectrum.shape[1], dtype=float)
        energy = np.sqrt(np.mean(part * part, axis=0))
        derivative = np.diff(np.log1p(10 * energy), prepend=0)
        return np.maximum(derivative, 0)

    # Frequenznormierung verhindert, dass ein einzelner lauter Kick alle
    # anderen Instrumente im Breitband-Onset verdrängt.
    whitened = spectrum / (np.mean(spectrum, axis=1, keepdims=True) + 1e-5)
    flux = np.maximum(np.diff(np.log1p(whitened), axis=1,
                              prepend=whitened[:, :1]), 0).mean(axis=0)
    return {"kick": band(35, 165), "snare": band(220, 2400), "flux": flux}


def _beat_autocorrelation_198(onsets, fps, grid):
    """Vergleicht Schlag-, Doppel- und Viertaktperiode auf derselben BPM-Skala."""
    import numpy as np

    signal = np.asarray(onsets, dtype=np.float64)
    if len(signal) < fps * 9 or not np.isfinite(signal).all():
        return np.zeros_like(grid)
    signal = np.maximum(signal, 0)
    if not np.any(signal):
        return np.zeros_like(grid)
    signal = np.clip(signal, 0, np.quantile(signal, .98))
    if signal.max() < 1e-8:
        return np.zeros_like(grid)
    signal -= signal.mean()
    n = len(signal)
    spectrum = np.fft.rfft(signal, n=2*n)
    ac = np.fft.irfft(spectrum * spectrum.conj())[:n]
    ac /= np.maximum(n - np.arange(n), 1)
    ac /= max(float(ac[0]), 1e-9)
    x = np.arange(n)
    lag = 60 * fps / grid
    interpolate = lambda t: np.interp(t, x, ac, left=0, right=0)
    return (interpolate(lag) + .35 * interpolate(2*lag) +
            .12 * interpolate(4*lag) + .05 * interpolate(.5*lag))


def _arrangement_recurrence_198(y, sr=11025, hop=256):
    """FFT-Autokorrelation normierter Frequenzbänder für längere Loop-Muster.

    Ein Vier-Takt-Muster kann echte 93 BPM von einem stark betonten 124er
    Unterteilungspuls unterscheiden; bei uneindeutigen Songs ist es kein
    absoluter Beweis für die Taktart.
    """
    import numpy as np
    import librosa

    spectrum = np.abs(librosa.stft(y=y, n_fft=2048, hop_length=hop))
    freqs = librosa.fft_frequencies(sr=sr, n_fft=2048)
    bands = np.geomspace(50, 5000, 36)
    features = []
    for low, high in zip(bands[:-1], bands[1:]):
        band = spectrum[(freqs >= low) & (freqs < high)]
        if band.size:
            features.append(np.log1p(np.mean(band, axis=0)))
    if not features:
        return np.array([], dtype=float)
    feature = np.vstack(features)
    feature -= feature.mean(axis=1, keepdims=True)
    feature /= np.maximum(feature.std(axis=1, keepdims=True), 1e-7)
    n = feature.shape[1]
    # Kanäle in einer FFT bündeln statt pro Frequenzband die FFT erneut zu rechnen.
    ft = np.fft.rfft(feature, n=2*n, axis=1)
    autocorr = np.fft.irfft(ft * ft.conj(), axis=1)[:, :n].mean(axis=0)
    return autocorr / np.maximum(n - np.arange(n), 1)


def estimate_bpm_multiscale_198(audio_segments, sr=11025, hop=256, percussion_only=False):
    """BPM-Kandidaten über Kick, Gesamt-Onsets und Vier-Takt-Loops bewerten.

    Wichtig: 80 / 160 und 93 / 124 werden aus tatsächlich gemessenen Mustern
    entschieden, nicht anhand fester Regeln auf bestimmte BPM umgerechnet.
    Der Bereich 65–190 BPM ist bewusst begrenzt; außerhalb bleibt die manuelle
    Korrektur möglich. Kein Verfahren kann Doubletime in jedem Song eindeutig
    bestimmen. Rückgabe ist ein ganzzahliger Schätzwert oder 0 bei fehlendem Puls.
    """
    import numpy as np
    from scipy.signal import find_peaks

    grid = np.arange(65.0, 191.0, .5)
    fps = sr / hop
    envelopes = []
    recurrence = []
    for y in audio_segments:
        if len(y) < sr * 12 or not np.all(np.isfinite(y)):
            continue
        env = _beat_envelopes_198(y, sr, hop)
        # Leere/perkussionsarme Ausschnitte tragen nichts zur BPM bei.
        if np.max(env["flux"]) < 1e-6:
            continue
        envelopes.append(env)
        recurrence.append(_arrangement_recurrence_198(y, sr, hop))
    if not envelopes:
        return 0.0

    segment_scores = [
        {name: _beat_autocorrelation_198(part[name], fps, grid)
         for name in ("kick", "flux", "snare")}
        for part in envelopes
    ]
    scores = {name: np.mean([part[name] for part in segment_scores], axis=0)
              for name in ("kick", "flux", "snare")}
    if max(scores["kick"].max(), scores["flux"].max(),
           scores["snare"].max()) < .07:
        return 0.0
    # Mehrere Kandidaten statt ausschließlich des dominanten Kick-Pulses.
    candidates = []
    for name, count in (("kick", 3), ("flux", 3), ("snare", 2)):
        peaks, _ = find_peaks(scores[name], distance=5)
        for idx in sorted(peaks, key=lambda i: scores[name][i], reverse=True)[:count]:
            candidate = float(grid[idx])
            if not any(abs(candidate - other) < 2.1 for other in candidates):
                candidates.append(candidate)
    if not candidates:
        return 0.0

    # Nur Fenster gleicher Länge gemeinsam mitteln (die üblichen 30 s).
    rec_length = min(len(r) for r in recurrence)
    rec = np.mean([r[:rec_length] for r in recurrence], axis=0)
    lags = np.arange(rec_length) / fps
    mask = (lags >= 4.0) & (lags <= 14.0)
    rec_peak = float(np.max(rec[mask])) if np.any(mask) else 0.0
    if rec_peak <= 1e-8:
        rec_peak = 1.0

    kick_max = max(float(scores["kick"].max()), 1e-9)
    wide_max = max(float(scores["flux"].max()), 1e-9)
    ranked = []
    for candidate in candidates:
        idx = int(np.argmin(abs(grid-candidate)))
        # 16 Beat-Ereignisse = vier Takte in 4/4-Takt. +-2 Frames
        center = int(round(960.0/candidate*fps))
        rec_strength = float(max(rec[max(0, center-2):center+3], default=0)) / rec_peak
        kick_strength = float(scores["kick"][idx]/kick_max)
        wide_strength = float(scores["flux"][idx]/wide_max)
        # Fast ausschließlich perkussive Loops: Die Kick ist ein besseres
        # Tempo-Signal als eine von Hi-Hats/Snares dominierte Loop-Erkennung.
        if percussion_only:
            combined = .20*rec_strength + .90*kick_strength + .06*wide_strength
        else:
            combined = 1.35*rec_strength + .45*kick_strength + .15*wide_strength
        ranked.append((combined, candidate))
    ranked.sort(reverse=True)
    global_choice = float(ranked[0][1])

    # Gegenprobe für Remixe: Ein Loop kann rhythmisch im Verhältnis 2:3 oder
    # 3:4 wiederkehren und die Vier-Takt-Autokorrelation irreführen. Nur wenn
    # ein unabhängig von der Kick gemessener Breitband-Onset-Puls deutlich
    # stärker für den zweitplatzierten Kandidaten spricht und sein kombinierter
    # Score dem Sieger nahekommt, wählen wir den alternativen Puls.
    # Halftime/Doubletime bleibt ausdrücklich unentschieden: keine pauschale
    # Halbierung/Verdopplung.
    if len(segment_scores) >= 3 and len(ranked) >= 2:
        best_score, best_bpm = ranked[0]
        for alternate_score, alternate_bpm in ranked[1:]:
            ratio = max(best_bpm, alternate_bpm) / min(best_bpm, alternate_bpm)
            if abs(ratio - 2.0) < .08:
                continue
            if alternate_score < best_score * .73:
                continue
            best_idx = int(np.argmin(abs(grid-best_bpm)))
            other_idx = int(np.argmin(abs(grid-alternate_bpm)))
            best_flux = float(scores["flux"][best_idx])/wide_max
            other_flux = float(scores["flux"][other_idx])/wide_max
            # Ein klarer, über die Abschnitte stabiler Drum-Groove soll Vorrang
            # vor einer einzigen dominanten Loop-Periode bekommen.
            flux_support = sum(
                float(parts["flux"][other_idx]) > float(parts["flux"][best_idx])
                for parts in segment_scores)
            if (other_flux >= best_flux + .12 and other_flux > .65
                    and flux_support >= 2):
                global_choice = alternate_bpm
                break
    return float(int(round(global_choice)))


# Harmonisch identische Paralleltonarten teilen dieselben sieben Tonklassen.
KEY_SCALE_NOTES = {}
for _note_idx, _root in enumerate(KEY_NAMES):
    for _mode, _steps in (("Major", (0,2,4,5,7,9,11)),
                          ("Minor", (0,2,3,5,7,8,10))):
        KEY_SCALE_NOTES[f"{_root} {_mode}"] = frozenset(
            (_note_idx + step) % 12 for step in _steps)

def analyze_track(path, length, with_diagnostics=False):
    """BPM/Key: eingebettete Metadaten bevorzugen, sonst Audiomerkmale vergleichen.

    Für BPM liefern Low-End-Kick und breitbandige Transienten getrennte Stimmen;
    für Key wird ein zeitlich gemitteltes, normalisiertes Harmonie-Chroma benutzt.
    """
    import librosa
    import numpy as np

    tag_bpm, tag_key = read_bpm_key_tags(path)
    sr, hop = 22050, 256
    onset_curves, onset_weights, kick_curves, chroma_groups = [], [], [], []
    tempo_segments = []
    percussion_ratios = []
    for offset, dur in pick_segments(length):
        y, _ = librosa.load(path, sr=sr, mono=True, offset=offset, duration=dur)
        if len(y) < 5 * sr or np.max(np.abs(y)) < 1e-5:
            continue
        y = np.asarray(y, dtype=np.float32)
        y_harm, y_perc = librosa.effects.hpss(y, margin=(2.0, 3.0))
        perc_rms = float(np.sqrt(np.mean(y_perc * y_perc)))
        harm_rms = float(np.sqrt(np.mean(y_harm * y_harm)))
        total_rms = float(np.sqrt(np.mean(y * y)))
        # Reine Melodie-/Akkordflächen enthalten zwar Tonwechsel, aber keinen
        # zuverlässig messbaren Beat. Keine Fantasie-BPM daraus erzeugen.
        if not tag_bpm and perc_rms >= max(total_rms * .06, 1e-6):
            # Rhythmus wird auf mehreren Frequenzbändern und über volle
            # Vier-Takt-Muster verglichen, nicht nur über Bass-Attacken.
            if len(y) >= 12 * sr:
                tempo_segments.append(librosa.resample(y, orig_sr=sr, target_sr=11025))
                percussion_ratios.append(harm_rms / max(perc_rms, 1e-9))
            kick = _low_frequency_onsets(y, sr, hop)
            kick_curves.append(kick)
            onset_curves.append(kick)
            onset_weights.append(2.4 if np.count_nonzero(kick > np.max(kick)*.20) >= 7 else .5)
            onset_curves.append(librosa.onset.onset_strength(y=y_perc, sr=sr,
                              hop_length=hop, aggregate=np.median))
            onset_weights.append(.95)
            onset_curves.append(librosa.onset.onset_strength(y=y, sr=sr,
                              hop_length=hop, aggregate=np.median))
            onset_weights.append(.65)
        if tag_key:
            continue
        # Rein perkussive Geräusche (z.B. Kick mit tonalem Nachklang) liefern
        # keine verlässliche Dur-/Moll-Tonart. Verhindert Fantasie-Key bei Drumloops.
        if harm_rms <= max(perc_rms * .07, 1e-5):
            continue
        # Eine tiefe Kick kann vom HPSS teilweise als harmonisch einsortiert
        # werden. Ohne weitere harmonische Obertöne ist kein Key verlässlich.
        spectrum = np.abs(librosa.stft(y=y_harm, n_fft=2048, hop_length=512))
        freqs = librosa.fft_frequencies(sr=sr, n_fft=2048)
        harmonic_power = float(np.sum(spectrum * spectrum)) + 1e-12
        bright_power = float(np.sum((spectrum[freqs >= 165])**2))
        if bright_power / harmonic_power < .003:
            continue
        try:
            tuning = float(librosa.estimate_tuning(y=y_harm, sr=sr, bins_per_octave=36))
            if not np.isfinite(tuning):
                tuning = 0.0
        except (ValueError, FloatingPointError):
            tuning = 0.0
        chroma_groups.append(librosa.feature.chroma_cqt(
            y=y_harm, sr=sr, hop_length=hop, bins_per_octave=36,
            tuning=tuning, norm=None))
    if tag_bpm:
        bpm = float(tag_bpm)
    else:
        # Ensemble: breite Spektral-Onsets + Bass + Loop-Wiederholung.
        # Wenn keine valide Perkussion erkannt wird, kein Fantasie-Tempo.
        nearly_only_drums = bool(percussion_ratios) and float(np.median(percussion_ratios)) < .18
        bpm = estimate_bpm_multiscale_198(tempo_segments, percussion_only=nearly_only_drums)
        if not bpm and onset_curves:
            bpm = estimate_bpm_from_envelopes(onset_curves, sr/hop, onset_weights)
    key = tag_key or estimate_key_from_chromas(chroma_groups)
    if not with_diagnostics:
        return bpm, key
    # Diagnostik: Stimmen separate Abschnitte mit dem Gesamtergebnis überein?
    # Dies sind Plausibilitätsindikatoren, KEINE kalibrierten Wahrscheinlichkeiten.
    def tempo_matches(candidate, result):
        if not candidate or not result:
            return False
        return any(abs(candidate * factor - result) <= max(2.0, result*.015)
                   for factor in (0.5, 1.0, 2.0))
    bpm_uncertain = None
    if tag_bpm:
        bpm_uncertain = 0
    elif bpm and len(tempo_segments) >= 2:
        segment_bpms = [estimate_bpm_multiscale_198([segment])
                        for segment in tempo_segments]
        count = sum(tempo_matches(one, bpm) for one in segment_bpms)
        bpm_uncertain = int(count < 2)
    key_uncertain = None
    if tag_key:
        key_uncertain = 0
    elif key and len(chroma_groups) >= 2:
        individual_keys = [estimate_key_from_chromas([c]) for c in chroma_groups]
        # Paralleltonarten teilen alle Tonklassen und sind für Remixe kompatibel.
        def same_scale(a, b):
            def notes(label):
                if not label:
                    return None
                return frozenset(KEY_SCALE_NOTES.get(label, ()))
            return bool(notes(a)) and notes(a) == notes(b)
        key_uncertain = int(sum(same_scale(candidate, key) for candidate in individual_keys) < 2)
    return bpm, key, bpm_uncertain, key_uncertain


def text_key(text):
    """Sortierschlüssel: Groß-/Kleinschreibung und Akzente (Ä -> A) werden ignoriert."""
    t = unicodedata.normalize("NFKD", str(text or "")).casefold()
    return "".join(ch for ch in t if not unicodedata.combining(ch))


def sort_rows(rows, col, desc):
    """Sortiert Tabellenzeilen (path, title, year, length, bpm, tonart).
    Titel/KEY alphabetisch, Jahr/Dauer/BPM numerisch. Leere Werte stehen immer
    unten, gleiche Werte bleiben nach Titel (A-Z) geordnet."""
    idx = SORT_INDEX[col]

    def value(r):
        v = r[idx]
        if col in ("title", "tonart", "genre", "camelot", "format"):
            return text_key(v) or None
        if col == "rating":
            return int(v) if v else None
        if col == "year":
            return int(v) if str(v).strip().isdigit() else None
        return float(v) if v else None

    keyed, missing = [], []
    for r in rows:
        k = value(r)
        (missing if k is None else keyed).append((k, r))
    keyed.sort(key=lambda t: text_key(t[1][1]))
    keyed.sort(key=lambda t: t[0], reverse=desc)
    missing.sort(key=lambda t: text_key(t[1][1]))
    return [r for _, r in keyed + missing]


CAMELOT_MAJOR = {1: "B", 2: "F#", 3: "C#", 4: "G#", 5: "D#", 6: "A#",
                 7: "F", 8: "C", 9: "G", 10: "D", 11: "A", 12: "E"}
CAMELOT_MINOR = {1: "G#", 2: "D#", 3: "A#", 4: "F", 5: "C", 6: "G",
                 7: "D", 8: "A", 9: "E", 10: "B", 11: "F#", 12: "C#"}
FLAT_TO_SHARP = {"C": "B", "D": "C#", "E": "D#", "F": "E", "G": "F#", "A": "G#", "B": "A#"}




def camelot_code(key):
    """Konvertiert die erkannte Tonart in das Camelot-System."""
    if not key:
        return ""
    parts = str(key).split()
    if len(parts) != 2:
        return ""
    note, mode = parts
    mapping = CAMELOT_MINOR if mode == "Minor" else CAMELOT_MAJOR if mode == "Major" else {}
    return next((f"{number}{'A' if mode == 'Minor' else 'B'}"
                 for number, name in mapping.items() if name == note), "")

def parse_bpm(text):
    """BPM aus einem Datei-Tag lesen (nur plausible Werte 40-250)."""
    try:
        v = float(str(text).replace(",", ".").strip())
    except ValueError:
        return 0.0
    return round(v, 1) if 40 <= v <= 250 else 0.0


def parse_key(text):
    """Tonart-Tag in das Format 'C Major' / 'A Minor' bringen.
    Erkennt z. B. 'Am', 'C#', 'F# minor', 'Bb major' und Camelot-Codes ('8A')."""
    t = str(text or "").strip().replace("♯", "#").replace("♭", "b")
    if not t:
        return ""
    m = re.fullmatch(r"0?(\d{1,2})([ABab])", t.replace(" ", ""))
    if m and 1 <= int(m.group(1)) <= 12:
        minor = m.group(2).upper() == "A"
        n = int(m.group(1))
        return f"{(CAMELOT_MINOR if minor else CAMELOT_MAJOR)[n]} {'Minor' if minor else 'Major'}"
    m = re.fullmatch(r"([A-Ga-g])([#b]?)\s*(.*)", t)
    if not m:
        return ""
    note, acc, rest = m.group(1).upper(), m.group(2), m.group(3).strip().lower()
    if acc == "b":
        note = FLAT_TO_SHARP[note]
    elif acc == "#":
        note = {"E#": "F", "B#": "C"}.get(note + "#", note + "#")
    if rest in ("", "maj", "major", "dur"):
        mode = "Major"
    elif rest in ("m", "min", "minor", "moll"):
        mode = "Minor"
    else:
        return ""
    return f"{note} {mode}" if note in KEY_NAMES else ""


def read_bpm_key_tags(path):
    """Liest BPM und Tonart aus den Datei-Tags (falls vorhanden), sonst (0, '')."""
    try:
        audio = MutagenFile(path, easy=True)
        if audio is None:
            return 0.0, ""
        bpm = parse_bpm((audio.get("bpm") or [""])[0])
        key = ""
        for name in ("initialkey", "key"):
            vals = audio.get(name)
            if vals:
                key = parse_key(vals[0])
                if key:
                    break
        return bpm, key
    except Exception:
        return 0.0, ""


def read_tags(path: Path):
    title, artist, album, year, length, genre = path.stem, "Unbekannt", "Unbekannt", "", 0, ""
    try:
        audio = MutagenFile(path, easy=True)
        if audio is not None:
            title = audio.get("title", [title])[0]
            artist = audio.get("artist", [artist])[0]
            album = audio.get("album", [album])[0]
            year = str(audio.get("date", [""])[0])[:4]
            length = audio.info.length
            genre = str((audio.get("genre") or [""])[0])
    except Exception:
        pass
    return title, artist, album, year, length, genre


_IMG_CACHE = {}


def smooth_shape(w, h, radius, color):
    """Gerundetes Rechteck (Pille/Kreis) als PNG mit weichen, transparenten Kanten.
    Tk zeichnet Formen sonst ohne Kantenglättung, das wirkt treppig."""
    key = (w, h, radius, color)
    if key in _IMG_CACHE:
        return _IMG_CACHE[key]
    r8, g8, b8 = (int(color[i:i + 2], 16) for i in (1, 3, 5))
    hw, hh = w / 2, h / 2
    raw = bytearray()
    for y in range(h):
        raw.append(0)                                  # PNG-Filter "keiner"
        py = y + 0.5 - hh
        for x in range(w):
            px = x + 0.5 - hw
            qx, qy = abs(px) - (hw - radius), abs(py) - (hh - radius)
            dist = math.hypot(max(qx, 0), max(qy, 0)) + min(max(qx, qy), 0) - radius
            alpha = min(max(0.5 - dist, 0.0), 1.0)
            raw += bytes((r8, g8, b8, int(alpha * 255 + 0.5)))

    def chunk(kind, data):
        body = kind + data
        return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)

    png = (b"\x89PNG\r\n\x1a\n"
           + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
           + chunk(b"IDAT", zlib.compress(bytes(raw)))
           + chunk(b"IEND", b""))
    img = tk.PhotoImage(data=base64.b64encode(png).decode("ascii"))
    _IMG_CACHE[key] = img
    return img


