_THEME_IMAGE_CACHE = {}


def _mix_rgb(a, b, t):
    return tuple(round(a[i] + (b[i] - a[i]) * t) for i in range(3))


def _rgb(hexcode):
    from PIL import ImageColor
    return ImageColor.getrgb(hexcode)


def _neon_pill_image(w, h, color):
    """Gezeichnete, kanten-geglattete Gradienten statt flacher Tk-Rechtecke."""
    from PIL import Image, ImageDraw
    w, h = int(w), int(h)
    cache_key = (w, h, color)
    item = _THEME_IMAGE_CACHE.get(cache_key)
    if item is not None:
        return item
    factor = 3
    bw, bh = w * factor, h * factor
    base = _rgb(color)
    if color.upper() in (ACTION_YELLOW, ACTION_YELLOW_HOVER):
        upper = _mix_rgb(base, (255, 255, 255), .13)
        lower = _mix_rgb(base, (255, 255, 255), .02)
        border = _mix_rgb(base, (255, 255, 255), .34)
    else:
        upper = tuple(min(255, int(v * .96 + 21)) for v in base)
        lower = tuple(max(0, int(v * .70)) for v in base)
        border = tuple(min(255, int(v * .92 + 47)) for v in base)
    im = Image.new('RGBA', (bw, bh), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    for yy in range(bh):
        t = yy / max(1, bh - 1)
        d.line((0, yy, bw - 1, yy), fill=(*_mix_rgb(upper, lower, t), 255))
    mask = Image.new('L', (bw, bh), 0)
    md = ImageDraw.Draw(mask)
    md.rounded_rectangle((0, 0, bw - 1, bh - 1), radius=bh // 2, fill=255)
    im.putalpha(mask)
    ImageDraw.Draw(im).rounded_rectangle((2, 2, bw - 3, bh - 3),
                                         radius=bh // 2, outline=(*border, 130),
                                         width=2)
    im = im.resize((w, h), Image.Resampling.LANCZOS)
    # PhotoImage must be made with an existing Tk root; the caller holds refs.
    if len(_THEME_IMAGE_CACHE) > 220:
        _THEME_IMAGE_CACHE.clear()
    _THEME_IMAGE_CACHE[cache_key] = im
    return im


def _render_neon_backdrop_reference(w, h, kind):
    """Build a diffuse, antialiased wallpaper once, never on a live resize.

    Multiple blurred layers are composited before the sharp center strands.
    Unlike the older polygon ribbons there is no hard filled boundary.
    """
    from PIL import Image, ImageDraw, ImageFilter
    import math
    w,h=max(2,int(w)),max(2,int(h))
    palettes={
      'top':((23,12,51),(29,12,58)),
      'sidebar':((25,13,54),(19,11,43)),
      'player':((24,13,52),(29,15,61)),
    }
    start,end=palettes.get(kind,((21,12,46),(17,10,39)))
    im=Image.new('RGBA',(w,h),start+(255,))
    paint=ImageDraw.Draw(im)
    for y in range(h):
        f=y/max(1,h-1)
        col=_mix_rgb(start,end,f)
        paint.line((0,y,w,y), fill=col+(255,))

    if kind == 'top':
        # Large blurred colors overlap well beyond the visible area, so there
        # can be no abrupt visible boundary or hard gradient band.
        wash=Image.new('RGBA',(w,h),(0,0,0,0))
        d=ImageDraw.Draw(wash)
        d.ellipse((int(w*.31),-h*2,int(w*1.44),int(h*2.1)),
                  fill=(123,24,182,165))
        d.ellipse((int(w*.63),-h*1.05,int(w*1.30),int(h*1.27)),
                  fill=(171,31,213,95))
        im=Image.alpha_composite(im,wash.filter(ImageFilter.GaussianBlur(46)))
        z=3
        layer=Image.new('RGBA',(w*z,h*z),(0,0,0,0))
        glow=ImageDraw.Draw(layer)
        curve=[]
        for x in range(round(w*.35*z),w*z+3,3):
            t=x/(w*z)
            u=max(0.0,min(1.0,(t-.35)/.65))
            ease=u*u*(3-2*u)
            y=(.96-.87*ease)*h*z
            curve.append((x,round(y)))
        if curve:
            glow.line(curve,fill=(199,67,250,235),width=11*z,joint='curve')
            soft=layer.resize((w,h),Image.Resampling.LANCZOS)
            for blur in (19,7):
                im=Image.alpha_composite(im,soft.filter(ImageFilter.GaussianBlur(blur)))
            core=Image.new('RGBA',(w*z,h*z),(0,0,0,0))
            ImageDraw.Draw(core).line(curve,fill=(244,150,255,245),width=3*z,joint='curve')
            im=Image.alpha_composite(im,core.resize((w,h),Image.Resampling.LANCZOS))
            # Light secondary strand, soft enough not to form another band.
            thin=Image.new('RGBA',(w*z,h*z),(0,0,0,0))
            ImageDraw.Draw(thin).line([(x,y+15*z) for x,y in curve],
                fill=(148,58,214,135),width=2*z,joint='curve')
            im=Image.alpha_composite(im,thin.resize((w,h),Image.Resampling.LANCZOS))
    elif kind == 'sidebar':
        z=3
        W,H=w*z,h*z
        curve=[]
        for x in range(-4,W+5,2):
            t=x/max(1,W)
            y=h*(.83-.080*math.exp(-((t-.39)/.24)**2)
                   +.032*math.exp(-((t-.84)/.14)**2))*z
            curve.append((x,round(y)))
        def stroke(offset,opacity,width):
            layer=Image.new('RGBA',(W,H),(0,0,0,0))
            d=ImageDraw.Draw(layer)
            for (x0,y0),(x1,y1) in zip(curve,curve[1:]):
                t=max(0,min(1,(x0+x1)/(2*W)))
                fade=min(1,t*7,(1-t)*6)
                rgb=_mix_rgb((64,133,255),(222,79,245),t)
                d.line((x0,y0+offset*z,x1,y1+offset*z),
                       fill=(*rgb,int(opacity*fade)),width=width*z)
            return layer.resize((w,h),Image.Resampling.LANCZOS)
        path=stroke(0,230,6)
        for blur in (12,5):
            im=Image.alpha_composite(im,path.filter(ImageFilter.GaussianBlur(blur)))
        im=Image.alpha_composite(im,stroke(0,250,3))
        im=Image.alpha_composite(im,stroke(7,95,1))
        # A second diffuse companion strand adds depth without a filled area.
        secondary=stroke(-11,75,2).filter(ImageFilter.GaussianBlur(4))
        im=Image.alpha_composite(im,secondary)
    elif kind == 'player':
        glow=Image.new('RGBA',(w,h),(0,0,0,0))
        d=ImageDraw.Draw(glow)
        d.ellipse((w*.16,-h*2,w*.84,h*1.9),fill=(118,32,198,85))
        im=Image.alpha_composite(im,glow.filter(ImageFilter.GaussianBlur(44)))
    return im.convert('RGB')

# A small set of antialiased master wallpapers is rendered once. Each exact
# window size is then produced by Pillow's fast native resize instead of
# re-blurring several million pixels for every <Configure> event.
from functools import lru_cache as _ui_lru_cache

@_ui_lru_cache(maxsize=4)
def _neon_reference(kind):
    sizes = {'top': (1550, 96), 'sidebar': (188, 860),
             'player': (1450, 96)}
    w, h = sizes.get(kind, (1200, 500))
    return _render_neon_backdrop_reference(w,h,kind)

@_ui_lru_cache(maxsize=18)
def _neon_backdrop_image(w,h,kind):
    from PIL import Image
    w,h = max(2,min(int(w),3500)),max(2,min(int(h),1900))
    master = _neon_reference(kind)
    if master.size == (w,h):
        return master
    return master.resize((w,h),Image.Resampling.BILINEAR)


@_ui_lru_cache(maxsize=2)
def _neon_edge_master(kind):
    from PIL import Image,ImageDraw
    width=2048
    im=Image.new('RGB',(width,3))
    pen=ImageDraw.Draw(im)
    for x in range(width):
        t=x/(width-1)
        if kind=='toolbar':
            rgb=_mix_rgb((73,34,129),(214,63,248),t)
        else:
            rgb=_mix_rgb((62,30,107),(165,54,225),1-abs(2*t-1))
        pen.line((x,0,x,2),fill=rgb)
    return im

@_ui_lru_cache(maxsize=32)
def _neon_edge_image(width,kind):
    from PIL import Image
    width=max(2,min(4000,int(width)))
    return _neon_edge_master(kind).resize((width,3),Image.Resampling.BILINEAR)

class NeonBackdrop(tk.Canvas):
    """Once-per-size ImageTk renderer; no redraw loops running in the idle path."""
    def __init__(self, master, kind, immediate=False, **kw):
        super().__init__(master, highlightthickness=0, bd=0, bg=SURFACE, **kw)
        self.kind, self._photo, self._draw_job, self._painted = kind, None, None, None
        self.immediate = immediate
        self.bind('<Configure>', self._schedule)

    def background_crop(self, x, y, width, height):
        # The toolbar keeps its original, independently scaled neon artwork.
        image = _neon_backdrop_image(self.winfo_width(), self.winfo_height(), self.kind)
        return image.crop((x, y, x + width, y + height))

    def _schedule(self, event=None):
        # Throttling statt Debouncing: beim manuellen Ziehen bleiben die
        # Neon-Hintergruende sichtbar und werden ca. 30-mal/s aktualisiert.
        # Wiederholte Configure-Ereignisse starten keinen neuen Timer.
        if self._draw_job is None:
            self._draw_job = self.after_idle(self._paint) if self.immediate else self.after(65, self._paint)

    def _paint(self):
        from PIL import ImageTk
        self._draw_job = None
        w, h = self.winfo_width(), self.winfo_height()
        signature = (w, h)
        if w < 4 or h < 4 or self._painted == signature:
            return
        self._painted = signature
        self._photo = ImageTk.PhotoImage(self.background_crop(0, 0, w, h), master=self)
        self.delete('all')
        self.create_image(0, 0, anchor='nw', image=self._photo)


SIDEBAR_ACCENTS = {
    'library': ACTION_YELLOW, 'flp': '#FF892A', 'player': '#BF6BFF',
    'analysis': '#F197ED', 'stats': '#70D9FF', 'settings': '#B8BAC4', 'updates': '#8DE7BC',
}


def _nav_photo(page, active, master):
    """Vector-drawn 23px icons so Windows does not show missing-glyph boxes."""
    from PIL import Image, ImageDraw, ImageTk
    import math
    z = 4
    im = Image.new('RGBA', (24*z, 24*z), (0,0,0,0))
    d = ImageDraw.Draw(im)
    col = _rgb(SIDEBAR_ACCENTS[page] if active else '#DDD0FD')
    col = (*col, 255)
    stroke = 2.2*z
    def line(points, width=stroke):
        d.line([(int(x*z),int(y*z)) for x,y in points], fill=col,
               width=int(width), joint='curve')
    def rect(box, width=stroke, fill=None):
        d.rounded_rectangle(tuple(int(v*z) for v in box),radius=2*z,
                            outline=col,width=int(width),fill=fill)
    if page == 'library':
        d.ellipse((8*z, 4*z, 22*z, 18*z), outline=col, width=2*z)
        rect((2, 6, 16, 21), width=2*z, fill='#3B205F' if active else '#1B1037')
        d.ellipse((5*z, 9*z, 13*z, 17*z), outline=col, width=z)
        d.ellipse((8*z, 12*z, 10*z, 14*z), fill=col)
    elif page == 'flp':
        for x,y in ((5,9),(12,15),(19,7)):
            line([(x,3),(x,21)],width=1.8*z)
            d.rounded_rectangle((int((x-2.7)*z),int((y-2)*z),
                                 int((x+2.7)*z),int((y+2)*z)),radius=int(1.5*z),
                                fill=col)
    elif page == 'analysis':
        line([(2,12),(5,12),(7.5,7),(10,18),(13,5),(16,15),(18,11),(22,11)])
    elif page == 'player':
        d.ellipse((2*z,2*z,22*z,22*z),outline=col,width=int(stroke))
        d.polygon([(9*z,7*z),(9*z,17*z),(17*z,12*z)],fill=col)
    elif page == 'stats':
        d.rounded_rectangle((3*z,12*z,7*z,21*z),radius=z,fill=col)
        d.rounded_rectangle((10*z,8*z,14*z,21*z),radius=z,fill=col)
        d.rounded_rectangle((17*z,3*z,21*z,21*z),radius=z,fill=col)
    elif page == 'updates':
        line([(12,3),(12,15)],width=2.2*z)
        line([(7,10),(12,16),(17,10)],width=2.2*z)
        line([(4,18),(4,21),(20,21),(20,18)],width=2.0*z)
    elif page == 'settings':
        points = []
        for tooth in range(6):
            angle = math.tau * tooth / 6
            for offset, radius in ((-.50, 8), (-.27, 10), (.27, 10), (.50, 8)):
                a = angle + offset * math.tau / 6
                points.append((round((12 + radius * math.cos(a)) * z),
                               round((12 + radius * math.sin(a)) * z)))
        d.polygon(points, fill=col if active else None, outline=col, width=2*z)
        d.ellipse((9*z, 9*z, 15*z, 15*z), fill=(0, 0, 0, 0), outline=None if active else col,
                  width=z)
    im=im.resize((24,24),Image.Resampling.LANCZOS)
    return ImageTk.PhotoImage(im, master=master)


class _TopOverlay(tk.Canvas):
    """Pixel-matched toolbar ornament with a real transparent appearance."""
    def __init__(self, master, width, height):
        super().__init__(master, width=width, height=height, bd=0,
                         highlightthickness=0, cursor='arrow', bg=SURFACE)
        self._background_photo=None
        self._overlay_job=None
        self._overlay_signature=None
        self._overlay_dirty=True
        self.bind('<Configure>', self._schedule_overlay)
        master.bind('<Configure>',self._schedule_overlay,add='+')

    def _schedule_overlay(self,event=None):
        # During a continuous window drag both the toolbar and its children
        # receive Configure events. Repainting on each creates a resize storm.
        root = self.winfo_toplevel()
        if getattr(root, '_resizing_window', False):
            if self._overlay_job is None:
                self._overlay_job = self.after(70, self._paint_overlay)
            return
        if self._overlay_job is not None:
            try:self.after_cancel(self._overlay_job)
            except tk.TclError:pass
            self._overlay_job = None
        if event is not None and event.widget is self:
            self._paint_overlay()
        else:
            self._overlay_job = self.after_idle(self._paint_overlay)

    def _paint_overlay(self):
        self._overlay_job=None
        if not self.winfo_exists() or not self.master.winfo_exists():
            return
        w,h=self.winfo_width(),self.winfo_height()
        pw,ph=self.master.winfo_width(),self.master.winfo_height()
        if min(w,h,pw,ph)<3:return
        x,y=self.winfo_x(),self.winfo_y()
        signature = (w, h, pw, ph, x, y)
        moved = signature != self._overlay_signature
        if not moved and not self._overlay_dirty:
            return
        if moved:
            from PIL import ImageTk
            self._overlay_signature = signature
            crop = self.master.background_crop(x, y, w, h)
            self._background_photo = ImageTk.PhotoImage(crop, master=self)
            if not hasattr(self, '_backdrop_item'):
                self._backdrop_item = self.create_image(0, 0, anchor='nw', image=self._background_photo)
            else:
                self.itemconfigure(self._backdrop_item, image=self._background_photo)
        if self._overlay_dirty or moved:
            self._overlay_dirty = False
            self.delete('foreground')
            self._paint_foreground()
            for item in self.find_all():
                if item != self._backdrop_item:
                    self.addtag_withtag('foreground', item)

    def _paint_foreground(self):
        pass

class _TopCount(_TopOverlay):
    def __init__(self,master):
        self._text=''
        super().__init__(master, width=155,height=36)

    def config(self,cnf=None,**kw):
        if 'text' in kw:
            changed=str(kw['text'])!=self._text
            self._text=str(kw.pop('text'))
            if changed:
                self._overlay_dirty=True
                self._paint_overlay()
        if cnf is not None or kw:
            return super().config(cnf,**kw)

    configure=config

    def _paint_foreground(self):
        self.create_text(self.winfo_width()-3,self.winfo_height()/2,
                         text=self._text,anchor='e',fill='#E3C5FF',
                         font=(getattr(self.winfo_toplevel(),'ui_font','Segoe UI'),11,'bold'))

class _TopSearch(_TopOverlay):
    def __init__(self,master,command):
        self._hover=False
        self._command=command
        super().__init__(master,width=43,height=37)
        self.configure(cursor='hand2')
        self.bind('<Enter>',lambda e:self._set_hover(True))
        self.bind('<Leave>',lambda e:self._set_hover(False))
        self.bind('<ButtonRelease-1>',lambda e:self._command()
                  if 0<=e.x<self.winfo_width() and 0<=e.y<self.winfo_height() else None)

    def _set_hover(self,value):
        if value!=self._hover:
            self._hover=value
            self._overlay_dirty=True
            self._paint_overlay()

    def _paint_foreground(self):
        from PIL import Image,ImageDraw,ImageTk,ImageFilter
        z=4;w=self.winfo_width();h=self.winfo_height()
        im=Image.new('RGBA',(w*z,h*z),(0,0,0,0))
        d=ImageDraw.Draw(im)
        cx,cy=w*z//2,h*z//2
        if self._hover:
            glow=Image.new('RGBA',im.size,(0,0,0,0))
            gd=ImageDraw.Draw(glow)
            gd.ellipse((cx-15*z,cy-15*z,cx+15*z,cy+15*z),fill=(168,63,221,180))
            im=Image.alpha_composite(im,glow.filter(ImageFilter.GaussianBlur(6*z)))
            d=ImageDraw.Draw(im)
        color=(227,195,255,255)
        d.ellipse((cx-10*z,cy-10*z,cx+5*z,cy+5*z),
                  outline=color,width=int(2.8*z))
        d.line((cx+3*z,cy+4*z,cx+11*z,cy+12*z),fill=color,width=int(3*z))
        self._icon_photo=ImageTk.PhotoImage(im.resize((w,h),Image.Resampling.LANCZOS),master=self)
        self.create_image(0,0,image=self._icon_photo,anchor='nw')


class Pill(tk.Canvas):
    """Abgerundeter Button (Pille, bei gleicher Breite und Höhe ein Kreis)."""

    def __init__(self, master, text, command, w=110, h=34, fill=SURFACE2, fg=TEXT,
                 hover=HOVER, bg=BG, font=("Segoe UI", 10)):
        super().__init__(master, width=w, height=h, bg=bg, highlightthickness=0,
                         bd=0, cursor="hand2")
        self.text, self.command, self.w, self.h = text, command, w, h
        self.fill, self.fg, self.hover, self.font = fill, fg, hover, font
        if fill == ACTION_YELLOW and hover == HOVER:
            self.hover = ACTION_YELLOW_HOVER
        self._rendered_button = None
        self._draw(fill)
        self.bind("<Enter>", lambda e: self._draw(self.hover))
        self.bind("<Leave>", lambda e: self._draw(self.fill))
        self.bind("<ButtonRelease-1>", self._click)

    def _draw(self, color):
        state = (color, self.fill, self.text, self.fg, self.font, self.w, self.h,
                 getattr(self, "_matching_backdrop", None))
        if state == self._rendered_button:
            return
        self._rendered_button = state
        self.delete("all")
        from PIL import ImageTk
        image = _neon_pill_image(self.w, self.h, color)
        backdrop = getattr(self, "_matching_backdrop", None)
        if backdrop is not None:
            from PIL import Image
            image = Image.alpha_composite(
                backdrop.resize(image.size, Image.Resampling.LANCZOS).convert("RGBA"), image)
        self._ui_button_photo = ImageTk.PhotoImage(image, master=self)
        self.create_image(0, 0, anchor="nw", image=self._ui_button_photo)
        if self.text in ('▶','⏸','⏮','⏭'):
            from PIL import ImageTk
            kind={'▶':'play','⏸':'pause','⏮':'prev','⏭':'next'}[self.text]
            self._smooth_transport_photo=ImageTk.PhotoImage(_mixer_transport_icon(
                kind,self.w,self.h,BG if self.fill==ACTION_YELLOW else '#E9D6F7'),master=self)
            self.create_image(0,0,image=self._smooth_transport_photo,anchor='nw')
        elif self.text == "•••":
            # Three true circles, not a font glyph with an asymmetric baseline.
            center_x, center_y = self.w / 2, self.h / 2
            for x in (center_x-9, center_x, center_x+9):
                self.create_oval(x-2.0, center_y-2.0, x+2.0, center_y+2.0,
                                 fill=self.fg, outline="")
        else:
            self.create_text(self.w / 2, self.h / 2, text=self.text,
                             fill=self.fg, font=self.font)

    def _click(self, event):
        if 0 <= event.x <= self.w and 0 <= event.y <= self.h:
            self.command()

    def set_text(self, text):
        self.text = text
        self._draw(self.fill)



class LibraryPill(Pill):
    """Modernes, abgerundetes Filter-Chip mit echtem Zwei-Farben-Verlauf."""

    _gradient_cache = {}

    def _draw(self, color):
        from PIL import Image, ImageDraw, ImageTk
        self.delete("all")
        active = color.lower() == YELLOW.lower()
        base = color.lower()
        if active:
            start, end, stroke = (255, 248, 175), _rgb(ACTION_YELLOW), (255, 252, 209)
        elif base in ("#342057", "#42256e", "#4e2982"):
            start, end, stroke = (104, 57, 163), (61, 34, 104), (119, 66, 176)
        else:
            start, end, stroke = (48, 32, 86), (33, 24, 68), (75, 49, 115)
        key = (self.w, self.h, start, end, stroke)
        if key not in self._gradient_cache:
            scale = 3
            w, h = self.w*scale, self.h*scale
            img = Image.new("RGBA", (w,h), (0,0,0,0))
            px = img.load()
            for y in range(h):
                t = y / max(1,h-1)
                c = tuple(round(start[i]*(1-t) + end[i]*t) for i in range(3))
                for x in range(w):
                    px[x,y] = (*c,255)
            mask = Image.new("L",(w,h),0)
            md = ImageDraw.Draw(mask)
            md.rounded_rectangle((1,1,w-2,h-2),radius=h//2,fill=255)
            img.putalpha(mask)
            d = ImageDraw.Draw(img)
            d.rounded_rectangle((2,2,w-3,h-3),radius=h//2,outline=(*stroke,220),width=2)
            img = img.resize((self.w,self.h),Image.Resampling.LANCZOS)
            self._gradient_cache[key]=ImageTk.PhotoImage(img,master=self)
        self._gradient_image=self._gradient_cache[key]
        self.create_image(0,0,anchor="nw",image=self._gradient_image)
        self.create_text(self.w/2,self.h/2,text=self.text,fill=self.fg,
                         font=self.font)



class SearchBox(tk.Canvas):
    """Abgerundetes Suchfeld mit Platzhalter 'Suchen...' und lila Rand bei Fokus."""

    def __init__(self, master, on_change, placeholder="Suchen...", w=250, h=36, bg=BG):
        super().__init__(master, width=w, height=h, bg=bg, highlightthickness=0, bd=0)
        self.w, self.h, self.placeholder, self.on_change = w, h, placeholder, on_change
        self.entry = tk.Entry(self, bd=0, relief="flat", highlightthickness=0, bg=SURFACE,
                              fg=MUTED, insertbackground=YELLOW, selectbackground=VIOLET,
                              selectforeground=YELLOW, font=(getattr(master.winfo_toplevel(),"ui_font","Segoe UI"), 10))
        self._entry_window = self.create_window(15, h / 2, window=self.entry, anchor="w",
                           width=w - 30, height=h - 15)
        self._ph = True
        self._search_backdrop_photo=None
        self._search_backdrop_job=None
        self._search_backdrop_geometry = None
        self._last_query = ""
        self.bind('<Configure>',self._schedule_matching_backdrop,add='+')
        self.master.bind('<Configure>',self._schedule_matching_backdrop,add='+')
        self._draw(False)
        self._show_placeholder()
        self.entry.bind("<FocusIn>", self._focus_in)
        self.entry.bind("<FocusOut>", self._focus_out)
        self.entry.bind("<KeyRelease>", self._query_changed)
        for sequence in ("<<Paste>>", "<<Cut>>"):
            self.entry.bind(sequence, lambda e: self.after_idle(self._query_changed))

    def _query_changed(self, event=None):
        query = self.text()
        if query != self._last_query:
            self._last_query = query
            self.on_change(query)

    def _schedule_matching_backdrop(self,event=None):
        if self._search_backdrop_job is not None:
            try:self.after_cancel(self._search_backdrop_job)
            except tk.TclError:pass
        self._search_backdrop_job=self.after_idle(self._refresh_matching_backdrop)

    def _refresh_matching_backdrop(self):
        """Exact pixel-matched topbar crop, hiding Tk Canvas rectangular edges."""
        self._search_backdrop_job=None
        if not self.winfo_exists() or not self.winfo_ismapped():return
        w,h=self.winfo_width(),self.winfo_height()
        pw,ph=self.master.winfo_width(),self.master.winfo_height()
        if min(w,h,pw,ph)<3:return
        x,y=self.winfo_x(),self.winfo_y()
        geometry = (x, y, w, h, pw, ph)
        if geometry == self._search_backdrop_geometry:
            return
        self._search_backdrop_geometry = geometry
        from PIL import ImageTk
        crop = self.master.background_crop(x, y, w, h)
        self._search_backdrop_photo=ImageTk.PhotoImage(crop,master=self)
        self.delete('backdrop')
        self.create_image(0,0,image=self._search_backdrop_photo,anchor='nw',tags='backdrop')
        self.tag_lower('backdrop')
        self.tag_raise('shape','backdrop')

    def _draw(self, focused):
        self.delete("shape")
        ring = "#C08AFF" if focused else "#8453B6"
        self.create_image(0, 0, anchor="nw", tags="shape",
                          image=smooth_shape(self.w, self.h, self.h / 2, ring))
        self.create_image(2, 2, anchor="nw", tags="shape",
                          image=smooth_shape(self.w - 4, self.h - 4, (self.h - 4) / 2, SURFACE))
        self.tag_lower("shape")
        if self.find_withtag("backdrop"):
            self.tag_lower("backdrop")

    def _show_placeholder(self):
        self._ph = True
        self.entry.delete(0, "end")
        self.entry.insert(0, self.placeholder)
        self.entry.config(fg=MUTED)

    def _focus_in(self, event):
        if self._ph:
            self.entry.delete(0, "end")
            self.entry.config(fg=TEXT)
            self._ph = False
        self._draw(True)

    def _focus_out(self, event):
        if not self.entry.get().strip():
            self._show_placeholder()
        self._draw(False)

    def text(self):
        return "" if self._ph else self.entry.get().strip()


class Slider(tk.Canvas):
    """Schlanker Regler: Schiene, farbiger Fortschritt und runder Knopf (mit weichen Kanten).
    Die Callbacks bekommen den Wert (0 bis maximum)."""
    PAD = 10

    def __init__(self, master, maximum=1.0, value=0.0, bg=BG, on_press=None,
                 on_drag=None, on_release=None, **kw):
        super().__init__(master, height=26, bg=bg, highlightthickness=0, bd=0,
                         cursor="hand2", **kw)
        self.maximum, self.value = max(float(maximum), 1e-9), float(value)
        self.enabled, self.dragging = False, False
        self.on_press, self.on_drag, self.on_release = on_press, on_drag, on_release
        self.bind("<Configure>", lambda e: self.redraw())
        self.bind("<ButtonPress-1>", self._press)
        self.bind("<B1-Motion>", self._drag)
        self.bind("<ButtonRelease-1>", self._release)

    def _value_at(self, x):
        span = max(self.winfo_width() - 2 * self.PAD, 1)
        return min(max((x - self.PAD) / span, 0.0), 1.0) * self.maximum

    def _press(self, event):
        if self.enabled:
            self.dragging = True
            self.set(self._value_at(event.x))
            if self.on_press:
                self.on_press(self.value)

    def _drag(self, event):
        if self.dragging:
            self.set(self._value_at(event.x))
            if self.on_drag:
                self.on_drag(self.value)

    def _release(self, event):
        if self.dragging:
            self.dragging = False
            self.set(self._value_at(event.x))
            if self.on_release:
                self.on_release(self.value)

    def set(self, value):
        self.value = min(max(float(value), 0.0), self.maximum)
        self.redraw()

    def get(self):
        return self.value

    def set_max(self, maximum):
        self.maximum = max(float(maximum), 1e-9)
        self.value = min(self.value, self.maximum)
        self.redraw()

    def enable(self, on=True):
        self.enabled = on
        if not on:
            self.dragging = False
        self.redraw()

    def _bar(self, xa, xb, cy, color):
        """Runde Schiene: weiche Endkappen (Bild) + gerades Mittelstück."""
        cap = smooth_shape(6, 6, 3, color)
        self.create_image(xa, cy, image=cap)
        self.create_image(xb, cy, image=cap)
        self.create_rectangle(xa, cy - 3, xb, cy + 3, fill=color, outline="")

    def redraw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.winfo_height()
        if w <= 1:
            return
        x0, x1, cy = self.PAD, w - self.PAD, h // 2
        xv = x0 + (x1 - x0) * self.value / self.maximum
        self._bar(x0, x1, cy, TRACK)
        if xv > x0:
            self._bar(x0, xv, cy, PURPLE)
        self.create_oval(xv-9,cy-9,xv+9,cy+9,fill=self.cget('bg'),outline='')
        knob = smooth_shape(16, 16, 8, YELLOW if self.enabled else MUTED)
        self.create_image(round(xv), cy, image=knob)


