def _mean_dict(values):
    out = {}
    if not values:
        return out
    for key in values[0]:
        out[key] = sum(v.get(key, 0.0) for v in values) / len(values)
    return out


def _score_prompt_groups(audio, prompt_groups):
    labels, owners = [], []
    for owner, prompts in prompt_groups.items():
        for prompt in prompts:
            labels.append(prompt)
            owners.append(owner)
    predictions = _AUDIO_CLASSIFIER(audio, candidate_labels=labels)
    by_label = {row["label"]: float(row["score"]) for row in predictions}
    totals, counts = {k: 0.0 for k in prompt_groups}, {k: 0 for k in prompt_groups}
    for owner, prompt in zip(owners, labels):
        totals[owner] += by_label.get(prompt, 0.0)
        counts[owner] += 1
    return {owner: totals[owner] / max(1, counts[owner]) for owner in prompt_groups}


def _audio_profile(y, sr):
    import numpy as np
    import librosa
    onset = librosa.onset.onset_strength(y=y, sr=sr)
    local_tempo = float(librosa.feature.tempo(onset_envelope=onset, sr=sr).mean()) if len(onset) else 0.0
    centroid = float(np.mean(librosa.feature.spectral_centroid(y=y, sr=sr))) / (sr / 2.0)
    rolloff = float(np.mean(librosa.feature.spectral_rolloff(y=y, sr=sr, roll_percent=0.90))) / (sr / 2.0)
    zcr = float(np.mean(librosa.feature.zero_crossing_rate(y)))
    rms = float(np.mean(librosa.feature.rms(y=y)))
    harm, perc = librosa.effects.hpss(y)
    harm_rms = float(np.mean(librosa.feature.rms(y=harm))) + 1e-9
    perc_rms = float(np.mean(librosa.feature.rms(y=perc))) + 1e-9
    return {
        "tempo": local_tempo,
        "brightness": 0.55 * centroid + 0.45 * rolloff,
        "centroid": centroid,
        "zcr": zcr,
        "rms": rms,
        "harm_ratio": harm_rms / max(perc_rms, 1e-9),
        "perc_ratio": perc_rms / max(harm_rms, 1e-9),
    }


def _bump(scores, key, amount):
    if key in scores:
        scores[key] += amount


def select_moods_from_scores(mood_rows):
    """Konservative, reproduzierbare CLAP-Auswahl mit Abstention.

    Die CLAP-Softmax-Scores sind nur relative Ähnlichkeiten, keine
    Wahrscheinlichkeiten. Einzelne dominante Adjektive dürfen nicht ungeprüft
    als Mood gespeichert werden. Bei fehlender Übereinstimmung bleibt das
    Ergebnis leer (bisheriger Wert bleibt in der DB erhalten).
    """
    import math
    valid = []
    for row in mood_rows:
        if not row:
            continue
        clean = {m: max(0., float(row.get(m, 0.))) for m in MOOD_AUTO_OPTIONS
                 if math.isfinite(float(row.get(m, 0.)))}
        if clean:
            valid.append(clean)
    if not valid:
        return ""
    count = len(valid)
    averages = _mean_dict(valid)
    ranked = sorted(averages, key=averages.get, reverse=True)

    def support(label, limit=3):
        return sum(label in sorted(row, key=row.get, reverse=True)[:limit]
                   for row in valid)

    required = max(2, (count+1)//2) if count >= 2 else 1
    primary = ranked[0]
    runner = ranked[1] if len(ranked) > 1 else None
    # Nur bei mehrfacher Wiederholung und erkennbarem Abstand sicher genug.
    # Bei knapper Wahl leeres Mood-Feld statt zufälligem Adjektiv.
    if support(primary, 2) < required:
        return ""
    if runner is not None and averages[primary] < averages[runner]*1.075:
        if support(primary, 1) < required:
            return ""

    # „Fröhlich“ insbesondere bei Instrumentals nur wenn es wirklich eine
    # deutliche Mehrheitsentscheidung ist (kein pauschaler Score-Abzug).
    if primary == "Fröhlich" and runner is not None:
        if (support(primary, 1) < required
                or averages[primary] < averages[runner]*1.14):
            return ""

    # Der zweite Mood muss eigenständig stabil und fast gleich stark sein.
    if count < 2 or not runner:
        return primary
    for second in ranked[1:]:
        if frozenset((primary, second)) in MOOD_INCOMPATIBLE:
            continue
        if (primary in MOOD_ENERGY) == (second in MOOD_ENERGY):
            continue
        if support(second, 2) < required:
            continue
        if averages[second] < averages[primary]*.94:
            continue
        if second == "Fröhlich":
            if support(second, 1) < required:
                continue
        return f"{primary} · {second}"
    return primary


def classify_genre_mood(path, length, known_bpm=0.0):
    """CLAP-Genre/Mood ohne starre Tempo-/Klangfarben-Vorurteile.

    Alle Genres werden mit derselben Promptmenge verglichen; dadurch werden
    Untergenres nicht schon durch eine unsichere Familien-Vorentscheidung
    ausgeschlossen. Mehrere Ausschnitte mindern zufällige Ausreißer. CLAP-
    Ähnlichkeitsscores sind KEINE kalibrierten Wahrscheinlichkeiten.
    """
    global _AUDIO_CLASSIFIER
    import numpy as np
    import librosa
    if _AUDIO_CLASSIFIER is None:
        from transformers import pipeline
        _AUDIO_CLASSIFIER = pipeline(
            "zero-shot-audio-classification",
            model="laion/clap-htsat-unfused", device=-1)

    # CLAP arbeitet mit 48 kHz. Bis zu 3 Stellen des Songs, keine Stille.
    sr = 48000
    offsets = [max(0, float(length or 60) * p - 7.5)
               for p in (0.20, 0.50, 0.80)]
    chunks, family_rows, genre_rows, mood_rows = [], [], [], []
    for offset in offsets:
        y, _ = librosa.load(path, sr=sr, mono=True, offset=offset, duration=15.0)
        if len(y) < sr * 4 or np.max(np.abs(y)) < 1e-5:
            continue
        # Keine Lautstärke-Boosts bei bereits normalisierten Songs erforderlich.
        y = np.ascontiguousarray(y.astype(np.float32))
        chunks.append(y)
        family_rows.append(_score_prompt_groups(y, FAMILY_PROMPTS))
        genre_rows.append(_score_prompt_groups(y, GENRE_PROMPTS))
        mood_rows.append(_score_prompt_groups(y, {m: MOOD_PROMPTS[m] for m in MOOD_AUTO_OPTIONS}))
    if not chunks:
        return "", ""

    # Jede Menge von Kandidaten wird innerhalb derselben CLAP-Abfrage bewertet.
    family = _mean_dict(family_rows)
    genres = _mean_dict(genre_rows)
    moods = _mean_dict(mood_rows)
    family_max = max(family.values(), default=0.0)
    for name in genres:
        parent = GENRE_TO_FAMILY.get(name)
        if parent and family_max > 0:
            # Maximal 16% relativer Prior, statt feste +0.03 bis +0.05
            # Zuschläge bei Tempo >120 bzw. dunklem Klang.
            relative = max(0.0, family.get(parent, 0) / family_max)
            genres[name] *= .92 + .16 * relative

    def stable_top(rows, totals, minimum_ratio):
        if not totals:
            return ""
        ranking = sorted(totals, key=totals.get, reverse=True)
        top = ranking[0]
        if len(ranking) < 2:
            return top
        runner = ranking[1]
        top_votes = sum(max(r, key=r.get) == top for r in rows if r)
        # Knappes, in den Ausschnitten unstetes Ergebnis lieber nicht als
        # sichere Genre-Zuweisung speichern. Bestehende Korrekturen bleiben.
        if top_votes <= 1 and totals[top] < totals[runner]*minimum_ratio:
            return ""
        return top

    genre = stable_top(genre_rows, genres, 1.09)
    mood = select_moods_from_scores(mood_rows)
    return genre, mood



EQ_BANDS = (60, 180, 650, 2500, 9000)
EQ_NEUTRAL = (0.0,) * len(EQ_BANDS)
EQ_PRESETS = {
    'Neutral': EQ_NEUTRAL,
    'Mehr Bass': (5, 3, 0, -1, 0),
    'Klarere Stimmen': (-2, -1, 1, 4, 1),
    'Mehr Höhen': (0, 0, -1, 1, 5),
}


class PlaybackError(RuntimeError):
    pass


def equalizer_coefficients(rate, gains, np):
    """Normalisierte Peaking-Biquads für die aktiven Bänder."""
    from math import cos, pi, sin

    sections = []
    for hz, gain in zip(EQ_BANDS, gains):
        if not gain or hz >= rate * .46:
            continue
        amplitude = 10 ** (gain / 40)
        omega = 2 * pi * hz / rate
        alpha = sin(omega) / 2  # Q = 1
        a0 = 1 + alpha / amplitude
        center = -2 * cos(omega)
        sections.append(((1 + alpha * amplitude) / a0, center / a0,
                         (1 - alpha * amplitude) / a0, 1, center / a0,
                         (1 - alpha / amplitude) / a0))
    return np.array(sections, dtype=np.float64).reshape((-1, 6))


class EqualizerFilter:
    def __init__(self, rate, np, signal):
        self.rate, self.np, self.signal = rate, np, signal
        self.gains = EQ_NEUTRAL
        self.sections = None
        self.state = None
        self.headroom = 1.0

    def _process(self, block, volume):
        if self.sections is None:
            return block * volume if volume != 1.0 else block
        output, self.state = self.signal.sosfilt(self.sections, block, axis=0, zi=self.state)
        return output * min(volume, self.headroom)

    def process(self, block, gains, volume=1.0):
        if gains == self.gains:
            return self._process(block, volume)
        previous = self._process(block, volume)
        self.gains = gains
        sections = equalizer_coefficients(self.rate, gains, self.np)
        if sections.size:
            _, response = self.signal.sosfreqz(sections, worN=1024)
            self.headroom = 1 / max(1.0, float(self.np.max(self.np.abs(response))))
            self.sections = sections
            self.state = self.np.zeros((len(sections), 2, block.shape[1]))
        else:
            self.sections = None
            self.state = None
            self.headroom = 1.0
        current = self._process(block, volume).copy()
        count = min(len(block), max(2, self.rate // 80))
        fade = self.np.linspace(0.0, 1.0, count)[:, None]
        current[:count] = previous[:count] * (1 - fade) + current[:count] * fade
        return current



def find_audio_ffmpeg():
    try:
        import imageio_ffmpeg
        return imageio_ffmpeg.get_ffmpeg_exe()
    except (ImportError, OSError, RuntimeError):
        from shutil import which
        return which('ffmpeg')


def sound_lab_filters(rate, tempo, semitones, frames):
    filters = []
    adjusted_rate = round(rate * 2 ** (semitones / 12))
    pitch_ratio = adjusted_rate / rate
    if adjusted_rate != rate:
        filters.extend((f'aresample={rate}', f'asetrate={adjusted_rate}', f'aresample={rate}'))
    factor = tempo / pitch_ratio
    while factor < .5:
        filters.append('atempo=0.5')
        factor *= 2
    while factor > 2:
        filters.append('atempo=2')
        factor /= 2
    if abs(factor - 1) > 1e-8:
        filters.append(f'atempo={factor:.10f}')
    filters.extend((f'apad=whole_len={frames}', f'atrim=end_sample={frames}'))
    return filters


def sound_lab_blocks(path, start, end, rate, tempo, semitones, ffmpeg, np, decoder, blocksize):
    """Stereo-PCM-Blöcke für Live-Ausgabe und Export. Positionen beziehen sich auf die Quelle."""
    if tempo == 1 and semitones == 0:
        with decoder.SoundFile(path) as reader:
            first = min(reader.frames, round(start * rate))
            last = min(reader.frames, round(end * rate))
            reader.seek(first)
            while reader.tell() < last:
                block = reader.read(min(blocksize, last - reader.tell()), dtype='float32', always_2d=True)
                if not len(block):
                    break
                if block.shape[1] == 1:
                    block = np.repeat(block, 2, axis=1)
                elif block.shape[1] > 2:
                    block = np.column_stack((block[:, ::2].mean(axis=1), block[:, 1::2].mean(axis=1)))
                yield block
        return
    if not ffmpeg:
        raise PlaybackError('Für Tempo und Tonhöhe ist imageio-ffmpeg erforderlich.')
    import subprocess
    import tempfile

    source_frames = max(1, round(end * rate) - round(start * rate))
    output_frames = max(1, round(source_frames / tempo))
    filters = ','.join((f'atrim=end_sample={source_frames}',
                        *sound_lab_filters(rate, tempo, semitones, output_frames)))
    command = [ffmpeg, '-hide_banner', '-loglevel', 'error', '-nostdin',
               '-protocol_whitelist', 'file,pipe', '-ss', f'{start:.9f}',
               '-i', str(Path(path).resolve()), '-map', '0:a:0',
               '-af', filters, '-ac', '2', '-ar', str(rate), '-f', 'f32le', 'pipe:1']
    flags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
    with tempfile.TemporaryFile() as errors:
        process = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                   stderr=errors, creationflags=flags)
        try:
            while True:
                raw = process.stdout.read(blocksize * 8)
                if not raw:
                    break
                if len(raw) % 8:
                    raise PlaybackError('Die Audioverarbeitung lieferte einen unvollständigen Block.')
                yield np.frombuffer(raw, dtype='<f4').reshape(-1, 2).copy()
            if process.wait():
                errors.seek(0)
                detail = errors.read(400).decode('utf-8', errors='replace').strip()
                raise PlaybackError(detail or 'FFmpeg konnte die Datei nicht verarbeiten.')
        finally:
            if process.poll() is None:
                process.kill()
            process.stdout.close()
            process.wait()


def filtered_audio_block(block, equalizer, gains, volume, np):
    np.nan_to_num(block, copy=False, nan=0.0, posinf=0.0, neginf=0.0)
    result = equalizer.process(block, gains, volume)
    return np.ascontiguousarray(np.clip(result, -1, 1), dtype=np.float32)


def export_sound_lab(source, target, start, end, tempo, semitones, gains, ffmpeg, cancel, progress):
    """Exportiert PCM-24-WAV und veröffentlicht die fertige Datei ohne Überschreiben."""
    from contextlib import closing
    import tempfile
    import numpy as np
    import soundfile as decoder
    from scipy import signal

    source, target = Path(source), Path(target)
    if source.resolve() == target.resolve() or target.exists():
        raise FileExistsError('Der Dateiname ist bereits vergeben. Wähle bitte einen anderen.')
    info = decoder.info(source)
    rate = info.samplerate
    start = max(0.0, start)
    end = min(info.frames / rate, end)
    if end <= start:
        raise PlaybackError('Der gewählte Ausschnitt ist leer.')
    frames = max(1, round((end - start) * rate / tempo))
    eq = EqualizerFilter(rate, np, signal)
    fd, name = tempfile.mkstemp(prefix='.kln-export-', suffix='.part', dir=target.parent)
    os.close(fd)
    temporary = Path(name)
    try:
        written = 0
        with decoder.SoundFile(temporary, 'w', samplerate=rate, channels=2,
                               format='WAV', subtype='PCM_24') as writer:
            with closing(sound_lab_blocks(source, start, end, rate, tempo, semitones,
                                          ffmpeg, np, decoder, max(256, round(rate * .018)))) as blocks:
                for block in blocks:
                    if cancel.is_set():
                        return False
                    writer.write(filtered_audio_block(block, eq, gains, 1.0, np))
                    written += len(block)
                    progress(min(.99, written / frames))
        if cancel.is_set():
            return False
        if not written:
            raise PlaybackError('Der gewählte Ausschnitt enthält kein Audio.')
        if os.name == 'nt':
            temporary.rename(target)
        else:
            os.link(temporary, target)
        progress(1.0)
        return True
    finally:
        temporary.unlink(missing_ok=True)


class StreamAudio:
    """Eine Audiowarteschleife. Dateizugriff und Ausgabe laufen außerhalb von Tk."""

    supports_eq = True

    def __init__(self):
        from threading import Condition, Thread
        import numpy as np
        import sounddevice as device
        import soundfile as decoder
        from scipy import signal

        try:
            device.check_output_settings(channels=2, dtype='float32')
        except device.PortAudioError as exc:
            raise PlaybackError(str(exc)) from exc
        self.np, self.device, self.decoder, self.signal = np, device, decoder, signal
        self.condition = Condition()
        self.path = None
        self.duration = 0.0
        self.position = 0.0
        self.revision = 0
        self.running = False
        self.closed = False
        self.volume = .7
        self.gains = EQ_NEUTRAL
        self.tempo, self.semitones, self.loop = 1.0, 0, None
        self.ffmpeg = None
        self.error = None
        self.thread = Thread(target=self._worker, name='KLN-Audio', daemon=True)
        self.thread.start()

    def load(self, path):
        try:
            info = self.decoder.info(path)
            if info.frames <= 0 or info.samplerate <= 0:
                raise PlaybackError('Die Audiodatei enthält keine Samples.')
        except (RuntimeError, OSError) as exc:
            raise PlaybackError(str(exc)) from exc
        with self.condition:
            self.path = path
            self.duration = info.frames / info.samplerate
            self._set_transport(0.0, False)
        return self.duration

    def _set_transport(self, position, running):
        self.position = position
        self.running = running
        self.error = None
        self.revision += 1
        self.condition.notify_all()

    def play(self, position=0.0, paused=False):
        with self.condition:
            if self.path is not None:
                position = min(self.duration, max(0.0, position))
                if self.loop and not self.loop[0] <= position < self.loop[1]:
                    position = self.loop[0]
                self._set_transport(position, not paused)

    def pause(self):
        with self.condition:
            if self.running:
                self._set_transport(self.position, False)

    def resume(self):
        with self.condition:
            if self.path is not None and not self.running:
                self._set_transport(self.position, True)

    def stop(self):
        with self.condition:
            self.path = None
            self._set_transport(0.0, False)

    def set_volume(self, value):
        with self.condition:
            self.volume = value

    def set_eq(self, gains):
        with self.condition:
            self.gains = gains

    def set_lab(self, tempo, semitones, loop):
        with self.condition:
            if (tempo, semitones, loop) == (self.tempo, self.semitones, self.loop):
                return
            self.tempo, self.semitones, self.loop = tempo, semitones, loop
            position = self.position
            if loop and not loop[0] <= position < loop[1]:
                position = loop[0]
            self._set_transport(position, self.running)

    def current_pos(self):
        with self.condition:
            return self.position

    def get_busy(self):
        with self.condition:
            return self.running

    def pop_error(self):
        with self.condition:
            error, self.error = self.error, None
            return error

    def close(self):
        with self.condition:
            self.closed = True
            self.condition.notify_all()
        self.thread.join(timeout=.65)

    def _worker(self):
        while True:
            with self.condition:
                self.condition.wait_for(lambda: self.closed or self.running)
                if self.closed:
                    return
                revision, path, position = self.revision, self.path, self.position
            try:
                self._stream(revision, path, position)
            except (RuntimeError, OSError, ValueError, self.device.PortAudioError) as exc:
                with self.condition:
                    if revision == self.revision and not self.closed:
                        self.error = str(exc)
            finally:
                with self.condition:
                    if revision == self.revision:
                        self.running = False

    def _stream(self, revision, path, position):
        from contextlib import closing

        info = self.decoder.info(path)
        rate = info.samplerate
        duration = info.frames / rate
        with self.condition:
            if self.closed or revision != self.revision:
                return
            tempo, semitones, loop = self.tempo, self.semitones, self.loop
        limit = min(duration, loop[1]) if loop else duration
        eq = EqualizerFilter(rate, self.np, self.signal)
        blocksize = max(256, round(rate * .018))
        stream = self.device.OutputStream(samplerate=rate, channels=2, dtype='float32',
                                           blocksize=blocksize, latency='low')
        drained = False
        try:
            with self.condition:
                if self.closed or revision != self.revision:
                    return
            stream.start()
            while True:
                played = 0
                with closing(sound_lab_blocks(path, position, limit, rate, tempo, semitones,
                                              self.ffmpeg, self.np, self.decoder, blocksize)) as blocks:
                    for block in blocks:
                        with self.condition:
                            if self.closed or revision != self.revision:
                                return
                            gains, volume = self.gains, self.volume
                        output = filtered_audio_block(block, eq, gains, volume, self.np)
                        stream.write(output)
                        played += len(block)
                        with self.condition:
                            if revision == self.revision:
                                elapsed = max(0.0, played / rate - stream.latency)
                                self.position = min(limit, position + elapsed * tempo)
                with self.condition:
                    if self.closed or revision != self.revision:
                        return
                if not loop or not played:
                    break
                position = loop[0]
            stream.stop()
            drained = True
            with self.condition:
                if revision == self.revision:
                    self.position = duration
        finally:
            try:
                if not drained and stream.active:
                    stream.abort()
            finally:
                stream.close()


class PygameAudio:
    supports_eq = False

    def __init__(self):
        self.music = None
        self.error = None
        self.offset = 0.0
        self.frozen_position = None
        try:
            import pygame
            pygame.mixer.init()
            self.music = pygame.mixer.music
            self.exception = pygame.error
        except (ImportError, OSError, RuntimeError) as exc:
            self.error = str(exc)

    def load(self, path):
        if self.music is None:
            raise PlaybackError(self.error or 'Keine Audioausgabe verfügbar.')
        try:
            self.music.load(path)
        except self.exception as exc:
            raise PlaybackError(str(exc)) from exc
        self.offset = 0.0
        self.frozen_position = None
        return 0.0

    def play(self, position=0.0, paused=False):
        try:
            if position:
                self.music.play(start=position)
            else:
                self.music.play()
        except (self.exception, NotImplementedError) as exc:
            raise PlaybackError(str(exc)) from exc
        self.offset = position
        self.frozen_position = None
        if paused:
            self.pause()

    def pause(self):
        self.frozen_position = self.current_pos()
        self.music.pause()

    def resume(self):
        self.music.unpause()
        self.frozen_position = None

    def stop(self):
        if self.music is not None:
            self.music.stop()
        self.offset, self.frozen_position = 0.0, None

    def set_volume(self, value):
        if self.music is not None:
            self.music.set_volume(value)

    def set_eq(self, gains):
        pass

    def current_pos(self):
        if self.frozen_position is not None:
            return self.frozen_position
        return self.offset + (max(0, self.music.get_pos()) / 1000 if self.music else 0.0)

    def get_busy(self):
        return bool(self.music and self.music.get_busy())

    def pop_error(self):
        return None

    def close(self):
        self.stop()


def read_waveform(path, cancelled, buckets=320):
    """Minima und Maxima ohne Laden der gesamten Datei in den Arbeitsspeicher."""
    import numpy as np
    import soundfile as sf

    with sf.SoundFile(path) as reader:
        if reader.frames <= 0:
            return ()
        peaks = np.zeros(buckets, dtype=np.float32)
        position = 0
        while not cancelled.is_set():
            block = reader.read(65536, dtype='float32', always_2d=True)
            if not len(block):
                return tuple(float(peak) for peak in peaks)
            indexes = (np.arange(position, position + len(block), dtype=np.int64)
                       * buckets // reader.frames)
            indexes = np.minimum(buckets - 1, indexes)
            amplitudes = np.max(np.abs(block), axis=1)
            # Indizes sind monoton: reduceat arbeitet in nativen NumPy-Loops
            # und vermeidet langsame einzelne indexed-at Updates pro Sample.
            starts = np.r_[0, np.flatnonzero(np.diff(indexes)) + 1]
            group_peaks = np.maximum.reduceat(amplitudes, starts)
            locations = indexes[starts]
            peaks[locations] = np.maximum(peaks[locations], group_peaks)
            position += len(block)
        return ()


# Versionsunabhaengiger, dateisignaturgebundener Cache ausschliesslich fuer
# abgeleitete Pegelwerte. Keine Musikdaten werden geaendert oder verschoben.
def _wave_disk_file(key):
    import hashlib
    import json
    fingerprint = json.dumps(key, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    return Path.home() / '.meine_mediathek_waveform_cache' / (hashlib.sha256(fingerprint).hexdigest() + '.json')


def _wave_disk_read(key):
    import json
    try:
        path = _wave_disk_file(key)
        if path.stat().st_size > 12000:
            return None
        data = json.loads(path.read_text(encoding='utf-8'))
        if isinstance(data, list) and len(data) == 320 and all(
                isinstance(x, (int, float)) and 0 <= x <= 1.01 for x in data):
            return tuple(float(x) for x in data)
    except (OSError, ValueError, TypeError):
        pass
    return None


def _wave_disk_write(key, peaks):
    import json
    import os
    import tempfile
    if len(peaks) != 320:
        return
    target = _wave_disk_file(key)
    tmp = None
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=target.parent,
                                         prefix='.wave-', suffix='.tmp', delete=False) as handle:
            tmp = handle.name
            json.dump(list(peaks), handle, separators=(',', ':'))
        os.replace(tmp, target)
        tmp = None
    except (OSError, ValueError, TypeError):
        pass
    finally:
        if tmp:
            try:
                os.unlink(tmp)
            except OSError:
                pass



class PlayerWaveform(tk.Canvas):
    """Neon-Waveform: cached audio data, static PIL glow, lightweight animated light.

    Only the moving shimmer and playhead animate; the waveform itself is NEVER
    recomputed on an animation frame. On resize, expensive paint is coalesced.
    """

    def __init__(self, parent, seek, preview):
        super().__init__(parent, height=136, bg='#25173D', highlightthickness=0,
                         bd=0, takefocus=True, cursor='hand2')
        self.seek, self.preview = seek, preview
        self.duration = self.position = 0.0
        self.peaks, self.message = (), ''
        self.dragging = False
        self.bars = []
        self.lab_markers = (None, None, False)
        self.cover_tint = None
        self.colored = 0
        self._wave_size = self._wave_pending = None
        self._levels_key = None
        self._anim_job = None
        self._animated_items = set()
        self._beam_photo = None
        self._beam_item = None
        self._glow_background_photo = None
        self._last_animation_time = 0.0
        self._animated_phase = 0.0
        self._bar_active_colors = []
        self._bar_idle_colors = []
        self._last_playhead_x = None
        self._glow_frame_cache = {}
        self._anim_mode = 'idle'
        self.bind('<Configure>', self._wave_configure)
        self.bind('<Map>', lambda event: self._start_animation())
        self.bind('<Unmap>', lambda event: self._stop_animation())
        self.bind('<Destroy>', lambda event: self._stop_animation() if event.widget is self else None)
        self.bind('<Button-1>', self._start_drag)
        self.bind('<B1-Motion>', self._drag)
        self.bind('<ButtonRelease-1>', self._release)
        self.bind('<Motion>', self._hover)
        self.bind('<Leave>', lambda event: self.delete('hover'))

    @staticmethod
    def _mix(a, b, p):
        def decode(c):
            return tuple(int(c[i:i+2], 16) for i in (1, 3, 5))
        x, y = decode(a), decode(b)
        return '#' + ''.join(f'{max(0, min(255, round(v*(1-p)+u*p))):02x}' for v, u in zip(x, y))

    def _wave_configure(self, event):
        size = (event.width, event.height)
        if size == self._wave_size:
            return
        if self._wave_pending is None:
            self._wave_pending = self.after(55, self._wave_flush)

    def _wave_flush(self):
        self._wave_pending = None
        size = (self.winfo_width(), self.winfo_height())
        if size == self._wave_size:
            return
        old = self._wave_size
        root = self.winfo_toplevel()
        if (getattr(root, '_resizing_window', False) and old
                and min(old) > 25 and min(size) > 25 and self.find_all()):
            self.scale('all', 0, 0, size[0] / old[0], size[1] / old[1])
            self._wave_size = size
            self._resize_scaled = True
            self._move_playhead(self.position)
            return
        self._render()

    def finish_resize(self):
        if getattr(self, '_resize_scaled', False):
            self._resize_scaled = False
            self._render()

    def set_track(self, duration, peaks=(), message=''):
        if (duration, peaks, message) == (self.duration, self.peaks, self.message):
            return
        self.duration, self.peaks, self.message = duration, peaks, message
        self._render()

    def set_position(self, position):
        self.position = position
        if not self.dragging:
            self._move_playhead(position)

    def _build_glow_background(self, width, height, levels, tint):
        from PIL import Image, ImageDraw, ImageTk, ImageFilter
        if not levels:
            # Loading/empty message must not allocate six large transparent bitmaps.
            empty=ImageTk.PhotoImage(Image.new('RGBA',(1,1)),master=self)
            return (empty,)*8
        key=(width,height,tuple(levels),tint)
        cached=self._glow_frame_cache.get(key)
        if cached is not None:
            return cached
        # Transparent localized halos: no extra purple rectangle inside the card.
        soft=Image.new('RGBA',(width,height))
        halo=ImageDraw.Draw(soft)
        mid=height*.5
        tint_rgb=(190,88,249)
        if levels:
            count=len(levels)
            for i,level in enumerate(levels):
                x=round(10+(i+.5)*(width-20)/count)
                radius=max(4,min(1.0,level)*(mid-13))
                halo.line((x,mid-radius,x,mid+radius),fill=(*tint_rgb,180),width=6)
        soft=soft.filter(ImageFilter.GaussianBlur(8))
        r,g,b,alpha=soft.split()
        # 24 antialiased brightness steps; no raster operations during animation ticks.
        frames=[]
        for gain in tuple(.40 + 1.42*(.5-.5*math.cos(math.pi*i/23)) for i in range(24)):
            lut=[min(255,round(v*gain)) for v in range(256)]
            frames.append(ImageTk.PhotoImage(Image.merge('RGBA',(r,g,b,alpha.point(lut))),master=self))
        frames=tuple(frames)
        # Only two most recently used sizes/tracks: bounded RAM even after drags.
        self._glow_frame_cache[key]=frames
        while len(self._glow_frame_cache)>1:
            self._glow_frame_cache.pop(next(iter(self._glow_frame_cache)))
        return frames

    def _build_shimmer(self, height):
        from PIL import Image, ImageDraw, ImageTk, ImageFilter
        width = 130
        layer = Image.new('RGBA', (width, max(1, height)))
        pix = ImageDraw.Draw(layer)
        for x in range(width):
            fx = abs((x-width/2)/(width/2))
            alpha = int(70*(max(0, 1-fx)**2.7))
            pix.line((x, 14, x, max(15, height-14)), fill=(236, 145, 255, alpha))
        layer = layer.filter(ImageFilter.GaussianBlur(9))
        return ImageTk.PhotoImage(layer, master=self)

    def _render(self):
        self._stop_animation()
        self.delete('all')
        self.bars = []
        self.colored = 0
        self._bar_idle_colors = []
        self._bar_active_colors = []
        self._breath_palettes = []
        self._animated_items.clear()
        width, height = self.winfo_width(), self.winfo_height()
        self._wave_size = (width, height)
        self._last_playhead_x = None
        if width <= 25 or height <= 25:
            return
        center = height/2
        levels = ()
        if self.peaks:
            # Cap bars per frame and cache downsampled levels by *data + width*.
            count = min(len(self.peaks), max(2, (width-20)//4), 380)
            key = (self.peaks, count)
            if key != self._levels_key:
                self._levels = tuple(max(self.peaks[i*len(self.peaks)//count:
                                                      max(i*len(self.peaks)//count+1, (i+1)*len(self.peaks)//count)])
                                     for i in range(count))
                self._levels_key = key
            levels = self._levels
        self._glow_background_frames=self._build_glow_background(width,height,levels,self.cover_tint)
        self._glow_background_photo=self._glow_background_frames[min(8,len(self._glow_background_frames)-1)]
        self._glow_base_item=self.create_image(0,0,image=self._glow_background_photo,
                                               anchor='nw',tags='wave_base')
        self._beam_photo=None
        self._beam_item=None
        self._breath_step=-1
        if levels:
            count = len(levels)
            for i, level in enumerate(levels):
                x = 10 + (i+.5)*(width-20)/count
                radius = max(2, min(1.0, level)*(center-14))
                gradient = i / max(1, count-1)
                dark = self._mix('#694889', '#9770BA', gradient)
                bright = self._mix('#FFC5FF', '#C66FFF', gradient)
                self._bar_idle_colors.append(dark)
                self._bar_active_colors.append(bright)
                item = self.create_line(x, center-radius, x, center+radius,
                                        width=max(2, min(3, (width-20)/count*.58)),
                                        capstyle='round', fill=dark, tags='wave_bar')
                self.bars.append(item)
            self._breath_palettes=[]
            for gain in tuple(.13+.61*(.5-.5*math.cos(math.pi*i/23)) for i in range(24)):
                self._breath_palettes.append(tuple(
                    (self._mix(self._bar_active_colors[i],'#FFE5FF',gain) if i<self.colored
                     else self._mix(self._bar_idle_colors[i],'#E1A2FF',gain))
                    for i in range(count)))
        else:
            self._breath_palettes=[]
        if not levels and self.message:
            self.create_text(width/2, center-14, text=self.message,
                             font=(self.winfo_toplevel().ui_font, 10),
                             fill='#EACCF8', tags='wave_message')
        # independent playhead elements: moving them is cheap even at 30fps
        self.playhead = self.create_line(10, 9, 10, height-9, width=2,
                                         fill='#FFF3BD', state='normal' if self.duration else 'hidden',
                                         tags='wave_playhead')
        self.playhead_dot = self.create_oval(6, center-4, 14, center+4, fill='#FFF5D6',
                                              outline='', state='normal' if self.duration else 'hidden',
                                              tags='wave_playhead')
        self._move_playhead(self.position)
        self._draw_lab_markers()
        self._start_animation()

    def set_lab_markers(self, a, b, enabled):
        if (a, b, enabled) != self.lab_markers:
            self.lab_markers = (a, b, enabled)
            self._draw_lab_markers()

    def _draw_lab_markers(self):
        self.delete('lab_markers')
        if not self.duration or self.winfo_width() <= 25:
            return
        width, height = self.winfo_width(), self.winfo_height()
        a, b, enabled = self.lab_markers
        def x_at(point):
            return 10 + max(0., min(1., point/self.duration))*(width-20)
        if a is not None and b is not None and b > a:
            shade = self.create_rectangle(x_at(a), 11, x_at(b), height-6,
                                          outline='', fill='#55346D' if enabled else '#36244D',
                                          stipple='gray50', tags='lab_markers')
            if self.bars:
                self.tag_lower(shade, self.bars[0])
            else:
                self.tag_lower(shade, self.playhead)
        for point, label in ((a, 'A'), (b, 'B')):
            if point is not None:
                x = x_at(point)
                self.create_line(x, 11, x, height-6, fill='#E9A1FA', dash=(3,3), tags='lab_markers')
                self.create_text(min(x+9, width-9), 8, text=label, fill='#F0B4FF',
                                 font=('Segoe UI', 8, 'bold'), tags='lab_markers')
        self.tag_raise('wave_playhead')

    def _move_playhead(self, position):
        if not self.duration or not hasattr(self, 'playhead') or not self.type(self.playhead):
            return
        fraction = max(0., min(1., position/self.duration))
        width, height = self.winfo_width(), self.winfo_height()
        x = 10 + fraction * max(1, width-20)
        if x != self._last_playhead_x:
            self.coords(self.playhead, x, 9, x, height-9)
            self.coords(self.playhead_dot, x-4, height/2-4, x+4, height/2+4)
            self._last_playhead_x = x
        target = round(fraction*len(self.bars))
        if target != self.colored:
            for i in range(*sorted((self.colored, target))):
                if i in self._animated_items:
                    continue
                self.itemconfigure(self.bars[i], fill=(self._bar_active_colors[i] if i < target
                                                     else self._bar_idle_colors[i]))
            self.colored = target

    def _start_animation(self):
        if self._anim_job is None and self.bars and self.winfo_ismapped():
            self._last_animation_time = time.monotonic()
            self._anim_job = self.after(90, self._animate)

    def _stop_animation(self):
        if self._anim_job is not None:
            try:
                self.after_cancel(self._anim_job)
            except tk.TclError:
                pass
            self._anim_job = None

    def _animate(self):
        self._anim_job=None
        if not self.winfo_exists() or not self.winfo_ismapped() or not self.bars:
            return
        root=self.winfo_toplevel()
        if getattr(root,'active_page',None)!='player' or getattr(root,'_resizing_window',False):
            self._last_animation_time=time.monotonic()
            self._anim_job=self.after(220,self._animate)
            return
        now=time.monotonic()
        elapsed=min(.3,max(0.0,now-self._last_animation_time))
        self._last_animation_time=now
        playing=bool(getattr(root,'playing',False) and not getattr(root,'paused',False))
        self._anim_mode='playing' if playing else 'breathing'
        # A shared 3.8 s inhale/exhale cycle; it brightens the *whole* wave,
        # including its soft neon halo. No left-to-right beam while stopped.
        self._animated_phase=(self._animated_phase+elapsed/3.8)%1.0
        strength=.5+.5*math.sin(self._animated_phase*math.tau)
        step=max(0,min(23,round(strength*23)))
        if step!=getattr(self,'_breath_step',-1):
            self._breath_step=step
            if getattr(self,'_glow_base_item',None) is not None:
                self._glow_background_photo=self._glow_background_frames[step]
                self.itemconfigure(self._glow_base_item,image=self._glow_background_photo)
            # Values are precomputed, so every heartbeat is only 1 PhotoImage swap
            # and a few native Canvas fill updates; no Pillow and no audio analysis.
            if self._breath_palettes:
                palette=self._breath_palettes[step]
                for i,item in enumerate(self.bars):
                    color=(self._mix(self._bar_active_colors[i],'#FFF1FF',(.23+.55*step/23))
                           if i<self.colored else palette[i])
                    self.itemconfigure(item,fill=color)
        self._anim_job=self.after(55,self._animate)

    def _time_at(self, event):
        fraction = (event.x-10)/max(1, self.winfo_width()-20)
        return self.duration*max(0., min(1., fraction))

    def _start_drag(self, event):
        if self.duration:
            self.focus_set()
            self.dragging = True
            self._drag(event)

    def _drag(self, event):
        if self.dragging:
            position = self._time_at(event)
            self._move_playhead(position)
            self.preview(position)

    def _release(self, event):
        if self.dragging:
            self.dragging = False
            self.seek(self._time_at(event))

    def _hover(self, event):
        self.delete('hover')
        if self.duration and not self.dragging:
            x = max(26, min(event.x, self.winfo_width()-26))
            self.create_rectangle(x-25, 5, x+25, 24, fill='#43245D',
                                  outline='#75518E', tags='hover')
            self.create_text(x, 14, text=fmt_time(self._time_at(event)),
                             font=(self.winfo_toplevel().ui_font, 9), fill=TEXT, tags='hover')





LAB_SURFACE = '#1D112F'
LAB_CARD = '#241538'
LAB_LINE = '#52376D'
LAB_TRACK = '#5D4678'
LAB_ACTIVE = '#BA6BFA'


# Gemeinsam benutzbare Render-Bausteine fuer aktuelle und kuenftige UI-Kacheln.
# Der Cache speichert nur PIL-Raster, keine Tk-Objekte (Tk-Bilder bleiben widget-lokal).
# Alle gestalterischen Parameter sind Teil des Schluessels; maxsize begrenzt den RAM.
from functools import lru_cache as _render_lru_cache

@_render_lru_cache(maxsize=64)
def _render_nine_slice(width, height, radius, fill, border, border_width=1):
    """Antialiaste runde Flaeche ohne teures 2x-Rendering ganzer Fensterbreiten.

    Nur ein kleines, supersampeltes Eckmuster wird gezeichnet. Die Mitten und
    Seiten werden aus demselben Muster zusammengesetzt. Exakte Endgroessen
    verhindern falsch skalierte Ränder nach Maximieren/Wiederherstellen.
    """
    from PIL import Image, ImageDraw
    width, height = int(width), int(height)
    if width < 3 or height < 3:
        return Image.new('RGBA', (max(1,width), max(1,height)), fill)
    r = max(1, min(int(radius), (min(width,height)-1)//2))
    edge = min(r+2, width//2, height//2)
    base_size = edge*2+1
    z = 3
    template = Image.new('RGBA',(base_size*z,base_size*z))
    pen=ImageDraw.Draw(template)
    pen.rounded_rectangle((0,0,base_size*z-1,base_size*z-1), radius=r*z,
                          fill=fill, outline=border, width=max(1,border_width*z))
    template=template.resize((base_size,base_size),Image.Resampling.LANCZOS)
    out=Image.new('RGBA',(width,height),fill)
    # Ecken werden pixelgenau kopiert; Mittelflaechen und Kanten benötigen
    # nur native Bildoperationen statt eines riesigen Pillow-Supersamplings.
    out.paste(template.crop((0,0,edge,edge)),(0,0))
    out.paste(template.crop((base_size-edge,0,base_size,edge)),(width-edge,0))
    out.paste(template.crop((0,base_size-edge,edge,base_size)),(0,height-edge))
    out.paste(template.crop((base_size-edge,base_size-edge,base_size,base_size)),
              (width-edge,height-edge))
    draw=ImageDraw.Draw(out)
    if width > 2*edge:
        draw.rectangle((edge,0,width-edge-1, border_width-1),fill=border)
        draw.rectangle((edge,height-border_width,width-edge-1,height-1),fill=border)
    if height > 2*edge:
        draw.rectangle((0,edge,border_width-1,height-edge-1),fill=border)
        draw.rectangle((width-border_width,edge,width-1,height-edge-1),fill=border)
    return out

@_render_lru_cache(maxsize=48)
def _player_frame_bitmap(width, height, outer_radius, edge, center, inner_radius):
    """Geglätteter, gemeinsam gecachter Kachelrahmen ohne Vollbild-Supersampling."""
    # Die bisherige Form bleibt durch zwei ineinanderliegende Rundungen erhalten.
    from PIL import Image
    width,height=int(width),int(height)
    if width <= 2 or height <= 2:
        return Image.new('RGBA',(max(1,width),max(1,height)),edge)
    outer=_render_nine_slice(width,height,outer_radius,edge,edge)
    inset=_render_nine_slice(width-2,height-2,inner_radius,center,center)
    outer.paste(inset,(1,1))
    return outer

# Vektoraehnlich geglaettete Kurve in 2x Aufloesung und aus einem fuer die
# jeweilige DPI-Klasse gross genugem Master. Pro Resize wird nur skaliert,
# bei 4K steht ein zusaetzlicher eigener hochaufgeloester Master bereit.
@_render_lru_cache(maxsize=2)
def _neon_arc_master(master_width):
    """Supersampled continuous neon curve, with soft halos but no stepped pixels."""
    from PIL import Image, ImageDraw, ImageFilter
    master_width = max(1100, int(master_width))
    master_height = 74
    factor = 2
    w, h = master_width * factor, master_height * factor

    def curve(offset):
        # Sample every subpixel to avoid visible stair steps at Windows DPI 125-150%.
        samples = []
        for ix in range(0, w, 1):
            t = ix / max(1, w-1)
            arc = (max(0., math.sin(math.pi*t)) ** 1.02)
            y = h*(0.18 + 0.51*arc + offset)
            samples.append((ix, round(y)))
        samples.append((w-1, round(h*(.18+offset))))
        return samples

    main, echo = curve(0), curve(-0.105)
    def stroke(points, color, thickness):
        pic = Image.new('RGBA',(w,h))
        ImageDraw.Draw(pic).line(points, fill=color, width=max(1,round(thickness*factor)),joint='curve')
        return pic

    wide = stroke(main,(197,61,252,120),15).filter(ImageFilter.GaussianBlur(8*factor))
    glow = stroke(main,(223,98,255,165),7).filter(ImageFilter.GaussianBlur(3.5*factor))
    result=Image.alpha_composite(wide,glow)
    result=Image.alpha_composite(result,stroke(echo,(237,174,255,95),0.65))
    result=Image.alpha_composite(result,stroke(main,(207,75,248,242),2.2))
    result=Image.alpha_composite(result,stroke(main,(255,208,255,238),0.65))
    # Soft light pools are part of the artwork, not independent pixelated ellipses.
    dots=Image.new('RGBA',(w,h))
    pen=ImageDraw.Draw(dots)
    for t,r in ((.20,2.8),(.52,3.8),(.84,2.8)):
        x=t*(w-1)
        y=h*(.18 + .51*math.sin(math.pi*t)**1.02)
        rad=r*factor
        pen.ellipse((x-rad,y-rad,x+rad,y+rad),fill=(255,189,255,160))
    result=Image.alpha_composite(result,dots.filter(ImageFilter.GaussianBlur(2.8*factor)))
    return result.resize((master_width,master_height),Image.Resampling.LANCZOS)

@_render_lru_cache(maxsize=24)
def _neon_arc_image(width, height):
    from PIL import Image
    width, height = max(12,int(width)), max(12,int(height))
    master = _neon_arc_master(2560 if width <= 2560 else 4400)
    return master.resize((width,height),Image.Resampling.LANCZOS)

# Reusable art for existing + future Sound-Lab buttons. The PIL cache is
# bounded, and the canvas owns only a small per-widget Tk PhotoImage.
@_render_lru_cache(maxsize=128)
def _lab_button_bitmap(w, h, primary, highlighted, focused):
    """Soft, truly antialiased capsule. No ornamental arc across its label."""
    from PIL import Image, ImageDraw, ImageFilter
    w,h = max(20,int(w)), max(18,int(h))
    z=4
    W,H=w*z,h*z
    radius=(H-5*z)//2
    halo=Image.new('RGBA',(W,H))
    hp=ImageDraw.Draw(halo)
    hp.rounded_rectangle((3*z,3*z,W-3*z-1,H-3*z-1),radius=radius,
        fill=(255,231,129,90 if highlighted else 55) if primary else (196,93,255,105 if highlighted else 48))
    halo=halo.filter(ImageFilter.GaussianBlur(2.1*z))
    mask=Image.new('L',(W,H))
    ImageDraw.Draw(mask).rounded_rectangle((2*z,2*z,W-2*z-1,H-2*z-1),radius=radius,fill=255)
    field=Image.new('RGBA',(W,H))
    brush=ImageDraw.Draw(field)
    first,last=((255,249,193),(246,221,124)) if primary else (((97,54,142),(52,31,81)) if highlighted else ((72,40,104),(43,26,67)))
    for y in range(H):
        t=y/max(1,H-1)
        color=tuple(round(start*(1-t)+end*t) for start,end in zip(first,last))
        brush.line((0,y,W,y),fill=(*color,255))
    field.putalpha(mask)
    art=Image.alpha_composite(halo,field)
    pen=ImageDraw.Draw(art)
    outline=(255,245,196,240) if primary else (223,162,255,246 if highlighted or focused else 190)
    pen.rounded_rectangle((2*z,2*z,W-2*z-1,H-2*z-1),radius=radius,
                          outline=outline,width=z)
    if focused:
        pen.rounded_rectangle((z,z,W-z-1,H-z-1),radius=radius+z,
                              outline=(238,182,255,210),width=z)
    return art.resize((w,h),Image.Resampling.LANCZOS)

@_render_lru_cache(maxsize=48)
def _lab_knob_bitmap(diameter, enabled, emphasized):
    """Reusable antialiased fader/switch knob; transparent glow and rounded edges."""
    from PIL import Image,ImageDraw,ImageFilter
    diameter=max(14,int(diameter))
    z=4
    side=(diameter+10)*z
    center=side/2
    r=diameter*z/2
    glow=Image.new('RGBA',(side,side))
    ImageDraw.Draw(glow).ellipse((center-r-2*z,center-r-2*z,center+r+2*z,center+r+2*z),
        fill=(239,174,255,154 if emphasized else 85))
    glow=glow.filter(ImageFilter.GaussianBlur(2.5*z))
    rim=Image.new('RGBA',(side,side))
    d=ImageDraw.Draw(rim)
    d.ellipse((center-r,center-r,center+r,center+r),fill=(154,90,191,245))
    d.ellipse((center-r+1*z,center-r+1*z,center+r-1*z,center+r-1*z),
              fill=(255,244,176,255) if enabled else (188,167,209,255))
    d.ellipse((center-r+3*z,center-r+2*z,center+r-3*z,center-r+4*z),fill=(255,255,248,140))
    glow=Image.alpha_composite(glow,rim)
    return glow.resize((diameter+10,diameter+10),Image.Resampling.LANCZOS)

@_render_lru_cache(maxsize=48)
def _lab_accent_line_bitmap(w):
    """Subtle studio-rack highlight; shared across three Sound Lab tiles."""
    from PIL import Image, ImageDraw
    w=max(2,int(w))
    art=Image.new('RGBA',(w,3))
    d=ImageDraw.Draw(art)
    for x in range(w):
        f=x/max(1,w-1)
        alpha=round(25+145*(math.sin(math.pi*f)**1.6))
        d.line((x,1,x,2), fill=(204,107,255,alpha))
    return art

class LabAccent(tk.Canvas):
    """Thin, lightly glowing accent; draw only when its width actually changes."""
    def __init__(self,parent):
        super().__init__(parent,height=4,bd=0,highlightthickness=0,bg=LAB_CARD)
        self._width=None
        self._photo=None
        self._job=None
        self.bind('<Configure>',self._changed)
    def _changed(self,event):
        if event.width==self._width: return
        if self._job is None:
            self._job=self.after(85,self._flush)
    def _flush(self):
        self._job=None
        w=self.winfo_width()
        if w==self._width or w<5: return
        from PIL import ImageTk
        self._photo=ImageTk.PhotoImage(_lab_accent_line_bitmap(w),master=self)
        self.delete('all')
        self.create_image(0,0,image=self._photo,anchor='nw')
        self._width=w


class RoundedPane(tk.Frame):
    """Geglaettete Flaeche: identische Groessen nicht erneut rendern.

    Configure-Stuerme beim erstmaligen Layout werden kurz zusammengefasst.
    Der eigentliche Inhalt bleibt ein normales Tk-Frame.
    """

    def __init__(self, parent, outside, fill, border=LAB_LINE, padding=12, radius=13):
        super().__init__(parent, bg=outside)
        self.fill, self.border, self.radius = fill, border, radius
        self.backdrop = tk.Canvas(self, bg=outside, bd=0, highlightthickness=0)
        self.backdrop.place(x=0, y=0, relwidth=1, relheight=1)
        self.backdrop.tk.call('lower', self.backdrop._w)
        self.content = tk.Frame(self, bg=fill)
        self.content.pack(fill='both', expand=True, padx=padding, pady=padding)
        self._paint_size = None
        self._paint_pending = None
        self._requested_size = None
        self.bind('<Configure>', self._paint)

    def _paint(self, event):
        size = (event.width, event.height)
        if min(size) < 8:
            return
        self._requested_size = size
        if self._paint_size == size:
            if self._paint_pending is not None:
                self.after_cancel(self._paint_pending)
                self._paint_pending = None
            return
        if self._paint_pending is None:
            self._paint_pending = self.after(75, self._flush_paint)

    def _flush_paint(self):
        self._paint_pending = None
        size = self._requested_size
        if not size or size == self._paint_size or not self.winfo_exists():
            return
        from PIL import ImageTk
        width,height=size
        photo=ImageTk.PhotoImage(_render_nine_slice(width,height,self.radius,
                                                     self.fill,self.border),master=self.backdrop)
        self.photo = photo
        if getattr(self, '_paint_item', None) is None:
            self._paint_item = self.backdrop.create_image(0, 0, anchor='nw', image=photo)
        else:
            self.backdrop.itemconfigure(self._paint_item, image=photo)
        self._paint_size = size


class LabButton(Pill):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.configure(takefocus=True)
        self.bind('<Return>', lambda event: self.command())
        self.bind('<space>', lambda event: self.command())
        self.bind('<FocusIn>', lambda event: self._draw(self.hover))
        self.bind('<FocusOut>', lambda event: self._draw(self.fill))

    def _draw(self, color):
        focused = self.focus_get() is self
        primary = self.fill == ACTION_YELLOW
        highlighted = color != self.fill
        sig=(self.text,self.fg,self.font,self.w,self.h,primary,highlighted,focused)
        if sig == getattr(self,'_lab_signature',None): return
        self._lab_signature=sig
        from PIL import ImageTk
        self._ui_button_photo=ImageTk.PhotoImage(
            _lab_button_bitmap(self.w,self.h,primary,highlighted,focused),master=self)
        self.delete('all')
        self.create_image(0,0,image=self._ui_button_photo,anchor='nw')
        self.create_text(self.w/2,self.h/2,text=self.text,fill=(BG if primary else self.fg),font=self.font)


class LabDisclosure(tk.Canvas):
    def __init__(self, parent, command, family):
        super().__init__(parent,height=44,bg=BG,bd=0,highlightthickness=0,takefocus=True,cursor='hand2')
        self.command,self.family=command,family
        self.expanded=False
        self.hover=False
        self._drawn_signature=None
        self._draw_pending=None
        self._accent_pulse=None
        self._pulse_job=None
        self._pulse_phase=0
        self.bind('<Configure>',self._on_resize)
        self.bind('<Enter>',lambda event:self._hover(True))
        self.bind('<Leave>',lambda event:self._hover(False))
        self.bind('<FocusIn>',lambda event:self.draw())
        self.bind('<FocusOut>',lambda event:self.draw())
        self.bind('<ButtonRelease-1>',lambda event:self.invoke())
        self.bind('<Return>',lambda event:self.invoke())
        self.bind('<space>',lambda event:self.invoke())
        self.bind('<Map>',lambda event:self._start_pulse())
        self.bind('<Unmap>',lambda event:self._stop_pulse())
        self.bind('<Destroy>',lambda event:self._stop_pulse() if event.widget is self else None)

    def _on_resize(self,event):
        if self._draw_pending is None:
            self._draw_pending=self.after(75,self._flush_draw)
    def _flush_draw(self):
        self._draw_pending=None
        self.draw()
    def invoke(self):
        self.command()
        return 'break'
    def set_open(self,open_):
        if self.expanded!=open_:
            self.expanded=open_
            self.draw()
            if open_: self._start_pulse()
            else: self._stop_pulse()
    def _hover(self,value):
        if self.hover!=value:
            self.hover=value
            self.draw()
    def _stop_pulse(self):
        if self._pulse_job is not None:
            try: self.after_cancel(self._pulse_job)
            except tk.TclError: pass
            self._pulse_job=None
    def _start_pulse(self):
        if self.expanded and self._pulse_job is None and self.winfo_ismapped():
            self._pulse_job=self.after(280,self._pulse)
    def _pulse(self):
        self._pulse_job=None
        if not self.winfo_exists() or not self.winfo_ismapped() or not self.expanded:
            return
        if not getattr(self.winfo_toplevel(),'_resizing_window',False):
            colors=('#9F60CF','#B36EE8','#CA90FC','#B36EE8')
            self._pulse_phase=(self._pulse_phase+1)%len(colors)
            if self._accent_pulse is not None:
                self.itemconfigure(self._accent_pulse,fill=colors[self._pulse_phase])
        self._pulse_job=self.after(280,self._pulse)
    def draw(self):
        w,h=self.winfo_width(),self.winfo_height()
        if w<30 or h<10:return
        focused=self.focus_get() is self
        signature=(w,h,focused,self.hover,self.expanded,self.family)
        if signature==self._drawn_signature:return
        from PIL import ImageTk
        border='#A276CE' if focused or self.hover else '#6C4A91'
        color='#3C2557' if self.hover else LAB_SURFACE
        self._background_photo=ImageTk.PhotoImage(
            _player_frame_bitmap(w,h,12,border,color,11),master=self)
        self.delete('all')
        self.create_image(0,0,image=self._background_photo,anchor='nw')
        # Purple edge is animated only by changing a native canvas color.
        self._accent_pulse=self.create_line(15,5,15,h-5,fill='#B36EE8',width=3,capstyle='round')
        self.create_line(24,h-3,w-28,h-3,fill='#6A3B88',width=1)
        self.create_text(30,h/2,text='Mixer',anchor='w',fill=TEXT,
                         font=(self.family,13,'bold'))
        if self.expanded:
            self.create_text(min(130,w-60),h/2,text='●',fill='#B989EC',anchor='w',font=(self.family,8))
        y=h/2
        offset=-4 if self.expanded else 4
        self.create_line(w-31,y-offset/2,w-24,y+offset/2,w-17,y-offset/2,
                         fill='#F0CEFF',width=2,capstyle='round',joinstyle='round')
        self._drawn_signature=signature


class LabSwitch(LabButton):
    def _draw(self,color):
        active=self.text=='Ein'
        highlighted=color!=self.fill
        focused=self.focus_get() is self
