    def _enable_dark_windows_titlebar(self):
        """Optional Windows 10/11 dark window chrome, preserving native window controls."""
        if os.name != 'nt':
            return
        try:
            import ctypes
            hwnd = ctypes.windll.user32.GetParent(self.winfo_id())
            enabled = ctypes.c_int(1)
            for attribute in (20, 19):
                if ctypes.windll.dwmapi.DwmSetWindowAttribute(
                        hwnd, attribute, ctypes.byref(enabled),
                        ctypes.sizeof(enabled)) == 0:
                    break
        except (OSError, AttributeError, ValueError):
            pass

    def setting(self, key, default=""):
        row = self.db.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        return row[0] if row else default

    def save_setting(self, key, value):
        self.db.execute("INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)", (key, str(value)))
        self.db.commit()

    def close_popups(self):
        self._close_song_menu()
        self.close_main_menu()
        if self.filter_popup and self.filter_popup.winfo_exists():
            self.filter_popup.destroy()
        self.filter_popup = None
        if self.analysis_panel and self.analysis_panel.winfo_exists():
            self.analysis_panel.destroy()
        self.analysis_panel = None

    def draw_analyze_button(self, hover=False):
        button = self.analyze_button
        button.delete("all")
        w = int(button.cget("width"))
        button.create_image(0, 0, anchor="nw",
            image=smooth_shape(w, 34, 17, ACTION_YELLOW_HOVER if hover else ACTION_YELLOW))
        button.create_text((w - 12) / 2, 17, text="Analysieren", fill=BG,
                           font=(self.ui_font, 9, "bold"))
        button.create_line(w - 27, 8, w - 27, 26, fill="#b99d35")
        button.create_text(w - 13, 17, text="▾", fill=BG,
                           font=(self.ui_font, 12, "bold"))

    def analysis_button_click(self, event):
        w = int(self.analyze_button.cget("width"))
        if event.x >= w - 28:
            self.toggle_analysis_menu()
        else:
            self.close_popups()
            self.start_analysis()

    def toggle_analysis_menu(self):
        opened = bool(self.analysis_panel and self.analysis_panel.winfo_exists())
        self.close_popups()
        if opened:
            return
        width = int(self.analyze_button.cget("width"))
