    def _analysis_scope_change(self):
        self.set_category(self.ana_scope.get())
        # set_category already refreshes the underlying library once.
        self._refresh_analysis_page()

    def _refresh_analysis_page(self):
        if self.active_page != "analysis" or not self.nav_view:
            return
        try:
            total = len(self._visible_analysis_todo())
            pending = len(self._visible_analysis_todo(only_pending=True))
            done = total - pending
            self.analysis_summary.config(text=f"In aktueller Auswahl: {total} Titel  ·  "
                                              f"{done} analysiert  ·  {pending} ausstehend")
            if self.analyzing:
                progress = 100 * self.ana_done / max(1, self.ana_total)
            else:
                progress = 100 * done / max(1, total)
            self.analysis_progress["value"] = progress
        except (tk.TclError, AttributeError):
            pass




    def _build_player_page(self, parent):
        viewport = tk.Frame(parent, bg=BG)
        viewport.pack(fill='both', expand=True)
        canvas = self._player_scroll = tk.Canvas(viewport, bg=BG, bd=0, highlightthickness=0)
        scroll = ttk.Scrollbar(viewport, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side='left', fill='both', expand=True)
        page = tk.Frame(canvas, bg=BG)
        window = canvas.create_window(0, 0, window=page, anchor='nw')

        body = self._player_body = tk.Frame(page, bg=BG)
        body.pack(fill='x')
        body.columnconfigure(0, weight=1)
        main = self._player_top = tk.Frame(body, bg=BG)
        main.grid(row=0, column=0, sticky='nsew')
        main.columnconfigure(1, weight=1)
        main.rowconfigure(0, minsize=280)
        self._player_artwork = CoverTile(main)
        self._player_artwork.grid(row=0, column=0, sticky='nsew', padx=(0, 12))
        self._player_wave_section = wave_shell = RoundedPane(main, BG, '#25173D', padding=16)
        wave_shell.grid(row=0, column=1, sticky='nsew')
        wave = wave_shell.content
        heading = tk.Frame(wave, bg='#25173D')
        heading.pack(fill='x')
        self._player_title = tk.Label(heading, bg='#25173D', fg=TEXT, text='', anchor='w', justify='left',
                                      font=(self.ui_font, 23, 'bold'))
        self._player_title.pack(side='left', fill='x')
        self._player_info_button = LabButton(heading, 'ⓘ', lambda: self._toggle_player_panel('details'),
                                             w=30, h=28, bg='#25173D', font=('Segoe UI Symbol', 11))
        self._player_info_button.pack(side='left', padx=8)
        heading.bind('<Configure>', lambda event: self._player_title.configure(wraplength=max(40, event.width - 46)))
        self._player_artist = tk.Label(wave, bg='#25173D', fg='#CFB8E9', anchor='w',
                                      font=(self.ui_font, 11))
        self._player_artist.pack(fill='x', pady=(2, 5))
        self.large_progress = PlayerWaveform(wave, self.seek_to, self._preview_player_time)
        self.large_progress.configure(bg='#25173D')
        self.large_progress.pack(fill='both', expand=True, pady=(4, 0))
        for modifier, index in (('Shift', 0), ('Control', 1)):
            def marker(event, n=index):
                self._set_lab_marker(n, self.large_progress._time_at(event))
                return 'break'
            self.large_progress.bind(f'<{modifier}-ButtonPress-1>', marker)
        times = tk.Frame(wave, bg='#25173D')
        times.pack(fill='x', pady=(3, 0))
        self.large_time = tk.Label(times, text='0:00', bg='#25173D', fg=TEXT,
                                   font=(self.ui_font, 10, 'bold'))
        self.large_time.pack(side='left')
        self.large_duration = tk.Label(times, text='0:00', bg='#25173D', fg=MUTED,
                                       font=(self.ui_font, 10))
        self.large_duration.pack(side='right')
        tk.Frame(wave, bg='#25173D', height=4).pack(fill='x')
        self._player_side = tk.Frame(body, bg=BG)
        self._player_open_panels = set()
        self._player_panels = {
            'details': self._build_player_details(page),
            'queue': self._build_player_queue(self._player_side),
        }
        self._player_panels['queue'].pack(fill='both', expand=True)
        arc = self._player_arc = PlayerNeonArc(page)
        arc.pack(fill='x', pady=(8, 6))
        tk.Frame(page, bg='#50306E', height=1).pack(fill='x', pady=(0, 10))
        self._lab_header = LabDisclosure(page, lambda: self._toggle_player_panel('lab'), self.ui_font)
        self._lab_header.pack(fill='x')
        self._player_panels['lab'] = self._build_sound_lab(page)
        self._player_queue_signature = None

        scroll_job=[None]
        def flush_scroll():
            scroll_job[0]=None
            if not canvas.winfo_exists():
                return
            height=max(1,canvas.winfo_height())
            width=max(1,canvas.winfo_width())
            required=max(1,page.winfo_reqheight())
            total=max(height,required)
            # The visible content, not a stale previous canvas window height,
            # determines scrollability. Never compress Sound-Lab widgets.
            try:
                old_height=int(float(canvas.itemcget(window,'height') or 0))
            except (ValueError,tk.TclError):
                old_height=0
            if old_height != total:
                canvas.itemconfigure(window,height=total)
            canvas.configure(scrollregion=(0,0,width,total))
            needs_scroll=required>height+1
            if needs_scroll:
                if not scroll.winfo_manager():
                    scroll.pack(side='right',fill='y',before=canvas)
            else:
                if scroll.winfo_manager():scroll.pack_forget()
                if canvas.yview()[0]>0:canvas.yview_moveto(0)

        def sync_scroll(event=None):
            if scroll_job[0] is None and canvas.winfo_exists():
                scroll_job[0]=canvas.after_idle(flush_scroll)
        self._player_sync_scroll=sync_scroll

        def resize(event):
            if event.width < 20 or event.height < 20:
                return
            canvas.itemconfigure(window,width=event.width)
            self._layout_player_panels(event.width)
            # Top section plus half of the Sound-Lab header is about 50% of viewport.
            # 87px separator + 24px (half header + small reserve) = 111px.
            # The genuine minimum needed for waveform labels is 280px. Small
            # windows use the existing scroll canvas rather than clipping EQ.
            hero=max(280, min(350, round(event.height*.50)-111))
            art=min(hero, max(188, round((event.width-18)*.33)))
            if getattr(main,'_hero_size',None)!=hero:
                main._hero_size=hero
                main.rowconfigure(0,minsize=hero)
            if getattr(main,'_art_size',None)!=art:
                main._art_size=art
                self._player_artwork.configure(width=art-2,height=hero-2)
            sync_scroll()

        def wheel(event):
            if scroll.winfo_manager():
                direction = -1 if getattr(event, 'delta', 0) > 0 or getattr(event, 'num', 0) == 4 else 1
                canvas.yview_scroll(direction * 3, 'units')
            return 'break'

        canvas.bind('<Configure>', resize)
        page.bind('<Configure>', sync_scroll)
        body.bind('<Configure>', sync_scroll)
        def bind_wheel(widget):
            if widget is self._player_queue_list or isinstance(widget, tk.Scale):
                return
            for sequence in ('<MouseWheel>', '<Button-4>', '<Button-5>'):
                widget.bind(sequence, wheel, add='+')
            for child in widget.winfo_children():
                bind_wheel(child)
        bind_wheel(page)
        bind_wheel(canvas)
        self._large_cover_path = object()
        self._wave_requested_path = object()
        self._refresh_large_player(force_cover=True)

    def _layout_player_panels(self, width):
        if 'queue' not in self._player_open_panels:
            self._player_side.grid_remove()
        elif width >= 870:
            self._player_side.grid(row=0, column=1, sticky='nsew', padx=(12, 0))
        else:
            self._player_side.grid(row=1, column=0, sticky='ew', pady=(8, 0))

    def _open_player_panel_from_bar(self, key):
        if self.active_page != 'player':
            self.show_page('player')
            if key in self._player_open_panels:
                return
        self._toggle_player_panel(key)

    def _toggle_player_panel(self, key):
        panel = self._player_panels[key]
        if key in self._player_open_panels:
            self._player_open_panels.remove(key)
            if key != 'queue':
                panel.pack_forget()
        else:
            self._player_open_panels.add(key)
            if key == 'details':
                panel.pack(fill='x', before=self._player_arc, pady=(7, 0))
                self._refresh_player_details()
            elif key == 'lab':
                panel.pack(fill='x', pady=(7, 1))
            else:
                self._refresh_player_queue()
        if key == 'lab':
            self._lab_header.set_open(key in self._player_open_panels)
        self._layout_player_panels(self._player_scroll.winfo_width())
        if hasattr(self,'_player_sync_scroll'):
            self._player_sync_scroll()
        self._update_bar_panel_buttons()

    def _update_bar_panel_buttons(self):
        button = getattr(self, '_bar_queue_button', None)
        if button is not None:
            button.show_state(self.active_page == 'player' and 'queue' in getattr(self, '_player_open_panels', ()))


    def _build_sound_lab(self, parent):
        """KLN Mixer: lightweight overview, lazily built detail editors and global tools."""
        shell=RoundedPane(parent,BG,LAB_SURFACE,border='#7B50A3',padding=10)
        lab=shell.content
        self._mixer_view='overview'
        self._mixer_views={}
        self._mixer_controls=[]
        self._lab_percent=tk.DoubleVar(value=round(self.lab_tempo*100,1))
        self._lab_pitch=tk.IntVar(value=int(self.lab_pitch))
        self._lab_cents=tk.IntVar(value=round((float(self.lab_pitch)-int(self.lab_pitch))*100))
        self._lab_sliders=[]
        self._mixer_summaries={}

        top=tk.Frame(lab,bg=LAB_SURFACE)
        top.pack(fill='x',pady=(0,4))
        self._mixer_back=LabButton(top,'← Übersicht',lambda:self._show_mixer_view('overview'),
                 w=116,h=27,bg=LAB_SURFACE,font=(self.ui_font,9))
        self._mixer_back.pack(side='left',padx=(0,8))
        self._mixer_title=tk.Label(top,text='Mixer · Übersicht',bg=LAB_SURFACE,fg=TEXT,
                                   font=(self.ui_font,12,'bold'))
        self._mixer_title.pack(side='left')
        self._mixer_support=tk.Label(top,text='',bg=LAB_SURFACE,fg=MUTED,
                    font=(self.ui_font,9))
        self._mixer_support.pack(side='right',padx=6)
        self._mixer_back.pack_forget()

        holder=tk.Frame(lab,bg=LAB_SURFACE)
        holder.pack(fill='x',expand=False)
        self._mixer_scroll=tk.Canvas(holder,bd=0,highlightthickness=0,bg=LAB_SURFACE,height=158)
        self._mixer_scroll.pack(side='left',fill='both',expand=True)
        self._mixer_yscroll=ttk.Scrollbar(holder,orient='vertical',command=self._mixer_scroll.yview)
        self._mixer_scroll.configure(yscrollcommand=self._mixer_yscroll.set)
        self._mixer_content=tk.Frame(self._mixer_scroll,bg=LAB_SURFACE)
        self._mixer_window=self._mixer_scroll.create_window(0,0,anchor='nw',window=self._mixer_content)
        def sync_size(event=None):
            if not self._mixer_scroll.winfo_exists():return
            self._mixer_scroll.itemconfigure(self._mixer_window,width=max(1,self._mixer_scroll.winfo_width()))
            self._mixer_scroll.configure(scrollregion=self._mixer_scroll.bbox('all'))
            if self._mixer_content.winfo_reqheight()>self._mixer_scroll.winfo_height()+2:
                if not self._mixer_yscroll.winfo_manager():
                    self._mixer_yscroll.pack(side='right',fill='y')
            elif self._mixer_yscroll.winfo_manager():
                self._mixer_yscroll.pack_forget()
                self._mixer_scroll.yview_moveto(0)
        self._mixer_sync_size=lambda: self.after_idle(sync_size)
        self._mixer_content.bind('<Configure>',sync_size)
        self._mixer_scroll.bind('<Configure>',sync_size)

        overview=tk.Frame(self._mixer_content,bg=LAB_SURFACE)
        self._mixer_views['overview']=overview
        headings=(('eq','Equalizer','5-Band · Klangprofil'),
                  ('tempo','Tempo','BPM · Geschwindigkeit'),
                  ('pitch','Tonhöhe','Halbtöne · Cent'))
        cards=tk.Frame(overview,bg=LAB_SURFACE)
        cards.pack(fill='x',pady=(2,6))
        self._mixer_card_frames=[]
        for i,(key,name,subtitle) in enumerate(headings):
            card=RoundedPane(cards,LAB_SURFACE,LAB_CARD,border='#8855B6',padding=10)
            card.grid(row=0,column=i,sticky='nsew',padx=4,pady=3)
            cards.columnconfigure(i,weight=1,uniform='mixer')
            self._mixer_card_frames.append(card)
            content=card.content
            tk.Label(content,text=name,bg=LAB_CARD,fg='#F4D9FF',
                     font=(self.ui_font,13,'bold')).pack(anchor='w')
            tk.Label(content,text=subtitle,bg=LAB_CARD,fg='#BDA4D0',
                     font=(self.ui_font,9)).pack(anchor='w',pady=(2,7))
            summary=tk.Label(content,text='',bg=LAB_CARD,fg=ACTION_YELLOW,
                     font=(self.ui_font,14,'bold'),anchor='w')
            summary.pack(fill='x',pady=(0,6))
            self._mixer_summaries[key]=summary
            LabButton(content,'Bearbeiten  ›',lambda m=key:self._show_mixer_view(m),
                     w=116,h=28,bg=LAB_CARD,font=(self.ui_font,9,'bold')).pack(anchor='w')
            def open_card(event,m=key):
                self._show_mixer_view(m)
            for widget in (card, content, summary, *content.winfo_children()):
                if not isinstance(widget, LabButton):
                    widget.configure(cursor='hand2')
                    widget.bind('<Button-1>',open_card,add='+')
        self._mixer_cards=cards
        self._mixer_views['overview'].pack(fill='both',expand=True)
        self._mixer_bind_wheel(overview)

        separator=tk.Frame(lab,bg='#674388',height=1)
        separator.pack(fill='x',pady=(5,6))
        # Shared loop: belongs to all three processing modules, never to Pitch alone.
        global_tools=tk.Frame(lab,bg=LAB_SURFACE)
        global_tools.pack(fill='x')
        tk.Label(global_tools,text='A/B-Schleife',fg='#E6C9FA',bg=LAB_SURFACE,
                 font=(self.ui_font,10,'bold')).pack(side='left',padx=(0,12))
        for index,label in enumerate(('A setzen','B setzen')):
            LabButton(global_tools,label,lambda i=index:self._set_lab_marker(i),
                      w=75,h=27,bg=LAB_SURFACE,font=(self.ui_font,9)).pack(side='left',padx=(0,5))
        self._lab_loop_button=LabButton(global_tools,'Schleife: aus',self._toggle_lab_loop,
                      w=106,h=27,bg=LAB_SURFACE,font=(self.ui_font,9))
        self._lab_loop_button.pack(side='left',padx=(0,5))
        LabButton(global_tools,'Löschen',self._reset_lab_markers,w=72,h=27,
                 bg=LAB_SURFACE,font=(self.ui_font,9)).pack(side='left')
        self._lab_marks_text=tk.Label(lab,text='',fg=MUTED,bg=LAB_SURFACE,
                     font=(self.ui_font,9),anchor='w')
        self._lab_marks_text.pack(fill='x',pady=(3,5))
        # Export and A/B belong to one persistent toolbar and remain visible
        # in overview and all three focus editors.
        footer=global_tools
        LabButton(footer,'Audio exportieren …',self._open_audio_export,
             w=161,h=29,fill=ACTION_YELLOW,fg=BG,bg=LAB_SURFACE,
             font=(self.ui_font,9,'bold')).pack(side='right',padx=(6,0))
        self._export_cancel_button=LabButton(footer,'Abbrechen',self._cancel_audio_export,
                     w=89,h=28,bg=LAB_SURFACE,font=(self.ui_font,9))
        self._export_status=tk.Label(lab,bg=LAB_SURFACE,fg=MUTED,anchor='w',
                      font=(self.ui_font,9))
        self._export_status.pack(fill='x',pady=(0,2))

        def layout_cards(event):
            columns=3 if event.width>830 else 2 if event.width>510 else 1
            if getattr(cards,'_columns',None)==columns:return
            cards._columns=columns
            for col in range(3):cards.columnconfigure(col,weight=1 if col<columns else 0)
            for index,card in enumerate(self._mixer_card_frames):
                card.grid(row=index//columns,column=index%columns,sticky='nsew',padx=4,pady=3)
        cards.bind('<Configure>',layout_cards)
        self._refresh_lab_values()
        return shell

    def _show_mixer_view(self,name):
        """Open mixer cards as full main-content pages (Producer-Hub pattern)."""
        if name == 'overview':
            self._close_mixer_focus()
        elif name in ('eq', 'tempo', 'pitch'):
            self._open_mixer_focus(name)

    def _open_mixer_focus(self, name):
        """Replace only the central content; sidebar and playback stay visible.

        Cached player and editor widgets retain the exact same audio/DB state.
        """
        if name not in ('eq', 'tempo', 'pitch'):
            return
        if self.active_page != 'player':
            self.show_page('player')
        if not hasattr(self, '_mixer_focus_pages'):
            self._mixer_focus_pages = {}
        if getattr(self, '_mixer_focus_active', False):
            active = self.nav_view
            if getattr(self, '_mixer_focus_name', None) == name:
                return
            if active is not None and active.winfo_exists():
                active.pack_forget()
        else:
            player = self.nav_view
            if player is not None and player.winfo_exists():
                player.pack_forget()
                self._page_cache['player'] = player
        view = self._mixer_focus_pages.get(name)
        if view is None or not view.winfo_exists():
            view = tk.Frame(self.content_host, bg=BG)
            self._mixer_focus_pages[name] = view
            self._build_mixer_focus_page(view, name)
        self._mixer_focus_active = True
        self._mixer_focus_name = name
        self.nav_view = view
        view.pack(fill='both', expand=True, padx=20, pady=16)
        self._refresh_lab_values()
        self._update_sidebar_highlight()
        self._focus_player_shortcuts()

    def _close_mixer_focus(self, restore=True):
        """Close focus page without destroying its cached controls."""
        if not getattr(self, '_mixer_focus_active', False):
            return
        current = self.nav_view
        if current is not None and current.winfo_exists():
            current.pack_forget()
        self._mixer_focus_active = False
        self._mixer_focus_name = None
        player = self._page_cache.get('player')
        self.nav_view = player if player is not None and player.winfo_exists() else None
        if restore:
            if self.nav_view is not None:
                self.nav_view.pack(fill='both', expand=True, padx=20, pady=16)
                self._refresh_large_player(force_cover=False)
            self._refresh_lab_values()
            self._focus_player_shortcuts()

    def _build_mixer_focus_page(self, parent, name):
        """Full-screen-style editor inside the existing app, no nested scroll pane."""
        titles = {
            'eq': ('Equalizer', 'Klangbild präzise formen · Frequenzen und Presets'),
            'tempo': ('Tempo', 'Geschwindigkeit präzise steuern · BPM und Prozent'),
            'pitch': ('Tonhöhe', 'Transposition und Feinstimmung · Halbton und Cent'),
        }
        title, desc = titles[name]
        header = tk.Frame(parent, bg=BG)
        header.pack(fill='x', pady=(0, 5))
        LabButton(header, '← Zurück zum Player', self._close_mixer_focus,
                  w=192, h=36, bg=BG, font=(self.ui_font, 10, 'bold')).pack(side='left', padx=(0, 15))
        caption = tk.Frame(header, bg=BG)
        caption.pack(side='left', fill='x', expand=True)
        tk.Label(caption, text=f'Mixer  /  {title}', bg=BG, fg=TEXT,
                 font=(self.ui_font, 19, 'bold')).pack(anchor='w')
        tk.Label(caption, text=desc, bg=BG, fg='#BDA4D0',
                 font=(self.ui_font, 10)).pack(anchor='w', pady=(1, 0))

        workspace = RoundedPane(parent, BG, LAB_SURFACE, border='#7854A3', padding=9)
        workspace.pack(fill='both', expand=True, pady=(0, 4))
        container = workspace.content
        toolbar = tk.Frame(container, bg=LAB_SURFACE)
        toolbar.pack(fill='x', pady=(0, 6))
        for key, label in (('eq', 'Equalizer'), ('tempo', 'Tempo'), ('pitch', 'Tonhöhe')):
            LabButton(toolbar, label, lambda target=key:self._open_mixer_focus(target),
                      w=108, h=32, bg=LAB_SURFACE,
                      fill='#583278' if key == name else '#2A1B42',
                      font=(self.ui_font, 9, 'bold')).pack(side='left', padx=(0, 8))
        LabButton(toolbar, 'Audio exportieren …', self._open_audio_export,
                  w=177, h=33, bg=LAB_SURFACE, fill=ACTION_YELLOW, fg=BG,
                  font=(self.ui_font, 9, 'bold')).pack(side='right')

        # Existing real DSP widgets are reused without a second state model.
        detail = tk.Frame(container, bg=LAB_SURFACE)
        detail.pack(fill='both', expand=True)
        if name == 'eq':
            left = tk.Frame(detail, bg=LAB_SURFACE)
            left.pack(side='left', fill='both', expand=True, padx=(0, 12))
            eq = self._build_player_equalizer(left)
            eq.pack(fill='both', expand=True)
            right = RoundedPane(detail, LAB_SURFACE, LAB_SURFACE,
                                border='#684987', padding=10)
            right.pack(side='left', fill='both', expand=True)
            self._mixer_panel_title(right.content, 'Feinabstimmung',
                                    'Direkte Bandwerte · individuelle Presets')
            self._add_mixer_eq_precision(right.content)
        else:
            # The page header already supplies the title and explanatory line.
            # Suppressing the former in-panel duplicate also keeps compact
            # Windows viewport sizes fully visible without scrolling.
            self._mixer_full_page_build = True
            try:
                if name == 'tempo':
                    self._build_mixer_tempo(detail)
                else:
                    self._build_mixer_pitch(detail)
            finally:
                self._mixer_full_page_build = False

        footer = RoundedPane(parent, BG, LAB_SURFACE, border='#65448A', padding=5)
        footer.pack(fill='x')
        bar = footer.content
        tk.Label(bar, text='A/B-Schleife', bg=LAB_SURFACE, fg='#F2D3FF',
                 font=(self.ui_font, 10, 'bold')).pack(side='left', padx=(1, 12))
        for index, label in enumerate(('A setzen', 'B setzen')):
            LabButton(bar, label, lambda idx=index:self._set_lab_marker(idx),
                      w=84, h=30, bg=LAB_SURFACE,
                      font=(self.ui_font, 9)).pack(side='left', padx=(0, 6))
        loop = LabButton(bar, 'Schleife: aus', self._toggle_lab_loop,
                         w=112, h=30, bg=LAB_SURFACE, font=(self.ui_font, 9))
        loop.pack(side='left', padx=(0, 6))
        if not hasattr(self, '_mixer_focus_loop_buttons'):
            self._mixer_focus_loop_buttons = []
        self._mixer_focus_loop_buttons.append(loop)
        LabButton(bar, 'Löschen', self._reset_lab_markers,
                  w=75, h=30, bg=LAB_SURFACE,
                  font=(self.ui_font, 9)).pack(side='left', padx=(0, 8))
        LabButton(bar, 'Audio exportieren …', self._open_audio_export,
                  w=168, h=30, bg=LAB_SURFACE,
                  fill=ACTION_YELLOW, fg=BG, font=(self.ui_font, 9, 'bold')).pack(side='right')

    def _mixer_bind_wheel(self,widget):
        def wheel(event):
            canvas=self._mixer_scroll
            if canvas.yview()[0]==0 and canvas.yview()[1]==1:
                return None
            amount=-1 if getattr(event,'delta',0)>0 or getattr(event,'num',0)==4 else 1
            canvas.yview_scroll(amount*2,'units')
            return 'break'
        # Wheel binds only to the displayed mixer module and is not global.
        # Entries keep their own ordinary focus/text behaviour.
        if not isinstance(widget,(tk.Entry,ttk.Combobox,tk.Scale)):
            widget.bind('<MouseWheel>',wheel,add='+')
            widget.bind('<Button-4>',wheel,add='+')
            widget.bind('<Button-5>',wheel,add='+')
        for child in widget.winfo_children():
            self._mixer_bind_wheel(child)

    def _mixer_panel_title(self,parent,title,description):
        if getattr(self, '_mixer_full_page_build', False):
            return
        tk.Label(parent,text=title,bg=LAB_SURFACE,fg='#F2D3FF',
                 font=(self.ui_font,14,'bold')).pack(anchor='w',padx=8,pady=(5,1))
        tk.Label(parent,text=description,bg=LAB_SURFACE,fg=MUTED,
                 font=(self.ui_font,9)).pack(anchor='w',padx=8,pady=(0,8))

