    def _mixer_set_tempo(self,value):
        if not(self.ffmpeg and self.audio.supports_eq):return
        self._lab_percent.set(max(50,min(200,round(float(value),1))))
        self._change_lab_values()

    def _mixer_shift_tempo(self,delta):
        self._mixer_set_tempo(self._lab_percent.get()+delta)

    def _mixer_set_percent(self,event=None):
        if not(self.ffmpeg and self.audio.supports_eq):return
        field=getattr(self,'_mixer_tempo_percent_entry',None)
        if field is None:return
        try:value=float(field.get().replace(',','.').replace('%','').strip())
        except ValueError:
            self._refresh_lab_values();return
        if not 50<=value<=200:
            self._refresh_lab_values();return
        self._mixer_set_tempo(value)
        if event is not None and getattr(event,'keysym','')=='Return':
            self.focus_set()

    def _mixer_set_bpm(self,event=None):
        if not(self.ffmpeg and self.audio.supports_eq):return
        bpm=getattr(self,'_lab_track_bpm',None)
        if not bpm or float(bpm)<=0:return
        field=getattr(self,'_mixer_bpm_entry',None)
        if field is None:return
        try:value=float(field.get().replace(',','.').strip())
        except ValueError:
            self._refresh_lab_values();return
        ratio=100*value/float(bpm)
        if not 50<=ratio<=200:
            self._refresh_lab_values();return
        self._mixer_set_tempo(ratio)
        if event is not None and getattr(event,'keysym','')=='Return':
            self.focus_set()

    def _mixer_set_pitch(self,value):
        if not(self.ffmpeg and self.audio.supports_eq):return
        self._lab_pitch.set(int(value)); self._change_lab_values()

    def _mixer_shift_cents(self,value):
        if not(self.ffmpeg and self.audio.supports_eq):return
        self._lab_cents.set(max(-100,min(100,self._lab_cents.get()+value)))
        self._change_lab_values()

    def _add_mixer_eq_precision(self,parent):
        """Additional useful EQ operations, editing the same filter state as playback/export."""
        line=tk.Frame(parent,bg=LAB_SURFACE)
        line.pack(fill='x',padx=8,pady=6)
        tk.Label(line,text='Bandwert direkt (dB)',bg=LAB_SURFACE,fg='#F0D0FF',
                 font=(self.ui_font,10,'bold')).pack(anchor='w')
        inputs=tk.Frame(line,bg=LAB_SURFACE)
        inputs.pack(fill='x',pady=4)
        self._mixer_eq_inputs=[]
        for i,hz in enumerate(EQ_BANDS):
            column=tk.Frame(inputs,bg=LAB_SURFACE)
            column.grid(row=0,column=i,padx=5,sticky='ew')
            inputs.columnconfigure(i,weight=1)
            tk.Label(column,text=f'{hz:g} Hz' if hz<1000 else f'{hz/1000:g}k',
                     bg=LAB_SURFACE,fg=MUTED,font=(self.ui_font,8)).pack()
            entry=tk.Entry(column,width=6,justify='center',bg='#37234F',fg=TEXT,
                     insertbackground=TEXT,relief='flat',font=(self.ui_font,10))
            entry.pack(pady=3)
            entry.insert(0,f'{self.eq_gains[i]:+.1f}')
            def change(event,n=i,widget=entry):
                try:gain=float(widget.get().replace(',','.'))
                except ValueError:return
                if -12<=gain<=12 and self.audio.supports_eq:
                    self._eq_variables[n].set(round(gain,1));self._apply_player_eq()
            entry.bind('<Return>',change)
            entry.bind('<FocusOut>',change)
            self._mixer_eq_inputs.append(entry)
        actions=tk.Frame(parent,bg=LAB_SURFACE)
        actions.pack(fill='x',padx=8,pady=(0,5))
        LabButton(actions,'Preset speichern',self._mixer_save_eq_preset,w=135,h=29,
             bg=LAB_SURFACE,font=(self.ui_font,9)).pack(side='left',padx=(0,7))
        LabButton(actions,'Preset laden',self._mixer_load_eq_preset,w=115,h=29,
             bg=LAB_SURFACE,font=(self.ui_font,9)).pack(side='left')

    def _mixer_save_eq_preset(self):
        self.save_setting('mixer_custom_eq',','.join(f'{x:g}' for x in self.eq_gains))
        self._export_status.configure(text='EQ-Preset gespeichert.')

    def _mixer_load_eq_preset(self):
        try:
            vals=tuple(float(x) for x in self.setting('mixer_custom_eq','').split(','))
        except ValueError:return
        if len(vals)!=len(EQ_BANDS) or not all(-12<=v<=12 for v in vals):return
        if not self.audio.supports_eq:return
        for variable,value in zip(self._eq_variables,vals):variable.set(value)
        self._apply_player_eq()

    def _refresh_lab_values(self):
        if not hasattr(self,'_lab_percent') or not hasattr(self,'_lab_marks_text'):return
        percent=float(self._lab_percent.get())
        bpm=getattr(self,'_lab_track_bpm',None)
        target=float(bpm)*percent/100 if bpm else None
        pitch=int(self._lab_pitch.get());cents=int(self._lab_cents.get())
        summaries={'eq':('EQ aktiv' if self.eq_enabled else 'EQ aus'),
                   'tempo':(f'{target:.1f} BPM' if target else f'{percent:.1f} %'),
                   'pitch':f'{pitch:+d} HT · {cents:+d} ct'}
        for key,widget in self._mixer_summaries.items():
            widget.configure(text=summaries[key])
        if hasattr(self,'_lab_tempo_text'):
            self._lab_tempo_text.configure(text=f'Original: {float(bpm):g} BPM' if bpm else 'Originaltempo: unbekannt')
            self._lab_target_text.configure(text=f'Ziel: {target:.1f} BPM' if target else 'Zieltempo: –')
            self._lab_percent_text.configure(text=f'{percent:.1f} %')
            for attr,content in (('_mixer_bpm_entry',f'{target:.1f}' if target else ''),
                                  ('_mixer_tempo_percent_entry',f'{percent:.1f} %')):
                field=getattr(self,attr,None)
                if field is not None and self.focus_get() is not field:
                    field.delete(0,'end');field.insert(0,content)
            self._mixer_bpm_entry.configure(state='normal' if bpm else 'disabled')
            self._mixer_tempo_dial.draw(force=True)
            self._mixer_tempo_slider.draw()
        if hasattr(self,'_lab_pitch_text'):
            self._lab_pitch_text.configure(text=f'{pitch:+d} Halbtöne')
            self._mixer_cent_text.configure(text=f'{cents:+d} Cent')
            self._mixer_pitch_dial.draw(force=True)
            self._mixer_pitch_slider.draw();self._mixer_cent_slider.draw()
        def label_time(value):
            if value is None:return '–'
            minutes,milliseconds=divmod(round(value*1000),60000)
            seconds,millis=divmod(milliseconds,1000)
            return f'{minutes}:{seconds:02d},{millis:03d}'
        labels=[f'{n}: {label_time(v)}' for n,v in zip('AB',self.lab_marks)]
        self._lab_marks_text.configure(text='   ·   '.join(labels))
        self._lab_loop_button.fg=ACTION_YELLOW if self.lab_loop else TEXT
        self._lab_loop_button.set_text('Schleife: an' if self.lab_loop else 'Schleife: aus')
        for button in getattr(self, '_mixer_focus_loop_buttons', ()):
            if button.winfo_exists():
                button.fg = ACTION_YELLOW if self.lab_loop else TEXT
                button.set_text('Schleife: an' if self.lab_loop else 'Schleife: aus')
        self.large_progress.set_lab_markers(*self.lab_marks,self.lab_loop)

    def _change_lab_values(self,event=None):
        self.lab_tempo=round(float(self._lab_percent.get())/100,3)
        self.lab_pitch=float(self._lab_pitch.get())+float(self._lab_cents.get())/100
        self._refresh_lab_values()
        if self._lab_apply_job is not None:self.after_cancel(self._lab_apply_job)
        self._lab_apply_job=self.after(220,self._apply_lab_values)

    def _apply_lab_values(self):
        if self._lab_apply_job is not None:
            self.after_cancel(self._lab_apply_job)
            self._lab_apply_job = None
        if self.audio.supports_eq:
            self.audio.set_lab(self.lab_tempo, self.lab_pitch, self._lab_range() if self.lab_loop else None)

    def _lab_range(self):
        a, b = self.lab_marks
        return (a, b) if a is not None and b is not None and b - a >= .25 else None

    def _set_lab_marker(self, index, position=None):
        if not self.active_track or not self.cur_len:
            return
        point = self.current_pos() if position is None else position
        self.lab_marks[index] = max(0.0, min(self.cur_len, point))
        if not self._lab_range():
            self.lab_loop = False
        self._apply_lab_values()
        self._refresh_lab_values()

    def _toggle_lab_loop(self):
        if not self.audio.supports_eq:
            return
        region = self._lab_range()
        if not region:
            self._lab_marks_text.configure(text='A und B mit mindestens 0,25 s Abstand setzen.')
            return
        self.lab_loop = not self.lab_loop
        if self.lab_loop and getattr(self, '_restored_song_pending', False) and not region[0] <= self.offset < region[1]:
            self.offset = region[0]
        self._apply_lab_values()
        self._refresh_lab_values()
        self.large_progress.focus_set()

    def _reset_lab_markers(self):
        self.lab_marks = [None, None]
        self.lab_loop = False
        self._apply_lab_values()
        self._refresh_lab_values()

    def _set_audio_export_folder(self, label):
        default = self.setting('audio_export_folder', '')
        folder = filedialog.askdirectory(parent=self, title='Standardordner für Audioexporte',
                                         initialdir=default if default and Path(default).is_dir() else str(Path.home()),
                                         mustexist=True)
        if folder:
            self.save_setting('audio_export_folder', folder)
            label.configure(text=folder)

    def _open_audio_export(self):
        path = self.active_track
        if not path or not self.cur_len:
            messagebox.showinfo('Audio exportieren', 'Wähle zuerst einen Titel aus.', parent=self)
            return
        if self._export_cancel is not None:
            return
        if not self.audio.supports_eq:
            messagebox.showinfo('Audio exportieren', 'Für den Export ist die Mixer-Audioverarbeitung erforderlich.', parent=self)
            return
        self._apply_lab_values()
        loop = self._lab_range()
        whole = (0.0, self.cur_len)
        tempo, pitch = self.lab_tempo, self.lab_pitch
        gains = self.eq_gains if self.eq_enabled else EQ_NEUTRAL
        dialog = tk.Toplevel(self)
        dialog.title('Mixer · Audio exportieren')
        dialog.configure(bg=SURFACE)
        dialog.transient(self)
        dialog.resizable(False, False)
        summary=tk.Label(dialog,bg=SURFACE,fg='#E8CBFF',justify='left',
            font=(self.ui_font,10),text=(f'Equalizer: {"Aktiv" if self.eq_enabled else "Aus"}  ·  '
               f'Tempo: {tempo*100:.1f} %  ·  Tonhöhe: {pitch:+.2f} Halbtöne'))
        summary.pack(anchor='w',padx=18,pady=(12,5))
        scope = tk.StringVar(value='ab' if loop else 'all')
        for key, title in (('all', 'Ganzer Titel'), ('ab', 'A/B-Ausschnitt')):
            tk.Radiobutton(dialog, text=title, variable=scope, value=key,
                           state='normal' if key == 'all' or loop else 'disabled',
                           selectcolor='#3E285D', activebackground=SURFACE, activeforeground=TEXT,
                           bg=SURFACE, fg=TEXT, font=(self.ui_font, 10),
                           command=lambda: refresh()).pack(anchor='w', padx=18, pady=(7, 0))
        duration = tk.Label(dialog, bg=SURFACE, fg=MUTED, font=(self.ui_font, 10))
        duration.pack(anchor='w', padx=18, pady=10)
        def selection():
            return loop if scope.get() == 'ab' and loop else whole
        def refresh():
            a, b = selection()
            duration.configure(text=f'WAV · 24 Bit · Dauer ca. {fmt_time((b-a)/tempo)}')
        def save():
            base = self.setting('audio_export_folder', '')
            folder = base if base and Path(base).is_dir() else str(Path(path).parent)
            suffix = 'A-B' if scope.get() == 'ab' and loop else 'Mixer'
            destination = filedialog.asksaveasfilename(
                parent=dialog, title='WAV speichern', initialdir=folder,
                initialfile=f'{Path(path).stem} - {suffix}.wav', defaultextension='.wav',
                filetypes=[('WAV-Audio', '*.wav')], confirmoverwrite=False)
            if not destination:
                return
            target = Path(destination)
            if target.suffix.lower() != '.wav':
                target = target.with_name(target.name + '.wav')
            if target.exists():
                messagebox.showinfo('Audio exportieren', 'Diese Datei existiert bereits. Wähle einen anderen Namen.', parent=dialog)
                return
            a, b = selection()
            dialog.destroy()
            self._start_audio_export(path, target, a, b, tempo, pitch, gains)
        Pill(dialog, 'Speichern …', save, w=120, h=32, fill=ACTION_YELLOW,
             fg=BG, bg=SURFACE, font=(self.ui_font, 9, 'bold')).pack(anchor='e', padx=18, pady=(0, 13))
        refresh()
        dialog.bind('<Escape>', lambda event: dialog.destroy())
        dialog.grab_set()

    def _start_audio_export(self, path, target, start, end, tempo, pitch, gains):
        from queue import SimpleQueue
        from threading import Event, Thread

        cancel = self._export_cancel = Event()
        replies = SimpleQueue()
        progress = [0.0]
        self._export_status.configure(text='Export läuft … 0 %')
        self._export_cancel_button.pack(side='right')
        def worker():
            try:
                completed = export_sound_lab(path, target, start, end, tempo, pitch, gains,
                                             self.ffmpeg, cancel, lambda value: progress.__setitem__(0, value))
                replies.put((completed, None))
            except (OSError, RuntimeError, ValueError, ImportError) as exc:
                replies.put((False, str(exc)))
        def poll():
            if replies.empty():
                self._export_status.configure(text=f'Export läuft … {round(progress[0] * 100)} %')
                self.after(125, poll)
                return
            completed, error = replies.get()
            self._export_cancel = None
            self._export_cancel_button.pack_forget()
            if completed:
                self._export_status.configure(text=f'Gespeichert: {target.name}')
            elif error:
                self._export_status.configure(text='Export fehlgeschlagen')
                messagebox.showerror('Audio exportieren', error, parent=self)
            else:
                self._export_status.configure(text='Export abgebrochen')
        Thread(target=worker, name='KLN-Export', daemon=False).start()
        self.after(125, poll)

    def _cancel_audio_export(self):
        if self._export_cancel is not None:
            self._export_cancel.set()

