    def _build_player_equalizer(self, parent):
        shell = RoundedPane(parent, LAB_SURFACE, LAB_CARD, border='#76509B', padding=12)
        frame = shell.content
        LabAccent(frame).pack(fill='x', pady=(0, 5))
        controls = tk.Frame(frame, bg=LAB_CARD)
        controls.pack(fill='x')
        self._eq_switch = tk.BooleanVar(value=self.eq_enabled)
        tk.Label(controls, text='Equalizer', bg=LAB_CARD, fg=TEXT,
                 font=(self.ui_font, 15, 'bold')).pack(side='left')
        def toggle_eq():
            self._eq_switch.set(not self._eq_switch.get())
            self._apply_player_eq()
        self._eq_enabled_button = enabled = LabSwitch(controls, '', toggle_eq, w=75, h=27,
                                                  bg=LAB_CARD, font=(self.ui_font, 9, 'bold'))
        enabled.pack(side='right', padx=7)
        presets_row = tk.Frame(frame, bg=LAB_CARD)
        presets_row.pack(fill='x', pady=(9, 2))
        preset = self._eq_preset = tk.StringVar(value=self._matching_eq_preset())
        style = ttk.Style(self)
        style.configure('SoundLab.TCombobox', fieldbackground='#43265C', background='#3D2558',
                        foreground=TEXT, arrowcolor='#F0C5FF', bordercolor='#895BB2',
                        darkcolor='#3D2558', lightcolor='#553174', padding=(8, 5))
        style.map('SoundLab.TCombobox', fieldbackground=[('readonly', '#43265C')],
                  foreground=[('readonly', TEXT)], selectbackground=[('readonly', '#5B347B')],
                  selectforeground=[('readonly', TEXT)], background=[('readonly', '#3D2558')],
                  bordercolor=[('focus','#C27BF3'),('active','#A86BDE')])
        combo = ttk.Combobox(presets_row, textvariable=preset, style='SoundLab.TCombobox',
                             values=tuple(EQ_PRESETS), width=15, state='readonly',
                             font=(self.ui_font, 9))
        popdown = combo.tk.call('ttk::combobox::PopdownWindow', combo._w)
        combo.tk.call(f'{popdown}.f.l', 'configure', '-background', '#291941',
                      '-foreground', TEXT, '-selectbackground', '#583482', '-selectforeground', TEXT)
        combo.pack(side='left', padx=7)
        combo.bind('<<ComboboxSelected>>', lambda event: self._select_eq_preset(preset.get()))
        reset = LabButton(presets_row, 'Zurücksetzen', lambda: self._select_eq_preset('Neutral'),
                     w=104, h=28, bg=LAB_CARD, font=(self.ui_font, 9))
        reset.pack(side='left')

        bands = tk.Frame(frame, bg=LAB_CARD)
        bands.pack(fill='x', pady=(7, 0))
        self._eq_variables = []
        self._eq_values = []
        sliders = []
        for i, hz in enumerate(EQ_BANDS):
            band = tk.Frame(bands, bg=LAB_CARD)
            band.grid(row=0, column=i, sticky='ew')
            bands.columnconfigure(i, weight=1, uniform='eq_bands')
            label = tk.Label(band, bg=LAB_CARD, fg=ACTION_YELLOW, font=(self.ui_font, 9, 'bold'))
            label.pack()
            self._eq_values.append(label)
            value = tk.DoubleVar(value=self.eq_gains[i])
            self._eq_variables.append(value)
            slider = EqFader(band, value, self._apply_player_eq, self.audio.supports_eq)
            slider.pack(fill='x')
            sliders.append(slider)
            frequency = f'{hz / 1000:g} kHz'.replace('.', ',') if hz >= 1000 else f'{hz} Hz'
            tk.Label(band, text=frequency, bg=LAB_CARD, fg=TEXT,
                     font=(self.ui_font, 9)).pack()
        self._eq_sliders = sliders
        self._update_eq_readout()

        if not self.audio.supports_eq:
            enabled.command = lambda: None
            combo.configure(state='disabled')
            reset.command = lambda: None
            tk.Label(frame, text='EQ nicht verfügbar. Prüfe die Standard-Audioausgabe und ob sounddevice, soundfile und scipy installiert sind.',
                     bg=LAB_CARD, fg=MUTED, justify='left', wraplength=395,
                     font=(self.ui_font, 9)).pack(anchor='w', pady=(6, 0))
        return shell

    def _matching_eq_preset(self):
        return next((name for name, values in EQ_PRESETS.items() if values == self.eq_gains), 'Benutzerdefiniert')

    def _update_eq_readout(self):
        for label, gain in zip(self._eq_values, self.eq_gains):
            label.configure(text=f'{gain:+.0f} dB' if gain else '0 dB')
        self._eq_preset.set(self._matching_eq_preset())
        enabled = self.audio.supports_eq and self.eq_enabled
        button = self._eq_enabled_button
        button.fill = '#613599' if enabled else SURFACE2
        button.fg = ACTION_YELLOW if enabled else TEXT
        button.set_text('Ein' if enabled else 'Aus')
        for slider in self._eq_sliders:
            slider.draw()
        for widget,value in zip(getattr(self,'_mixer_eq_inputs',()),self.eq_gains):
            if self.focus_get() is not widget:
                widget.delete(0,'end');widget.insert(0,f'{value:+.1f}')
        if hasattr(self,'_mixer_summaries') and 'eq' in self._mixer_summaries:
            self._mixer_summaries['eq'].configure(text='EQ aktiv' if self.eq_enabled else 'EQ aus')

    def _apply_player_eq(self):
        if not self.audio.supports_eq:
            return
        self.eq_enabled = self._eq_switch.get()
        self.eq_gains = tuple(value.get() for value in self._eq_variables)
        self.audio.set_eq(self.eq_gains if self.eq_enabled else EQ_NEUTRAL)
        self._update_eq_readout()
        if self._eq_save_job is not None:
            self.after_cancel(self._eq_save_job)
        self._eq_save_job = self.after(220, self._save_player_eq)

    def _select_eq_preset(self, name):
        if name not in EQ_PRESETS or not self.audio.supports_eq:
            return
        for value, gain in zip(self._eq_variables, EQ_PRESETS[name]):
            value.set(gain)
        self._apply_player_eq()

    def _save_player_eq(self):
        self._eq_save_job = None
        self.save_setting('player_eq_enabled', '1' if self.eq_enabled else '0')
        self.save_setting('player_eq_gains', ','.join(f'{gain:g}' for gain in self.eq_gains))

