    def _refresh_player_details(self):
        path = self.active_track if self.playing else None
        row = self.db.execute("SELECT bpm,tonart,genre,mood,rating FROM tracks WHERE path=?",
                              (path,)).fetchone() if path else None
        if row is None:
            self.large_meta.configure(text='Kein Titel geladen.')
            return
        bpm, key, genre, mood, rating = row
        self.large_meta.configure(text=(
            f"BPM  {self._display_bpm(bpm) or '–'}    ·    Tonart  {key or '–'}    ·    "
            f"Camelot  {camelot_code(key) or '–'}\n"
            f"Genre  {genre or '–'}    ·    Mood  {mood or '–'}    ·    Bewertung  {rating or 0}/5"))

    def _refresh_player_queue(self):
        start = max(0, self.index + 1)
        signature = (id(self.queue), len(self.queue), start)
        if signature == self._player_queue_signature:
            return
        self._player_queue_signature = signature
        upcoming = self.queue[start:]
        tree = self._player_queue_list
        selected = tree.selection()
        tree.delete(*tree.get_children())
        tree.tag_configure('manual', foreground='#DAB5FF')
        if upcoming:
            names = dict(self.db.execute('SELECT path, title FROM tracks'))
            for path in upcoming:
                manual = path in self.manual_queue
                title = names.get(path) or Path(path).stem
                tree.insert('', 'end', iid=path, text=('＋  ' if manual else '') + title,
                            tags=('manual',) if manual else ())
        manual_count = sum(path in self.manual_queue for path in upcoming)
        summary = f'{len(upcoming)} Titel' if upcoming else 'Keine weiteren Titel'
        if manual_count:
            summary += f' · {manual_count} manuell (＋)'
        self._queue_summary.configure(text=summary)
        if selected and tree.exists(selected[0]):
            tree.selection_set(selected[0])

    def _play_from_queue(self):
        selected = self._player_queue_list.selection()
        if selected and selected[0] in self.queue:
            target = max(0, self.index + 1)
            index = self.queue.index(selected[0])
            if index >= target:
                self.queue.insert(target, self.queue.pop(index))
                self.play_index(target)
        return 'break'

    def _change_queue_selection(self, direction):
        selected = self._player_queue_list.selection()
        if not selected or selected[0] not in self.queue:
            return
        index = self.queue.index(selected[0])
        if index <= self.index:
            return
        if direction is None:
            self.queue.pop(index)
            self.manual_queue.discard(selected[0])
        else:
            target = index + direction
            if not self.index < target < len(self.queue):
                return
            if (self.queue[index] in self.manual_queue) != (self.queue[target] in self.manual_queue):
                return
            self.queue[index], self.queue[target] = self.queue[target], self.queue[index]
        self._player_queue_signature = None
        self._refresh_player_queue()

    def _player_queue_press(self, event):
        path = self._player_queue_list.identify_row(event.y)
        self._queue_drag = (path, event.y) if path else None

    def _player_queue_drag(self, event):
        if self._queue_drag and abs(event.y - self._queue_drag[1]) >= 6:
            tree = self._player_queue_list
            target = tree.identify_row(event.y)
            if target:
                tree.focus(target)
                tree.selection_set(target)
            return 'break'

    def _player_queue_drop(self, event):
        drag, self._queue_drag = self._queue_drag, None
        if not drag or abs(event.y - drag[1]) < 6:
            return
        tree = self._player_queue_list
        target = tree.identify_row(event.y)
        if not target and event.y >= tree.winfo_height() - 20:
            children = tree.get_children()
            target = children[-1] if children else ''
        path = drag[0]
        if (target and path != target and path in self.queue and target in self.queue
                and (path in self.manual_queue) == (target in self.manual_queue)):
            box = tree.bbox(target)
            after = bool(box and event.y >= box[1] + box[3] / 2)
            self.queue.remove(path)
            self.queue.insert(self.queue.index(target) + after, path)
            self._player_queue_signature = None
            self._refresh_player_queue()
            tree.selection_set(path)
            tree.see(path)
        return 'break'

    def _update_player_modes(self):
        self._repeat_button.show_state(self.player_repeat != 'off', self.player_repeat == 'one')
        self._shuffle_button.show_state(self.player_shuffle)

    def _cycle_player_repeat(self):
        self.player_repeat = {'off': 'one', 'one': 'all', 'all': 'off'}[self.player_repeat]
        self.save_setting('player_repeat', self.player_repeat)
        self._update_player_modes()

    def _toggle_player_shuffle(self):
        self.player_shuffle = not self.player_shuffle
        self.save_setting('player_shuffle', '1' if self.player_shuffle else '0')
        self._update_player_modes()

    def _preview_player_time(self, position):
        shown = fmt_time(position)
        if self.large_time.cget('text') != shown:
            self.large_time.configure(text=shown)

    def _cancel_waveform(self):
        if self._wave_pending is not None:
            future, cancel = self._wave_pending
            cancel.set()
            future.cancel()
            self._wave_pending = None

    def _request_player_waveform(self, path, duration):
        from threading import Event

        self._cancel_waveform()
        self._wave_requested_path = path
        self._wave_key = None
        if not path:
            self.large_progress.set_track(0, message='Kein Titel geladen')
            return
        try:
            stat = Path(path).stat()
        except OSError:
            self.large_progress.set_track(duration, message='Audiodatei nicht verfügbar')
            return
        key = self._wave_key = (path, stat.st_size, stat.st_mtime_ns)
        if key in self._wave_cache:
            self._wave_cache.move_to_end(key)
            peaks = self._wave_cache[key]
            self.large_progress.set_track(duration, peaks, '' if peaks else 'Wellenform nicht verfügbar')
            return
        peaks = _wave_disk_read(key)
        if peaks is not None:
            self._wave_cache[key] = peaks
            if len(self._wave_cache) > 24:
                self._wave_cache.popitem(last=False)
            self.large_progress.set_track(duration, peaks)
            return
        cancel = Event()
        self.large_progress.set_track(duration, message='Wellenform wird geladen …')
        self._wave_pending = (self._wave_pool.submit(read_waveform, path, cancel), cancel)

    def _collect_player_waveform(self):
        if self._wave_pending is None:
            return
        future, cancel = self._wave_pending
        if not future.done():
            return
        self._wave_pending = None
        if cancel.is_set():
            return
        try:
            peaks = future.result()
        except (ImportError, OSError, RuntimeError, ValueError):
            peaks = ()
        self._wave_cache[self._wave_key] = peaks
        if len(self._wave_cache) > 24:
            self._wave_cache.popitem(last=False)
        if peaks:
            # Winzige JSON-Datei: kuenftige Programmlaeufe zeigen die Welle
            # ohne erneute Analyse. Ausnahmen haben keinen Einfluss auf Audio.
            _wave_disk_write(self._wave_key, peaks)
        self.large_progress.set_track(self.cur_len, peaks, '' if peaks else 'Wellenform nicht verfügbar')

    def _refresh_large_player(self, force_cover=False):
        if self.active_page != 'player' or not getattr(self, '_player_artwork', None):
            return
        path = self.active_track if self.playing else None
        if force_cover or self._large_cover_path != path:
            self._large_cover_path = path
            data = self.db.execute('SELECT title,artist,bpm FROM tracks WHERE path=?', (path,)).fetchone() if path else None
            title = (data[0] or Path(path).stem) if data else 'Kein Titel geladen'
            artist = (data[1] or 'Unbekannter Künstler') if data else ''
            self._player_title.configure(text=title)
            self._player_artist.configure(text=artist)
            self._lab_track_bpm = data[2] if data else None
            cover = self._cover_image(356, path)
            self._player_artwork.set_cover(cover)
            self.large_progress.cover_tint = cover.resize((1, 1)).getpixel((0, 0))[:3] if path else None
            self.large_progress._render()
            self._refresh_lab_values()
            if 'details' in self._player_open_panels:
                self._refresh_player_details()
        duration = self.cur_len if path else 0.0
        if self._wave_requested_path != path:
            self._request_player_waveform(path, duration)
        self._collect_player_waveform()
        self.large_progress.set_lab_markers(*self.lab_marks, self.lab_loop)
        current = min(self.current_pos(), duration) if path else 0.0
        self.large_progress.set_position(current)
        if not self.large_progress.dragging:
            self._preview_player_time(current)
        shown = fmt_time(duration)
        if self.large_duration.cget('text') != shown:
            self.large_duration.configure(text=shown)
        if 'queue' in self._player_open_panels:
            self._refresh_player_queue()

