    def _set_stat_scope(self, scope):
        if scope == self.stat_scope and not self._stats_dirty:
            return
        self.stat_scope = scope
        self._render_stats_page()

    def _stat_rows(self):
        sql = "SELECT length,genre,mood,rating,bpm,category FROM tracks"
        args = ()
        if self.stat_scope != "all":
            sql += " WHERE COALESCE(NULLIF(category,''),'beats')=?"
            args = (self.stat_scope,)
        return self.db.execute(sql, args).fetchall()

