        for main, recent in groups:
            column = tk.Frame(toolrows, bg=SURFACE, width=button_width, height=76)
            column.pack_propagate(False)
            Pill(column, main[0], main[1], w=button_width, h=32, bg=SURFACE,
                 font=(self.ui_font, 9)).pack(anchor='w')
            if recent:
                Pill(column, recent[0], recent[1], w=button_width, h=32, bg=SURFACE,
                     font=(self.ui_font, 9)).pack(anchor='w', pady=(8, 0))
            columns.append(column)
        def arrange_music_actions(event):
            count = max(1, min(len(columns), (event.width + 8) // (button_width + 8)))
            if count == getattr(toolrows, '_action_columns', None):
                return
            toolrows._action_columns = count
            wide = count == len(columns)
            toolrows.columnconfigure(3, weight=int(wide))
            for i, column in enumerate(columns):
                row, col = divmod(i, count)
                if wide and col >= 3:
                    col += 1
                column.grid(row=row, column=col, sticky='nw', padx=(0, 8), pady=(0, 8))
        toolrows.bind('<Configure>', arrange_music_actions)
