    def _change_header_mode(self,column,mode):
        if column is None:
            self.header_default_mode=mode
        else:
            self.header_column_modes[column]=mode
        self._draw_library_header()

    def _apply_sidebar_setting(self, collapsed):
        self.sidebar_collapsed = bool(collapsed)
        self._build_sidebar()
        self.after_idle(self.schedule_table_layout)

    def _change_seek_step(self, value):
        self.seek_step = int(value)

    def _update_bpm_format(self, value):
        self.bpm_decimals = value == "decimal"
        self.refresh()
        self._refresh_large_player(force_cover=True)

    def _update_uncertainty(self, value):
        self.show_uncertainty = value
        self.refresh()

