    # ---------- Suche, Favoriten, Statistiken und Cover ----------
    def focus_search_hotkey(self, event=None):
        if self._keyboard_in_text_field() or getattr(self, "menu_panel", None) and self.menu_panel.winfo_exists():
            return None
        self.show_search()
        return "break"

    def _dismiss_search_on_outside_click(self, event):
        if not self.search_open:
            return
        obj=event.widget
        while obj is not None:
            if obj in (self.search_box,self.search_button): return
            obj=getattr(obj,'master',None)
        self.hide_search(clear=False)

    def toggle_search(self):
        if self.search_open:
            self.hide_search(clear=False)
        else:
            self.show_search()

    def show_search(self):
        if not self.search_open:
            self.search_open = True
            self._position_search_box()
        self.search_box.entry.focus_set()
        if self.search_box._ph:
            self.search_box._focus_in(None)
        self.search_box.entry.selection_range(0, "end")

    def hide_search(self, clear=False):
        if not self.search_open:
            return
        self.search_open = False
        if clear:
            self.search_box.entry.delete(0, "end")
            self.search_box._show_placeholder()
        self.search_box.place_forget()
        self.status.pack_configure(padx=(0, 11))
        self._search_count_padding = None
        self._focus_player_shortcuts()
        if clear:
            self.search_box._last_query = ""
            if self.active_page == "flp": self._flp_search_changed("")
            else: self.refresh()

    def set_category(self, category):
        if category not in ("all", "beats", "remixes", "songs"):
            return
        self.category_filter = category
        self._update_category_buttons()
        self.refresh()

    def _update_category_buttons(self):
        for category, button in self.category_buttons.items():
            on = category == self.category_filter
            button.fill = YELLOW if on else "#342057"
            button.fg = "#160D2C" if on else TEXT
            button._draw(button.fill)

    def toggle_favorites(self):
        self.favorites_only = not self.favorites_only
        self.favorites_button.fill = YELLOW if self.favorites_only else "#342057"
        self.favorites_button.fg = BG if self.favorites_only else TEXT
        self.favorites_button.text = "★ Favoriten" if self.favorites_only else "☆ Favoriten"
        self.favorites_button._draw(self.favorites_button.fill)
        self.refresh()

    def toggle_statistics(self):
        self.show_page("stats")

    @staticmethod
    def _format_total_duration(seconds):
        minutes = int(seconds or 0) // 60
        return f"{minutes // 60} h {minutes % 60:02d} min" if minutes >= 60 else f"{minutes} min"

    def build_statistics(self):
        """Statistik über die gesamte Bibliothek, unabhängig von Suche/Favoritenfilter."""
        import collections
        for child in self.stats_panel.winfo_children():
            child.destroy()
        total, seconds, genres, favorites = self.db.execute(
            "SELECT COUNT(*), COALESCE(SUM(length),0), "
            "COUNT(DISTINCT NULLIF(TRIM(genre),'')), "
            "COALESCE(SUM(CASE WHEN rating>=4 THEN 1 ELSE 0 END),0) FROM tracks"
        ).fetchone()
        moods = self.db.execute("SELECT mood FROM tracks WHERE mood IS NOT NULL AND mood!=''").fetchall()
        counters = collections.Counter()
        recognized = 0
        for (raw,) in moods:
            parts = [part.strip() for part in str(raw).split("·") if part.strip()]
            if parts:
                recognized += 1
                counters[parts[0]] += 1.0
                if len(parts) > 1:
                    counters[parts[1]] += 0.5
        main = tk.Frame(self.stats_panel, bg="#191638", highlightbackground="#39305b",
                        highlightthickness=1)
        main.pack(fill="x", padx=18, pady=(5, 6))
        row = tk.Frame(main, bg="#191638")
        row.pack(fill="x", padx=12, pady=(9, 6))
        tk.Label(row, text="Statistiken", bg="#191638", fg=TEXT,
                 font=(self.ui_font, 10, "bold")).pack(side="left")
        cards = tk.Frame(main, bg="#191638")
        cards.pack(fill="x", padx=12)
        for title, value in (("Titel", str(total)),
                             ("Gesamtdauer", self._format_total_duration(seconds)),
                             ("Genres", str(genres))):
            item = tk.Frame(cards, bg=SURFACE2)
            item.pack(side="left", fill="x", expand=True, padx=(0, 6))
            tk.Label(item, text=title, bg=SURFACE2, fg=MUTED,
                     font=(self.ui_font, 9)).pack(anchor="w", padx=10, pady=(5, 0))
            tk.Label(item, text=value, bg=SURFACE2, fg=TEXT,
                     font=(self.ui_font, 13, "bold")).pack(anchor="w", padx=10, pady=(0, 6))
        bottom = tk.Frame(main, bg="#191638")
        bottom.pack(fill="x", padx=12, pady=(8, 10))
        mood_label = " · ".join(k for k, _ in counters.most_common(2)) if counters else "Noch keine Mood-Daten"
        tk.Label(bottom, text="Gesamt-Mood", bg="#191638", fg=MUTED,
                 font=(self.ui_font, 9)).pack(side="left")
        tk.Label(bottom, text=mood_label, bg="#191638", fg=YELLOW,
                 font=(self.ui_font, 10, "bold")).pack(side="left", padx=(10, 8))
        # Farbige gewichtete Mood-Verteilung.
        moodbar = tk.Canvas(bottom, bg="#191638", height=12, width=140,
                            highlightthickness=0, bd=0)
        moodbar.pack(side="left", padx=(0, 8))
        total_moods = sum(counters.values())
        x = 0
        if total_moods:
            for mood, count in counters.most_common():
                w = round(140 * count / total_moods)
                if w > 0:
                    moodbar.create_rectangle(x, 2, min(140, x+w), 10,
                                            fill=MOOD_COLORS.get(mood, PURPLE), outline="")
                x += w
        self.stats_fav_button = Pill(bottom, f"★ {favorites} Favoriten  →",
                                     lambda: self.toggle_favorites() if not self.favorites_only else None,
                                     w=165, h=29, fill=SURFACE2, bg="#191638", fg=YELLOW,
                                     font=(self.ui_font, 9))
        self.stats_fav_button.pack(side="right")

    def hover_track(self, event, offset=0):
        row = self.tree.identify_row(event.y + offset)
        if row == self.hovered_row:
            return
        self.clear_hover()
        if row and self.tree.exists(row) and row != self.active_track:
            self.hovered_row = row
            tags = list(self.tree.item(row, "tags"))
            self.tree.item(row, tags=(*tags, "hover"))

    def clear_hover(self):
        if self.hovered_row and self.tree.exists(self.hovered_row):
            tags = [tag for tag in self.tree.item(self.hovered_row, "tags") if tag != "hover"]
            self.tree.item(self.hovered_row, tags=tags)
        self.hovered_row = None

    def _song_cover_path(self, song):
        if not song:
            return None
        row = self.db.execute('SELECT image_path FROM song_covers WHERE path=?', (str(song),)).fetchone()
        if not row:
            return None
        stored = Path(row[0])
        if not stored.is_absolute():
            if stored.name != row[0]:
                return None
            for directory in (SONG_COVER_DIR, SONG_COVER_DIR.with_name("song_covers_test15_performance3"),
                              SONG_COVER_DIR.with_name("song_covers_test15_performance1"),
                              SONG_COVER_DIR.with_name("song_covers_test13"),
                              SONG_COVER_DIR.with_name("song_covers_test9"),
                              SONG_COVER_DIR.with_name("song_covers_test8"),
                              SONG_COVER_DIR.with_name("song_covers_test7"),
                              SONG_COVER_DIR.with_name("song_covers_test6_menuefix"),
                              SONG_COVER_DIR.with_name("song_covers_test6"),
                              SONG_COVER_DIR.with_name("song_covers_test5"),
                              SONG_COVER_DIR.with_name("song_covers_test4")):
                candidate = directory / stored
                if candidate.is_file():
                    return candidate
            return None
        if stored.is_file():
            return stored
        legacy = SONG_COVER_DIR.with_name("song_covers") / stored.name
        return legacy if legacy.is_file() else None

    def choose_song_cover(self, song):
        from PIL import Image
        import hashlib
        if not self.db.execute('SELECT 1 FROM tracks WHERE path=?',(str(song),)).fetchone():
            return
        original=filedialog.askopenfilename(parent=self,title='Eigenes Cover für diesen Song',
            filetypes=[('Bilder','*.png *.jpg *.jpeg *.webp'),('Alle Dateien','*.*')])
        if not original: return
        try:
            file=Path(original)
            if file.stat().st_size>15*1024*1024:
                raise ValueError('Bild größer als 15 MB')
            import tempfile
            directory = SONG_COVER_DIR
            directory.mkdir(parents=True,exist_ok=True)
            destination=directory/(hashlib.sha256(str(song).encode('utf-8')).hexdigest()+'.png')
            with Image.open(file) as image:
                image.verify()
            with Image.open(file) as image:
                image=Image.Image.convert(image,'RGBA')
                if image.width*image.height>35_000_000:
                    raise ValueError('Bildauflösung zu groß')
                with tempfile.NamedTemporaryFile(dir=directory, suffix=".png", delete=False) as file:
                    temporary = Path(file.name)
                try:
                    image.save(temporary, 'PNG')
                    temporary.replace(destination)
                finally:
                    temporary.unlink(missing_ok=True)
            self.db.execute('INSERT OR REPLACE INTO song_covers(path,image_path) VALUES(?,?)',
                            (str(song), destination.name))
            self.db.commit()
            if song==self.active_track: self._refresh_user_covers()
        except (OSError,ValueError) as exc:
            messagebox.showerror('Song-Cover',f'Das Cover konnte nicht gespeichert werden:\n{exc}',parent=self)

    def remove_song_cover(self, song):
        row=self.db.execute('SELECT image_path FROM song_covers WHERE path=?',(str(song),)).fetchone()
        self.db.execute('DELETE FROM song_covers WHERE path=?',(str(song),))
        self.db.commit()
        if row and Path(row[0]).name == row[0]:
            try:
                (SONG_COVER_DIR / row[0]).unlink(missing_ok=True)
            except OSError:
                pass
        if song==self.active_track: self._refresh_user_covers()

    def _restore_last_song(self):
        """Restore information and highlight, never autoplay audio."""
        song=self.setting('last_played_song','')
        if not song or not Path(song).is_file(): return
        row=self.db.execute('SELECT title,artist,length FROM tracks WHERE path=?',(song,)).fetchone()
        if not row: return
        self.active_track=song
        self.playing=True   # Nur Titel und Position anzeigen, Audio bleibt gestoppt.
        self.paused=True
        self._restored_song_pending=True
        self.queue=[x for x in self.tree.get_children() if Path(x).suffix.lower() in EXTS]
        self.index=self.queue.index(song) if song in self.queue else -1
        self.cur_len=float(row[2] or 0)
        self.offset=0
        self.now.config(text=row[0] or Path(song).stem)
        self.artist_lbl.config(text=row[1] or '')
        self.total_lbl.config(text=fmt_time(self.cur_len))
        self.seek.set_max(max(self.cur_len,1))
        self.seek.set(0)
        self.seek.enable(True)
        self.btn_play.set_text('▶')
        self._set_cover(song)
        self._update_playing_display()

    def _user_cover_path(self):
        raw=self.setting('player_custom_cover','').strip()
        return Path(raw) if raw else None

    def _cover_image(self, size, song=None):
        """A transparent KLN logo or full custom artwork, contained without cropping.

        The transparent PhotoImage is drawn over the native player background.
        JPEG backgrounds remain opaque; PNG alpha is never replaced by purple.
        """
        from PIL import Image
        custom=self._song_cover_path(song if song is not None else getattr(self,'active_track',None)) or self._user_cover_path()
        source=None
        if custom and custom.is_file():
            try:
                with Image.open(custom) as selected:
                    source=selected.convert('RGBA').copy()
            except (OSError,ValueError):
                source=None
        if source is None:
            source=Image.open(io.BytesIO(base64.b64decode(KLN_LOGO_PNG))).convert('RGBA')
        width,height=(size if isinstance(size,tuple) else (size,size))
        canvas=Image.new('RGBA',(width,height),(0,0,0,0))
        # Wide native logo gets the whole player slot; square albums fit inside.
        pad=2 if custom is None else 1
        source.thumbnail((width-2*pad,height-2*pad),Image.Resampling.LANCZOS)
        canvas.alpha_composite(source,((width-source.width)//2,(height-source.height)//2))
        return canvas

    def _set_cover(self,path):
        try:
            from PIL import ImageTk
            image=self._cover_image((126,82),path)
            self.cover_photo=ImageTk.PhotoImage(image,master=self)
            self.cover_label.configure(image=self.cover_photo,text='',
                                       bg=SURFACE,bd=0,highlightthickness=0)
        except Exception:
            self.cover_label.configure(image='',text='KLN',fg=YELLOW,
                                       bg=SURFACE,font=(self.ui_font,14,'bold'))

    def choose_player_cover(self):
        """Copy validated artwork into the user's own app-data directory."""
        path=filedialog.askopenfilename(parent=self,title='Eigenes Player-Cover auswählen',
               filetypes=[('Bilder','*.png *.jpg *.jpeg *.webp'),('Alle Dateien','*.*')])
        if not path:return
        candidate=Path(path)
        if not candidate.is_file() or candidate.stat().st_size>15*1024*1024:
            messagebox.showerror('Coverbild','Bitte eine Bilddatei bis maximal 15 MB wählen.',parent=self)
            return
        try:
            from PIL import Image
            with Image.open(candidate) as img:
                img.verify()
            target_dir=Path.home()/'.meine_mediathek_design'
            target_dir.mkdir(parents=True,exist_ok=True)
            target=target_dir/'player_cover.png'
            with Image.open(candidate) as img:
                img.convert('RGBA').save(target,format='PNG')
            self.save_setting('player_custom_cover',str(target))
            self._refresh_user_covers()
        except (OSError,ValueError) as exc:
            messagebox.showerror('Coverbild',f'Bild konnte nicht geladen werden:\n{exc}',parent=self)

    def reset_player_cover(self):
        self.save_setting('player_custom_cover','')
        self._refresh_user_covers()

    def _refresh_user_covers(self):
        self._set_cover(self.active_track)
        self._large_cover_path = object()
        self._refresh_large_player(force_cover=True)
        label = getattr(self, 'cover_choice_label', None)
        if label is not None and label.winfo_exists():
            label.configure(text='Eigenes Cover aktiv' if self._user_cover_path() else 'Standard: KLN-Logo')

    CATEGORY_NAMES = {"beats": "Beats", "remixes": "Remixe", "songs": "Songs"}

    def configured_folders(self):
        return {name: self.setting("folder_" + name, "").strip()
                for name in self.CATEGORY_NAMES}

    def manage_music_folders(self):
        """Verknüpfung der Ordner ändern, ohne Musikdateien anzufassen."""
        popup = tk.Toplevel(self)
        popup.title("Musikordner verwalten")
        popup.configure(bg=BG)
        popup.geometry("700x285")
        popup.resizable(False, False)
        popup.transient(self)
        popup.grab_set()
        tk.Label(popup, text="Musikordner verknüpfen", bg=BG, fg=YELLOW,
                 font=(self.ui_font, 13, "bold")).pack(anchor="w", padx=18, pady=(13, 4))
        tk.Label(popup, text="Dateien und Unterordner bleiben unverändert. Neue Titel werden beim Synchronisieren eingelesen.",
                 bg=BG, fg=MUTED, font=(self.ui_font, 9)).pack(anchor="w", padx=18, pady=(0, 12))
        for category, title in self.CATEGORY_NAMES.items():
            row = tk.Frame(popup, bg=BG)
            row.pack(fill="x", padx=18, pady=5)
            tk.Label(row, text=title, width=9, anchor="w", bg=BG, fg=TEXT,
                     font=(self.ui_font, 10, "bold")).pack(side="left")
            path_label = tk.Label(row, text=self.setting("folder_"+category, "") or "Kein Ordner ausgewählt",
                                  bg=SURFACE2, fg=MUTED, anchor="w", width=52,
                                  font=(self.ui_font, 9))
            path_label.pack(side="left", fill="x", expand=True, padx=(6, 8), ipady=7)
            def choose(c=category, lbl=path_label):
                initial = self.setting("folder_"+c, "")
                options = {"title": "Ordner für " + self.CATEGORY_NAMES[c] + " wählen", "parent": popup}
                if initial and Path(initial).is_dir():
                    options["initialdir"] = initial
                path = filedialog.askdirectory(**options)
                if path:
                    # Verhindert eine doppelte Zuordnung desselben Ordners.
                    configured = self.configured_folders()
                    for other, existing in configured.items():
                        if other != c and existing and Path(existing).resolve() == Path(path).resolve():
                            messagebox.showwarning("Ordner bereits verknüpft",
                                "Dieser Ordner ist bereits der Kategorie " + self.CATEGORY_NAMES[other] + " zugeordnet.",
                                parent=popup)
                            return
                    self.save_setting("folder_"+c, path)
                    self.save_setting("last_folder_manage", path)
                    self.save_setting("last_folder_manage_category", c)
                    lbl.config(text=path, fg=TEXT)
            tk.Button(row, text="Wählen …", command=choose, bg=SURFACE2, fg=TEXT,
                      activebackground=HOVER, activeforeground=YELLOW,
                      relief="flat", padx=9, cursor="hand2").pack(side="right")
        tk.Button(popup, text="Fertig", command=popup.destroy, bg=PURPLE, fg=TEXT,
                  activebackground=HOVER, activeforeground=YELLOW, relief="flat",
                  padx=14, pady=5, cursor="hand2").pack(side="right", padx=18, pady=13)

    def sync_on_start(self):
        if self.setting("sync_start","1") == "1" and any(self.configured_folders().values()):
            self.synchronize_library(silent=True)

    def synchronize_library(self, silent=False):
        """Scans configured folders, never moves/copies/deletes files on disk.

        Missing entries are removed only if they belong to currently configured
        folders and are actually absent (not when the drive is disconnected).
        """
        if self.sync_running:
            return
        config = self.configured_folders()
        usable = {}
        missing = []
        for category, path in config.items():
            if not path:
                continue
            root = Path(path).expanduser()
            if root.is_dir():
                usable[category] = root.resolve()
            else:
                missing.append(self.CATEGORY_NAMES[category])
        if not usable:
            if not silent:
                messagebox.showinfo("Mediathek synchronisieren",
                    "Bitte zuerst im Drei-Punkte-Menü unter „Musikordner verwalten“ die Ordner für Beats, Remixe und Songs auswählen.")
            return
        self.sync_running = True
        added = 0
        moved_category = 0
        removed = 0
        seen = set()
        try:
            # Die Datei wird anhand ihres tatsächlichen Pfads eingeordnet.
            # Synchronisierung importiert nur neue Titel und aktualisiert die
            # Kategorie. Vorhandene Analysewerte/Bewertungen bleiben erhalten.
            for category, root in usable.items():
                iterator = root.rglob("*") if self.setting("scan_subfolders","1") == "1" else root.glob("*")
                for file in iterator:
                    if not file.is_file() or file.suffix.lower() not in EXTS:
                        continue
                    try:
                        path = str(file.resolve())
                        seen.add(path)
                        existing = self.db.execute(
                            "SELECT category FROM tracks WHERE path=?", (path,)).fetchone()
                        if existing is None:
                            self.db.execute(UPSERT_SQL, (path, *read_tags(file)))
                            self.db.execute("UPDATE tracks SET category=? WHERE path=?", (category,path))
                            added += 1
                        elif existing[0] != category:
                            self.db.execute("UPDATE tracks SET category=? WHERE path=?", (category,path))
                            moved_category += 1
                    except (OSError, ValueError, RuntimeError):
                        continue
            # Nur verwaiste Datenbankeinträge aus erreichbaren verknüpften
            # Ordnern entfernen. Die Dateien selbst werden niemals gelöscht.
            # Laufwerke/Ordner, die aktuell nicht erreichbar sind, ausnehmen.
            for (stored_path,) in self.db.execute("SELECT path FROM tracks").fetchall():
                old = Path(stored_path)
                monitored = False
                for root in usable.values():
                    try:
                        old.relative_to(root)
                        monitored = True
                        break
                    except ValueError:
                        continue
                if monitored and stored_path not in seen and not old.is_file():
                    self.db.execute("DELETE FROM correction_originals WHERE path=?", (stored_path,))
                    self.db.execute("DELETE FROM tracks WHERE path=?", (stored_path,))
                    removed += 1
            self.db.commit()
            self.refresh()
        except OSError as error:
            if not silent:
                messagebox.showerror("Synchronisierung", str(error))
        finally:
            self.sync_running = False
        if not silent:
            suffix = ("\nNicht erreichbare Ordner: " + ", ".join(missing)) if missing else ""
            messagebox.showinfo("Mediathek synchronisiert",
                f"{added} neue Titel hinzugefügt.\n{moved_category} Kategorien aktualisiert."
                f"\n{removed} nicht mehr vorhandene Einträge entfernt."
                f"\nMusikdateien selbst werden nicht verändert.{suffix}")

    def _reuse_folder(self, kind):
        path = self.setting('last_folder_' + kind, '')
        if not path or not Path(path).is_dir():
            messagebox.showinfo('Ordner-Schnellzugriff',
                                'Es wurde noch kein erreichbarer Ordner gespeichert.')
            return
        if kind == 'add':
            self.add_folder(path)
        elif kind == 'import':
            # Kopieren ist ein eigener Vorgang: vor dem Wiederholen bestätigen.
            if messagebox.askyesno('Ordner erneut importieren',
                       f'Diesen Ordner erneut importieren?\n\n{path}'):
                self.import_folder(path)
        else:
            category=self.setting('last_folder_manage_category','')
            if category not in self.CATEGORY_NAMES:
                self.manage_music_folders()
                return
            self.save_setting('folder_'+category,path)
            messagebox.showinfo('Musikordner erneut verwendet',
                f'Der letzte Ordner wurde der Kategorie {self.CATEGORY_NAMES[category]} zugewiesen:\n\n{path}')

    def add_folder(self, folder=None):
        if folder is None:
            folder = filedialog.askdirectory(title="Musikordner wählen")
        if not folder:
            return
        folder = str(Path(folder).expanduser())
        if not Path(folder).is_dir():
            messagebox.showwarning('Ordner nicht gefunden', folder)
            return
        self.save_setting('last_folder_add', folder)
        files = [p for p in Path(folder).rglob("*") if p.suffix.lower() in EXTS]
        for i, p in enumerate(files, 1):
            self.db.execute(UPSERT_SQL,
                            (str(p), *read_tags(p)))
            self.db.execute("UPDATE tracks SET category=? WHERE path=?", (self.setting("default_category","beats"),str(p)))
            if i % 20 == 0:
                self.status.config(text=f"Lese ein: {i}/{len(files)}")
                self.update_idletasks()
        self.db.commit()
        self.refresh()
        messagebox.showinfo("Fertig", f"{len(files)} Titel eingelesen.")

    def add_files(self):
        """Einzelne Musikdateien auswählen und in die Mediathek eintragen."""
        types = [("Musikdateien", " ".join(f"*{e}" for e in sorted(EXTS))),
                 ("Alle Dateien", "*.*")]
        paths = filedialog.askopenfilenames(title="Musikdateien wählen", filetypes=types)
        if not paths:
            return
        count = 0
        for p in map(Path, paths):
            if p.suffix.lower() in EXTS:
                self.db.execute(UPSERT_SQL,
                                (str(p), *read_tags(p)))
                self.db.execute("UPDATE tracks SET category=? WHERE path=?", (self.setting("default_category","beats"),str(p)))
                count += 1
        self.db.commit()
        self.refresh()
        if count < len(paths):
            messagebox.showinfo("Hinweis", f"{len(paths) - count} Datei(en) hatten ein "
                                           "nicht unterstütztes Format und wurden übersprungen.")

    def import_folder(self, folder=None):
        """Kopiert einen Ordner in die Mediathek (LIB_DIR) und trägt ihn ein."""
        if folder is None:
            folder = filedialog.askdirectory(title="Musikordner zum Importieren wählen")
        if not folder:
            return
        folder = str(Path(folder).expanduser())
        if not Path(folder).is_dir():
            messagebox.showwarning('Ordner nicht gefunden', folder)
            return
        self.save_setting('last_folder_import', folder)
        src_root = Path(folder)
        files = [p for p in src_root.rglob("*") if p.suffix.lower() in EXTS]
        dest_root = LIB_DIR / src_root.name
        failed = 0
        for i, p in enumerate(files, 1):
            dest = dest_root / p.relative_to(src_root)
            try:
                dest.parent.mkdir(parents=True, exist_ok=True)
                if not dest.exists():
                    shutil.copy2(p, dest)
                self.db.execute(UPSERT_SQL,
                                (str(dest), *read_tags(dest)))
            except OSError:
                failed += 1
            if i % 10 == 0:
                self.status.config(text=f"Importiere: {i}/{len(files)}")
                self.update_idletasks()
        self.db.commit()
        self.refresh()
        msg = (f"{len(files) - failed} Titel wurden nach\n{dest_root}\nkopiert.\n\n"
               "Die Originale kannst du jetzt löschen, die App nutzt nur noch die Kopien.")
        if failed:
            msg += f"\n\n{failed} Datei(en) konnten nicht kopiert werden."
        messagebox.showinfo("Import fertig", msg)

    def toggle_filter_popup(self):
        """Short, two-row/three-row chips instead of a tall scrollable list."""
        opened = bool(self.filter_popup and self.filter_popup.winfo_exists())
        self.close_popups()
        if opened:
            return
        popup = tk.Frame(self, bg=BG, highlightbackground=PURPLE, highlightthickness=1)
        self.filter_popup = popup
        tk.Label(popup, text="Spalten anzeigen", bg=BG, fg=YELLOW,
                 font=(self.ui_font, 11, "bold")).pack(anchor="w", padx=12, pady=(9, 4))
        group = tk.Frame(popup, bg=BG)
        group.pack(fill="both", expand=True, padx=9, pady=(2, 9))
        # Three columns: four rows for ten filter choices.
        chip_names = list(COLUMNS.items())
        chip_width = 126
        for i, (key, title) in enumerate(chip_names):
            r, c = divmod(i, 3)
            active = key in self.visible_columns
            background = "#4E2982" if active else SURFACE2
            foreground = YELLOW if active else TEXT
            chip = Pill(group, ("✓  " if active else "+  ") + title,
                        lambda k=key: self.toggle_column_chip(k),
                        w=chip_width, h=30, fill=background, fg=foreground,
                        bg=BG, font=(self.ui_font, 9, "bold"))
            chip.grid(row=r, column=c, padx=3, pady=4)
            # keep a reference so selection can be recoloured in-place
            chip.column_key = key
        tk.Label(popup, text="Sortieren", bg=BG, fg=YELLOW,
                 font=(self.ui_font, 10, "bold")).pack(anchor="w", padx=12, pady=(0, 3))
        sort_row = tk.Frame(popup, bg=BG)
        sort_row.pack(anchor="w", padx=12, pady=(0, 10))
        newest = self.sort_col == "added"
        sort_btn = Pill(sort_row, "Zuletzt hinzugefügt ↓", self.toggle_added_sort,
                        w=192, h=30, fill=VIOLET if newest else SURFACE2,
                        fg=YELLOW if newest else TEXT, bg=BG,
                        font=(self.ui_font, 9, "bold"))
        sort_btn.pack(side="left")
        self._library_newest_chip = sort_btn
        self.update_idletasks()
        width = min(414, self.winfo_width()-24)
        height = 269
        x = max(8, min(self.filter_button.winfo_rootx()-self.winfo_rootx(),
                       self.winfo_width()-width-8))
        y = self.filter_button.winfo_rooty()-self.winfo_rooty()+self.filter_button.winfo_height()+5
        if y + height > self.winfo_height()-8:
            y = max(8, self.winfo_height()-height-8)
        popup.place(x=x, y=y, width=width, height=height)
        popup.lift()

    def toggle_added_sort(self):
        """Neue Importe vor alten, unabhaengig von Datei-MTime/Abspielzeit."""
        newest = self.sort_col != "added"
        self.sort_col = "added" if newest else "title"
        self.sort_desc = newest
        chip = getattr(self, "_library_newest_chip", None)
        if chip is not None and chip.winfo_exists():
            chip.fill = VIOLET if newest else SURFACE2
            chip.fg = YELLOW if newest else TEXT
            chip._draw(chip.fill)
        self.refresh()

    def toggle_column_chip(self, column):
        """Spalte verlaesslich umschalten, speichern und Tabellenlayout aktualisieren.

        Fix: Der Sortier-Pill hat kein column_key und wurde vorher faelschlich
        mitbearbeitet. Der dadurch ausgeloeste AttributeError verhinderte die
        Aktualisierung des Treeview nach jeder Auswahl.
        """
        if column not in COLUMNS:
            return
        visible = list(self.visible_columns)
        if column in visible:
            if len(visible) == 1:
                return
            visible.remove(column)
        else:
            visible.append(column)
        visible.sort(key=lambda name: list(COLUMNS).index(name))
        self.visible_columns = visible
        width=max(50,self.tree.winfo_width()-5)
        if len(visible)>1 and 'title' in visible:
            weights=[TITLE_SHARE if name=='title' else (1-TITLE_SHARE)/(len(visible)-1)
                     for name in visible]
        else:
            weights=[1/len(visible)]*len(visible)
        widths=[max(36,int(width*w)) for w in weights]
        if sum(widths)<width:
            widths[-1]+=width-sum(widths)
        # Configure hidden/new columns first, then switch the display tuple.
        # No intermediate "all columns at 150 px" layout is exposed to Tk.
        for name,px in zip(visible,widths):
            self.tree.column(name,width=px,minwidth=24,stretch=False)
        self.tree['displaycolumns']=tuple(visible)
        self._schedule_library_header()
        self.save_setting('columns',','.join(visible))

        popup = self.filter_popup
        if popup is not None and popup.winfo_exists():
            for group in popup.winfo_children():
                if isinstance(group, tk.Frame):
                    for chip in group.winfo_children():
                        key = getattr(chip, "column_key", None)
                        if key != column or not isinstance(chip,Pill):
                            continue
                        enabled = key in visible
                        chip.fill = "#4E2982" if enabled else SURFACE2
                        chip.fg = YELLOW if enabled else TEXT
                        chip.text = ("✓  " if enabled else "+  ") + COLUMNS[key]
                        chip._draw(chip.fill)
        # Column geometry can be applied immediately but the overlay must be
        # hidden until the native Treeview has committed its new column boxes.
        self.rating_overlay.place_forget()
        self._request_rating_sync()
        self.schedule_table_layout()

    def _table_draw_bottom(self):
        """Never reveal an incomplete bottom row, regardless of zoom or scrolling."""
        tree=self.tree
        bottom=max(0,tree.winfo_height())
        if bottom<2:return bottom
        try:
            rh=int(float(ttk.Style(self).lookup('Library.Treeview','rowheight') or 36))
        except (ValueError,tk.TclError):
            rh=36
        rh=max(1,rh)
        return max(0,(bottom//rh)*rh)

    def _visible_tree_rows(self, extra=3):
        """Only visible Treeview rows should be repainted during scrolling."""
        tree = self.tree
        all_items = tree.get_children()
        count = len(all_items)
        if not count:
            return []
        try:
            start, end = tree.yview()
            lower = max(0, int(start * count) - extra)
            upper = min(count, int(end * count) + extra + 2)
        except (ValueError, tk.TclError):
            lower, upper = 0, count
        return list(enumerate(all_items[lower:upper], start=lower))

    def _click_playing_icon(self, event):
        """Die kleine Overlay-Grafik darf die Zeilenbedienung nicht blockieren."""
        if self.active_track and self.tree.exists(self.active_track):
            self.tree.focus(self.active_track)
            self.tree.focus_set()
        return "break"

    def _speaker_photo(self):
        """Antialias a transparent loudspeaker, centered in the actual row bbox."""
        from PIL import Image, ImageDraw, ImageTk
        size=max(15,min(22,round(self.zoom_level*1.45)))
        if size in self._speaker_photos:
            return self._speaker_photos[size]
        z=4
        image=Image.new('RGBA',(size*z,size*z),(0,0,0,0))
        draw=ImageDraw.Draw(image)
        k=size/21*z
        pts=lambda p:[(round(x*k),round(y*k)) for x,y in p]
        body=pts([(2,8),(6,8),(10,4),(10,17),(6,13),(2,13)])
        draw.polygon(body, fill=(255,229,89,255))
        draw.arc(tuple(round(v*k) for v in (8,5,16.5,16)), start=-69,end=69,
                 fill=(255,229,89,255),width=max(2,round(1.7*k)))
        draw.arc(tuple(round(v*k) for v in (8,2,21,19)),start=-67,end=67,
                 fill=(255,229,89,255),width=max(2,round(1.4*k)))
        photo=ImageTk.PhotoImage(image.resize((size,size),Image.Resampling.LANCZOS),master=self.tree)
        self._speaker_photos[size]=photo
        return photo

    def redraw_playing_icon(self):
        """Center speaker in the playing track's title cell, not the font baseline."""
        icon=self.playing_icon
        try:
            if (not self.playing or not self.active_track or
                not self.tree.exists(self.active_track) or
                'title' not in tuple(self.tree['displaycolumns'])):
                icon.place_forget()
                return
            box=self.tree.bbox(self.active_track,'title')
            if not box or box[1]+box[3]>self._table_draw_bottom():
                icon.place_forget()
                return
            photo=self._speaker_photo()
            icon.configure(image=photo, bg=ROW_PLAYING)
            icon.place(x=box[0]+6, y=box[1]+(box[3]-photo.height())//2,
                       width=photo.width(),height=photo.height())
            icon.lift()
        except (tk.TclError,AttributeError):
            try:icon.place_forget()
            except tk.TclError:pass

    def update_grid_lines(self, schedule_next=True):
        """Place persistent separators from the real Treeview geometry.

        schedule_next=False allows one immediate post-resize synchronization
        without accidentally starting a second repeating update loop.
        """
        try:
            tree = self.tree
            if not tree.winfo_exists():
                return
            if self.active_page != 'library' or self._resizing_window:
                if schedule_next:
                    self.after(240,self.update_grid_lines)
                return
            width, height = tree.winfo_width(), tree.winfo_height()
            visible = tuple(tree["displaycolumns"])
            column_widths = tuple(int(tree.column(key, "width")) for key in visible[:-1])
            signature = (width, height, visible, column_widths)
            if signature != getattr(self, '_grid_signature', None):
                self._grid_signature = signature
                while len(self.grid_lines) < len(column_widths):
                    separator = tk.Frame(tree, bg="#52306D", width=1)
                    separator.bind("<ButtonRelease-3>", self.rating_context_menu)
                    self.grid_lines.append(separator)
                x = 0
                for line, column_width in zip(self.grid_lines, column_widths):
                    x += column_width
                    if 0 < x < width:
                        line.place(x=x-1, y=0, width=1, height=height)
                        line.lift()
                    else:
                        line.place_forget()
                for line in self.grid_lines[len(column_widths):]:
                    line.place_forget()
            selected = tree.selection()
            if selected:
                rect = tree.bbox(selected[0])
                if rect and selected[0] != self.active_track:
                    self.selection_marker.configure(bg="#B081E8")
                    self.selection_marker.place(x=0, y=rect[1], width=3, height=rect[3])
                    self.selection_marker.lift()
                else:
                    self.selection_marker.place_forget()
            else:
                self.selection_marker.place_forget()
            playing = self.active_track if self.playing else None
            if playing and tree.exists(playing):
                played_box = tree.bbox(playing)
                if played_box:
                    self.playing_marker.place(x=0, y=played_box[1], width=3, height=played_box[3])
                    self.playing_marker.lift()
                else:
                    self.playing_marker.place_forget()
            else:
                self.playing_marker.place_forget()
            self.redraw_playing_icon()
            self._mask_partial_row()
        except tk.TclError:
            return
        if schedule_next:
            self.after(160,self.update_grid_lines)

    def schedule_table_layout(self, event=None):
        """Synchronize column widths even while the user is dragging a border.

        Performance2 used a continuously restarted 245-ms debounce; with each
        Treeview <Configure> the deadline moved, so columns could lag until
        after the user stopped dragging. A single pending 42-ms callback is
        instead throttled while dragging (never restarted by further events).
        """
        if self._resizing_window:
            if self.active_page == 'library' and self._layout_job is None:
                self._layout_job = self.after(42, self._apply_table_layout)
            return
        if self._layout_job is not None:
            try: self.after_cancel(self._layout_job)
            except tk.TclError: pass
        self._layout_job = self.after(12, self._apply_table_layout)

    def _apply_table_layout(self):
        self._layout_job = None
        if self.active_page != 'library':
            return
        self.fit_columns()
        self._schedule_library_header()
        # Rating/Mood drawing is deferred until Tk has committed its native
        # cell positions, but is not continually postponed by size events.
        if not self._resizing_window:
            self._request_rating_sync(settle=False)

    def _paint_neon_edge(self,canvas,kind):
        """One 3px PhotoImage instead of hundreds of Canvas rectangles each resize."""
        from PIL import ImageTk
        width=canvas.winfo_width()
        if width<2 or getattr(canvas,'_painted_width',None)==width:
            return
        canvas._painted_width=width
        canvas._edge_photo=ImageTk.PhotoImage(_neon_edge_image(width,kind),master=canvas)
        canvas.delete('all')
        canvas.create_image(0,0,anchor='nw',image=canvas._edge_photo)

    def resize_toolbar(self, event=None):
        if event is not None and event.widget is not self:
            return
        if self._resize_idle_job is not None:
            try: self.after_cancel(self._resize_idle_job)
            except tk.TclError: pass
        self._resizing_window = True
        # Long enough not to finish between ordinary drag events (~8-13/s),
        # but shorter than the former 210 ms post-drag wait.
        self._resize_idle_job = self.after(145, self._window_resize_settled)
        self._position_search_box()

    def _position_search_box(self, event=None):
        if not self.search_open:
            return
        box = self.search_box
        toolbar = self.toolbar_content
        right = self.search_button.winfo_x() - 8
        if not self.search_button.winfo_ismapped():
            right = toolbar.winfo_width() - self.search_button.winfo_reqwidth() - 8
        logo_end = self.kln_logo_label.winfo_x() + self.kln_logo_label.winfo_width() + 12
        width = min(310, right - logo_end - self.status.winfo_reqwidth() - 10)
        if width < 38:
            box.place_forget()
            self.status.pack_configure(padx=(0, 11))
            self._search_count_padding = None
            return
        padding = (0, width + 16)
        if getattr(self, '_search_count_padding', None) != padding:
            self._search_count_padding = padding
            self.status.pack_configure(padx=padding)
        if box.w != width:
            box.w = width
            box.configure(width=width)
            box.itemconfigure(box._entry_window, width=max(1, width - 30))
            box._draw(self.focus_get() is box.entry)
        box.place(x=right, y=max(0, (toolbar.winfo_height() - box.h) // 2), anchor='ne')
        box.tk.call('raise', box._w)
        box._schedule_matching_backdrop()

    def _window_resize_settled(self):
        self._resize_idle_job = None
        self._resizing_window = False
        if self.active_page == "library":
            # The latest Treeview size must win over every pending intermediate
            # drag update. Apply column widths NOW, rather than another timer.
            if self._layout_job is not None:
                try: self.after_cancel(self._layout_job)
                except tk.TclError: pass
                self._layout_job = None
            self.fit_columns()
            if self._header_render_job is not None:
                try: self.after_cancel(self._header_render_job)
                except tk.TclError: pass
                self._header_render_job = None
            # after_idle sees the final native Treeview cell boxes. Only one
            # finish pass is queued, even after closely spaced drag bursts.
            if self._library_resize_sync_job is not None:
                try: self.after_cancel(self._library_resize_sync_job)
                except tk.TclError: pass
            self._library_resize_sync_job = self.after_idle(self._complete_library_resize)
        elif self.active_page == "player":
            wave = getattr(self, 'large_progress', None)
            if wave is not None and wave.winfo_exists():
                wave.finish_resize()
        # Reposition toolbar overlays using their current geometry.
        for widget in (getattr(self, 'search_button', None),
                       getattr(self, 'status', None)):
            if widget is not None and widget.winfo_exists():
                widget._schedule_overlay()

    def _complete_library_resize(self):
        """One geometry-consistent finish pass, without new wait timers."""
        self._library_resize_sync_job = None
        if self._resizing_window or self.active_page != 'library':
            return
        try:
            if not self.tree.winfo_exists():
                return
            self.fit_columns()
            self._draw_library_header()
            # Do not restart update_grid_lines' existing 160-ms poll loop.
            self.update_grid_lines(schedule_next=False)
            self._request_rating_sync(settle=False)
        except tk.TclError:
            return

    def _schedule_library_header(self, event=None):
        if self._resizing_window:
            # Rate limit: no timer cancellation storm, redraw latest width.
            if self._header_render_job is None:
                self._header_render_job=self.after(95, self._delayed_library_header)
            return
        if self._header_render_job is not None:
            try:self.after_cancel(self._header_render_job)
            except tk.TclError:pass
        self._header_render_job=self.after(22, self._delayed_library_header)

    def _delayed_library_header(self):
        self._header_render_job=None
        if self.active_page == "library":
            self._draw_library_header()

    def change_zoom(self, direction):
        """Ändert Schriftgröße und Zeilenhöhe ohne Daten neu einzulesen."""
        next_level = max(8, min(20, self.zoom_level + direction))
        if next_level == self.zoom_level and direction != 0:
            return "break"
        self.zoom_level = next_level
        ttk.Style(self).configure(
            "Treeview",
            font=(self.ui_font, self.zoom_level),
            rowheight=(max(24, int(self.zoom_level * 3.3) - 7)
                       if self.setting("row_density", "normal") == "compact"
                       else max(28, int(self.zoom_level * 3.3))),
        )
        ttk.Style(self).configure(
            "Treeview.Heading",
            font=(self.ui_font, max(11, round(self.zoom_level * 1.2)), "bold"),
        )
        ttk.Style(self).configure(
            "Library.Treeview", font=(self.ui_font, self.zoom_level),
            rowheight=(max(24, int(self.zoom_level*3.3)-7)
                       if self.setting("row_density","normal")=="compact"
                       else max(28,int(self.zoom_level*3.3))),
        )
        self.save_setting("zoom", self.zoom_level)
        if hasattr(self, "tree"):
            self.schedule_table_layout()
        if hasattr(self, "zoom_label") and self.zoom_label.winfo_exists():
            self.zoom_label.config(text=f"{round(self.zoom_level / 11 * 100)} %")
        return "break"

    def zoom_mousewheel(self, event):
        return self.change_zoom(1 if event.delta > 0 else -1)

    def fit_columns(self, event=None):
        """Pixel-exact widths assigned once, with remainder on the last column.

        Keeps separators aligned and avoids cumulative rounding jumps.
        """
        if not hasattr(self, "tree") or not self.tree.winfo_exists():
            return
        visible = list(self.visible_columns)
        if not visible:
            return
        total = max(50, self.tree.winfo_width()-5)
        weights = [TITLE_SHARE if key == "title" and len(visible) > 1 else 1.0
                   for key in visible]
        if "title" in visible and len(visible) > 1:
            weights = [TITLE_SHARE if key == "title" else (1-TITLE_SHARE)/(len(visible)-1)
                       for key in visible]
        widths = [int(total*w/sum(weights)) for w in weights]
        widths[-1] += total-sum(widths)
        # Very narrow windows may need horizontal scroll; don't move separators
        # independently of the Treeview's own column widths.
        widths = [max(36, x) for x in widths]
        for key, width in zip(visible, widths):
            if int(self.tree.column(key, "width")) != width:
                self.tree.column(key, width=width, stretch=False, minwidth=24)

    @staticmethod
    @_ui_lru_cache(maxsize=1)
    def _header_reference_texture():
        """Supersampled header with genuine clipped corner/border antialiasing."""
        from PIL import Image,ImageDraw,ImageFilter
        w,h,z=1560,49,4
        W,H=w*z,h*z
        image=Image.new('RGBA',(W,H),(0,0,0,0))
        pen=ImageDraw.Draw(image)
        stops=((0.0,(42,23,79)),(.30,(80,31,128)),
               (.66,(99,30,155)),(1.0,(48,22,91)))
        for x in range(W):
            t=x/(W-1)
            for j in range(len(stops)-1):
                a,ca=stops[j];b,cb=stops[j+1]
                if t<=b:
                    rgb=_mix_rgb(ca,cb,(t-a)/(b-a))
                    break
            pen.line((x,0,x,H),fill=rgb+(255,))
        mask=Image.new('L',(W,H),0)
        md=ImageDraw.Draw(mask)
        # Tall rounded rectangle extends below the crop; only top corners round.
        md.rounded_rectangle((0,0,W-1,H+19*z),radius=14*z,fill=255)
        image.putalpha(mask)
        line=Image.new('RGBA',(W,H),(0,0,0,0))
        d=ImageDraw.Draw(line)
        d.arc((2*z,2*z,27*z,27*z),180,270,fill=(240,119,255,240),width=2*z)
        d.line((14*z,2*z,W-14*z,2*z),fill=(240,119,255,240),width=2*z)
        d.arc((W-27*z,2*z,W-2*z,27*z),270,360,fill=(240,119,255,240),width=2*z)
        glow=line.filter(ImageFilter.GaussianBlur(7*z))
        mid=line.filter(ImageFilter.GaussianBlur(2*z))
        image=Image.alpha_composite(image,glow)
        image=Image.alpha_composite(image,mid)
        image=Image.alpha_composite(image,line)
        image.putalpha(mask)
        # Flatten against the exact dark-purple canvas to eliminate 1px halos.
        back=Image.new('RGBA',(W,H),'#130C2C')
        back=Image.alpha_composite(back,image)
        return back.convert('RGB').resize((w,h),Image.Resampling.LANCZOS)

    def _draw_library_header(self,event=None):
        """Antialiased cached header; redraw only labels when columns change."""
        if not hasattr(self,'library_header') or not hasattr(self,'tree'):
            return
        canvas=self.library_header
        if not canvas.winfo_exists():return
        width=min(3500,canvas.winfo_width())
        height=49
        if width<40:return
        visible = tuple(self.tree['displaycolumns'])
        signature = (width, self.ui_font, self.zoom_level, visible,
                     tuple(self.tree.column(key, 'width') for key in visible),
                     self.sort_col, self.sort_desc, self.header_default_mode,
                     tuple(self.header_column_modes.items()))
        if signature == getattr(self, '_last_header_signature', None):
            return
        self._last_header_signature = signature
        from PIL import ImageTk, Image
        if getattr(self,'_header_texture_width',None)!=width:
            master=self._header_reference_texture()
            # Bilinear scaling is smooth and much faster than redrawing all pixels.
            bg=master.resize((width,height),Image.Resampling.BILINEAR)
            self._library_header_image=ImageTk.PhotoImage(bg,master=canvas)
            self._header_texture_width=width
        canvas.delete('all')
        canvas.create_image(0,0,anchor='nw',image=self._library_header_image)
        self._header_hitboxes=[]
        offset=0
        from tkinter import font as tkfont
        fsize=max(10,min(12,round(self.zoom_level*1.03)))
        label_font=tkfont.Font(family=self.ui_font,size=fsize,weight='bold')
        visible=list(self.tree['displaycolumns'])
        for idx,key in enumerate(visible):
            span=int(self.tree.column(key,'width'))
            if span<=0:continue
            left=offset+11
            self._header_hitboxes.append((offset,offset+span,key))
            title='BPM' if key=='bpm' else COLUMNS[key]
            mode=self.header_column_modes.get(key,'default')
            if mode not in ('text','icon','both'):
                mode=self.header_default_mode
            symbol=self._library_icon_photo(key) if (mode != 'text' and
                (key != 'rating' or mode == 'icon')) else None
            has_icon=symbol is not None and span>=36
            show_text=(mode!='icon' or not has_icon)
            text_x=left+(26 if has_icon and show_text else 0)
            if has_icon:
                canvas.create_image(left+12,25,image=symbol)
            selected=key==self.sort_col
            text_color='#FFF396' if selected else '#F5F0FF'
            # Reserve sort-arrow space only on the actually sorted column.
            # Otherwise long headings such as Dateiformat fit without ellipsis.
            available=span-(text_x-offset)-4-(19 if selected else 0)
            title_display=title
            if (show_text and available>20) or (not show_text):
                if show_text:
                    while label_font.measure(title_display)>available and len(title_display)>1:
                        title_display=title_display[:-1]
                    if title_display!=title:title_display=title_display[:-1]+'…'
                    canvas.create_text(text_x,25,text=title_display,
                                       fill=text_color,font=label_font,anchor='w')
                if selected:
                    arrow_x=(text_x+label_font.measure(title_display)+10 if show_text
                             else left+29)
                    if arrow_x<offset+span-7:
                        canvas.create_text(arrow_x,25,
                           text='▼' if self.sort_desc else '▲',anchor='w',
                           fill='#FFF396',font=(self.ui_font,9,'bold'))
            offset+=span
            if idx<len(visible)-1 and offset<width:
                canvas.create_line(offset,11,offset,38,fill='#684084',width=1)
        canvas.create_line(0,height-1,width,height-1,fill='#593377',width=1)

    def _library_icon_photo(self,key):
        """Supersampled 24px vector artwork; smooth on Windows at 100% scaling."""
        cache=getattr(self,'_library_icon_cache',None)
        if cache is None:
            cache={};self._library_icon_cache=cache
        if key in cache:return cache[key]
        from PIL import Image,ImageDraw,ImageTk
        z=4
        image=Image.new('RGBA',(24*z,24*z),(0,0,0,0))
        pen=ImageDraw.Draw(image)
        ink=(237,224,255,255)
        thickness=2.0*z
        def segment(points,w=thickness):
            xy=[(round(x*z),round(y*z)) for x,y in points]
            pen.line(xy,fill=ink,width=round(w),joint='curve')
            r=w/2
            for x,y in (xy[0],xy[-1]):
                pen.ellipse((x-r,y-r,x+r,y+r),fill=ink)
        def rect(box,r=1.8,stroke=thickness):
            pen.rounded_rectangle(tuple(int(k*z) for k in box),radius=round(r*z),
                                  outline=ink,width=round(stroke))
        if key=='title':
            # A single, elegant music note instead of two blocky joined notes.
            pen.ellipse((3*z,15*z,12*z,20*z),fill=ink)
            segment([(11,17),(11,4),(20,2.5)],2.2*z)
            segment([(12,6.5),(20,4.7)],1.6*z)
        elif key=='year':
            rect((3,5,21,20),2)
            segment([(3,10),(21,10)],1.6*z)
            segment([(8,3),(8,7)],1.7*z)
            segment([(16,3),(16,7)],1.7*z)
            for xx in (8,13,18):
                for yy in (14,17):
                    pen.ellipse(((xx-0.65)*z,(yy-0.65)*z,
                                 (xx+0.65)*z,(yy+0.65)*z),fill=ink)
        elif key=='length':
            pen.ellipse((3*z,3*z,21*z,21*z),outline=ink,width=2*z)
            segment([(12,7),(12,12),(15.8,15)],1.8*z)
        elif key=='bpm':
            segment([(1.5,12),(6,12),(8.3,6),(11.7,18),
                     (14,9),(16.2,12),(22,12)],1.8*z)
        elif key=='tonart':
            rect((2,4,22,20),1.4,1.3*z)
            for xx in (8.7,15.5):segment([(xx,5),(xx,19)],1*z)
            pen.rounded_rectangle((7*z,4*z,11*z,12*z),radius=z//2,fill=ink)
            pen.rounded_rectangle((14*z,4*z,18*z,12*z),radius=z//2,fill=ink)
        elif key=='genre':
            # Music tag, no jagged polygon corners.
            poly=[(3,11),(11,3),(20,3),(21,12),(13,21)]
            pen.line([(int(x*z),int(y*z)) for x,y in poly+[poly[0]]],
                     fill=ink,width=2*z,joint='curve')
            pen.ellipse((14*z,6*z,17*z,9*z),fill=ink)
        elif key=='format':
            rect((5,3,18,21),1.4,1.5*z)
            segment([(10,9),(15,9)],1.5*z)
            segment([(10,14),(15,14)],1.5*z)
        elif key=='camelot':
            pen.ellipse((4*z,4*z,20*z,20*z),outline=ink,width=2*z)
            segment([(12,4),(12,20)],1.5*z)
        elif key=='rating':
            # Minimal rating glyph only when the user specifically selects icon mode.
            pts=[]
            for n in range(10):
                a=-math.pi/2+n*math.pi/5
                r=9 if n%2==0 else 4
                pts.append(((12+r*math.cos(a))*z,(12+r*math.sin(a))*z))
            pen.polygon(pts,outline=ink,width=2*z)
        elif key=='mood':
            pen.ellipse((3*z,3*z,21*z,21*z),outline=ink,width=2*z)
            pen.ellipse((8*z,9*z,9.5*z,10.5*z),fill=ink)
            pen.ellipse((14*z,9*z,15.5*z,10.5*z),fill=ink)
            pen.arc((7*z,9*z,17*z,17*z),start=10,end=170,fill=ink,width=2*z)
        else:
            return None
        photo=ImageTk.PhotoImage(image.resize((24,24),Image.Resampling.LANCZOS),master=self.library_header)
        cache[key]=photo
        return photo


    def _library_header_click(self,event):
        for left,right,key in getattr(self,"_header_hitboxes",[]):
            if left<=event.x<right:
                self.sort_by(key)
                return "break"

    def _library_header_hover(self,event):
        hit=any(a<=event.x<b for a,b,_ in getattr(self,"_header_hitboxes",[]))
        self.library_header.configure(cursor="hand2" if hit else "arrow")

    def update_headings(self):
        """Pfeil in der Überschrift zeigt Sortierspalte und Richtung (▲ aufsteigend, ▼ absteigend)."""
        signature = (self.sort_col, self.sort_desc)
        if signature != getattr(self, '_native_heading_sort', None):
            arrow = "  ▼" if self.sort_desc else "  ▲"
            for key, name in COLUMNS.items():
                self.tree.heading(key, text=name + (arrow if key == self.sort_col else ""))
            self._native_heading_sort = signature
        self._draw_library_header()

    def _display_bpm(self, value):
        if not value:
            return ""
        return f"{float(value):.1f}".replace(".",",") if self.bpm_decimals else fmt_bpm(value)

    def refresh(self):
        q = f"%{self.search_box.text()}%"
        query = ("SELECT path,title,year,length,bpm,tonart,genre,rating,mood,bpm_uncertain,key_uncertain FROM tracks "
                 "WHERE title LIKE ? AND COALESCE(category,'') != 'flp'")
        args = [q]
        if self.category_filter != "all":
            query += " AND COALESCE(NULLIF(category,''),'beats')=?"
            args.append(self.category_filter)
        if self.favorites_only:
            query += " AND rating>=4"
        rows = self.db.execute(query, args).fetchall()
        diagnostics = {path:(bc,kc) for path,_,_,_,_,_,_,_,_,bc,kc in rows}
        rows = [(path, title, year, length, bpm, tonart, genre or "",
                 camelot_code(tonart), Path(path).suffix.lstrip(".").upper(), rating or 0, mood or "")
                for path, title, year, length, bpm, tonart, genre, rating, mood, bc, kc in rows]
        if self.sort_col == "added":
            # Bei gleichem Zeitstempel entscheidet die Einfuegefolge.
            stamps = {p: ((when or ""), seq) for p, when, seq in self.db.execute(
                "SELECT path,added_at,id FROM track_added")}
            rows.sort(key=lambda r: stamps.get(r[0], ("", 0)), reverse=True)
        else:
            rows = sort_rows(rows, self.sort_col, self.sort_desc)
        self.update_headings()
        self.uncertainty_values = diagnostics
        previous_selection = set(self.tree.selection())
        self.tree.delete(*self.tree.get_children())
        self.rating_values = {r[0]: max(0, min(5, int(r[9] or 0))) for r in rows}
        self.tree.tag_configure("even", background="#110A28", foreground="#F3EDFF")
        self.tree.tag_configure("odd", background="#23133E", foreground="#F3EDFF")
        self.tree.tag_configure("hover", background="#3B2164", foreground="#FFFFFF")
        self.tree.tag_configure("playing",background=ROW_PLAYING,foreground="#FFF396")
        self.hovered_row = None
        self._stats_dirty = True
        for i, (path, title, year, length, bpm, tonart, genre, camelot, fmt, rating, mood) in enumerate(rows):
            is_flp = fmt == "FLP"
            is_playing = self.active_track == path and self.playing
            row_tags = ("playing",) if is_playing else (("odd" if i % 2 else "even"),)
            self.tree.insert("", "end", iid=path, tags=row_tags,
                             values=((PLAYING_TITLE_INDENT + title) if is_playing else title, year, ("–" if is_flp else fmt_time(length)),
                                     ((self._display_bpm(bpm) + (" ?" if self.show_uncertainty and diagnostics[path][0] else ""))
                                      if bpm else ("Nicht vorhanden" if is_flp else ("?" if self.show_uncertainty else ""))),
                                     ((tonart + (" ?" if self.show_uncertainty and diagnostics[path][1] and not is_flp else ""))
                                      if tonart else ("Nicht vorhanden" if is_flp else ("?" if self.show_uncertainty else ""))),
                                     (genre or ("" if is_flp else ("?" if self.show_uncertainty else ""))), camelot, fmt,
                                     "", (" · ".join(str(mood).split(" · ")[:self.max_moods]) or ("" if is_flp else ("?" if self.show_uncertainty else "")))))
        keep_selection = [path for path in previous_selection if self.tree.exists(path)
                          and not (self.playing and path == self.active_track)]
        if keep_selection:
            self.tree.selection_set(keep_selection)
        self._library_visible_count = len(rows)
        if self.active_page == "library":
            self.status.config(text=f"{len(rows)} Titel" + (" · Favoriten" if self.favorites_only else ""))
        self._last_highlight_track = self.active_track if self.playing else None
        # The existing canvas still contains stars from the PREVIOUS row order.
        # Hide it synchronously, then redraw after Tk commits new row positions.
        if getattr(self, "rating_overlay", None) is not None:
            self.rating_overlay.place_forget()
            if self.mood_overlay is not None:
                self.mood_overlay.place_forget()
            self._request_rating_sync(settle=False)

    def sort_by(self, col):
        self.sort_desc = (not self.sort_desc) if col == self.sort_col else False
        self.sort_col = col
        self.refresh()

    def on_tree_double_click(self, event):
        row = self.tree.identify_row(event.y)
        if row and Path(row).suffix.lower() == ".flp":
            self.open_flp_project(row)
            return "break"
        col_id = self.tree.identify_column(event.x)
        visible = list(self.tree["displaycolumns"])
        try:
            column = visible[int(col_id[1:]) - 1]
        except (ValueError, IndexError):
            column = None
        if self.edit_mode and row and column:
            self.start_cell_edit(row, column)
            return "break"
        if row and column != "rating":
            self._close_song_menu()
            self.tree.selection_set(row)
            self.tree.focus(row)
            self.tree.focus_set()
            self.play_selected()
            return "break"

    def rating_click(self, event):
        """Bewertungszellen werden zentral gezeichnet; kein Overlay pro Song."""
        return None

    @staticmethod
    def _star_points(cx, cy, outer, inner):
        coords = []
        for i in range(10):
            angle = -math.pi / 2 + i * math.pi / 5
            r = outer if i % 2 == 0 else inner
            coords.extend((cx + math.cos(angle) * r, cy + math.sin(angle) * r))
        return coords

    def _star_strip(self, rating, star_gap, background):
        """Antialiasing durch 4x-Supersampling, danach Lanczos-Verkleinerung.
        Bei fehlendem Pillow werden native Canvas-Polygone verwendet.
        """
        key = (rating, star_gap, background)
        if key in self.rating_icons:
            return self.rating_icons[key]
        try:
            from PIL import Image, ImageDraw, ImageTk
            scale = 4
            width, height = star_gap * 5 + 6, max(24, int(star_gap * 1.15))
            image = Image.new("RGBA", (width * scale, height * scale), background)
            pen = ImageDraw.Draw(image)
            for n in range(5):
                cx = (3 + star_gap * (n + .5)) * scale
                cy = (height / 2) * scale
                outer = min(star_gap * .40, (height - 3) * .43) * scale
                points = self._star_points(cx, cy, outer, outer * .49)
                xy = [(round(points[i]), round(points[i+1])) for i in range(0,len(points),2)]
                pen.polygon(xy, fill=RATING_GOLD if n < rating else background)
                pen.line(xy + [xy[0]], fill=RATING_GOLD, width=max(3, round(scale * 1.15)), joint="curve")
            image = image.resize((width, height), Image.Resampling.LANCZOS)
            photo = ImageTk.PhotoImage(image, master=self.tree)
            self.rating_icons[key] = photo
            return photo
        except ImportError:
            return None

    def rating_overlay_wheel(self, event):
        if not (event.state & 0x4):
            self.tree.yview_scroll(-1 if event.delta > 0 else 1, "units")
            self._request_rating_sync()
        return "break"

    def rating_overlay_click(self, event):
        self.close_popups()
        widget = self.rating_overlay
        x, y = event.x, event.y
        # Der Bezugspunkt wird beim Zeichnen aktualisiert.
        y_tree = y + getattr(self, "_rating_top", 0)
        path = self.tree.identify_row(y_tree)
        if not path or not self.tree.exists(path):
            return "break"
        gap = getattr(self, "_rating_star_gap", 22)
        number = min(5, max(1, int(max(0, x - 5) / gap) + 1))
        current = self.rating_values.get(path, 0)
        self.save_correction(path, "rating", 0 if number == current else number)
        self.tree.selection_set(path)
        self.tree.focus(path)
        self.refresh()
        if self.tree.exists(path):
            self.tree.selection_set(path)
            self.tree.focus(path)
        self._request_rating_sync()
        return "break"

    def _library_scrollbar_move(self, *args):
        """Synchronize star placement with native scrollbar motion."""
        self.tree.yview(*args)
        self._request_rating_sync()

    def _library_scroll_sync(self, event=None):
        # The default Tk Treeview class binding runs after this instance
        # handler, so the queued callback sees the final scroll position.
        self._request_rating_sync()

    def _request_rating_sync(self, settle=True):
        """Coalesce geometry/scroll/sort events into one cheap idle repaint.

        Important: never repaint synchronously inside a native Treeview callback,
        since the native sort/scroll/layout may not yet be committed.
        """
        if not settle or not getattr(self, '_rating_sync_job', None):
            self._rating_needs_settle = settle
        if not settle and self._rating_settle_job is not None:
            self.after_cancel(self._rating_settle_job)
            self._rating_settle_job = None
        if getattr(self, '_rating_sync_job', None) is None:
            try:
                self._rating_sync_job = self.after_idle(self._flush_rating_sync)
            except tk.TclError:
                return

    def _flush_rating_sync(self):
        self._rating_sync_job = None
        if (getattr(self, 'active_page', None) != 'library' or
                getattr(self, '_resizing_window', False)):
            return
        self.redraw_ratings()
        if not self._rating_needs_settle:
            return
        # Nur native Geometrieereignisse brauchen gegebenenfalls einen zweiten Durchlauf.
        previous = getattr(self, '_rating_settle_job', None)
        if previous is not None:
            try: self.after_cancel(previous)
            except tk.TclError: pass
        self._rating_settle_job = self.after(36, self._settle_rating_sync)

    def _settle_rating_sync(self):
        self._rating_settle_job = None
        if getattr(self, 'active_page', None) == 'library' and not self._resizing_window:
            self.redraw_ratings()

    def _rating_layout_state(self):
        tree = self.tree
        # Detect order-only changes as well as scrolling and new column widths.
        # This prevents stale stars when sorting leaves the scroll fraction intact.
        visible = self._visible_tree_rows(extra=0)
        first = visible[0][1] if visible else None
        last = visible[-1][1] if visible else None
        return (tuple(tree['displaycolumns']),
                tuple(round(v, 4) for v in tree.yview()),
                tree.winfo_width(), tree.winfo_height(),
                first, last, len(tree.get_children()),
                tuple(tree.selection()), self.hovered_row,
                self.active_track, self.playing, self.paused)

    def _queue_rating_refresh(self):
        """Fallback watcher; direct events handle normal scroll and reordering."""
        previous = getattr(self, '_rating_refresh_job', None)
        if previous is not None:
            try: self.after_cancel(previous)
            except tk.TclError: pass
        self._rating_refresh_job = self.after(180, self._timed_rating_refresh)

    def _timed_rating_refresh(self):
        self._rating_refresh_job = None
        if not hasattr(self, 'tree') or not self.tree.winfo_exists():
            return
        if self.active_page != 'library' or self._resizing_window:
            self._queue_rating_refresh()
            return
        try:
            state = self._rating_layout_state()
        except tk.TclError:
            return
        if state != getattr(self, '_last_rating_state', None):
            self.redraw_ratings()
        else:
            self._queue_rating_refresh()

    def redraw_ratings(self):
        """Eine gemeinsame Stern-Ebene exakt über der Bewertungsspalte.
        Keine pro Song positionierten Widgets und keine alten lilafarbenen Reste.
        """
        try:
            tree, canvas = self.tree, self.rating_overlay
            if not tree.winfo_exists() or not canvas.winfo_exists():
                return
            columns = list(tree["displaycolumns"])
            if "rating" not in columns:
                canvas.place_forget()
                self.redraw_moods()
                self._mask_partial_row()
                self._queue_rating_refresh()
                return
            indexed_items = self._visible_tree_rows()
            items = [item for _, item in indexed_items]
            if not items:
                canvas.place_forget()
                self._mask_partial_row()
                self._queue_rating_refresh()
                return
            # Treeview bestimmt Spaltenposition selbst. bbox liefert sie genau,
            # auch nach Änderung der Filterspalten und der Fensterbreite.
            box = next((tree.bbox(item, "rating") for item in items if tree.bbox(item, "rating")), None)
            if not box:
                canvas.place_forget()
                self._mask_partial_row()
                self._queue_rating_refresh()
                return
            col_x, _, col_width, _ = box
            # Oberkante des Datenbereichs, ohne die gelben Tabellenüberschriften zu verdecken.
            header = next((yy for yy in range(min(100, tree.winfo_height()))
                           if tree.identify_region(2, yy) in ("cell", "tree")), 30)
            self._rating_top = header
            draw_bottom = self._table_draw_bottom()
            height = max(1, draw_bottom - header)
            canvas.place(x=col_x + 2, y=header, width=max(1, col_width - 3), height=height)
            canvas.delete("all")
            self._rating_star_gap = max(19, min(27, int(self.zoom_level * 2.1)))
            selected = set(tree.selection())
            # Die Zeichenfläche erhält genau den Zeilenhintergrund, der in der
            # Treeview verwendet wird; jede Änderung wird ohne Widgets-Neuanlage gezeichnet.
            for i, item in indexed_items:
                rowbox = tree.bbox(item)
                if not rowbox:
                    continue
                _, top, _, rh = rowbox
                if top + rh <= header or top >= draw_bottom:
                    continue
                top -= header
                background = (ROW_PLAYING if item == self.active_track and self.playing
                              else ROW_SELECTED if item in selected else ROW_HOVER
                              if item == self.hovered_row else "#23133E" if i%2 else "#110A28")
                canvas.create_rectangle(0, top, col_width, top + rh,
                                        fill=background, outline="")
                stars = self.rating_values.get(item, 0)
                gap = self._rating_star_gap
                strip = self._star_strip(stars, gap, background)
                if strip is not None:
                    canvas.create_image(2, top + rh / 2, image=strip, anchor="w")
                else:
                    radius = min(gap * .40, rh * .35)
                    for n in range(5):
                        canvas.create_polygon(*self._star_points(5 + gap * (n+.5),
                                               top + rh/2, radius, radius*.49),
                                               fill=RATING_GOLD if n < stars else background,
                                               outline=RATING_GOLD, width=1.3)
            tk.Misc.lift(canvas)  # Raise widget, not Canvas item (tag_raise needs an ID)
            self.redraw_moods()
            self._mask_partial_row()
            try:
                self._last_rating_state=self._rating_layout_state()
            except tk.TclError:pass
            # Die Markierung des ausgewählten Songs bleibt sichtbar.
            if self.selection_marker.winfo_manager():
                self.selection_marker.lift()
            self._queue_rating_refresh()
        except (tk.TclError, ValueError):
            self._queue_rating_refresh()

    def mood_overlay_click(self, event):
        self.close_popups()
        row = self.tree.identify_row(event.y + getattr(self, "_mood_top", 0))
        if row:
            self.tree.selection_set(row)
            self.tree.focus(row)
        return "break"

    def mood_overlay_doubleclick(self, event):
        row = self.tree.identify_row(event.y + getattr(self, "_mood_top", 0))
        if row and self.edit_mode:
            self.start_cell_edit(row, "mood")
        elif row:
            self.tree.selection_set(row)
            self.play_selected()
        return "break"

    def redraw_moods(self):
        """Draw small, zoom-aware mood dots in a single column-wide layer.

        This is deliberately separate from font glyphs so dots retain their
        colours, including the black lightning icon for Energetisch.
        """
        try:
            tree, canvas = self.tree, self.mood_overlay
            if not tree.winfo_exists() or not canvas.winfo_exists():
                return
            if "mood" not in list(tree["displaycolumns"]):
                canvas.place_forget()
                return
            indexed_items = self._visible_tree_rows()
            items = [item for _, item in indexed_items]
            cell = next((tree.bbox(item, "mood") for item in items
                         if tree.bbox(item, "mood")), None)
            if not cell:
                canvas.place_forget()
                return
            from tkinter import font as tkfont
            x, _, width, _ = cell
            header = next((yy for yy in range(min(100, tree.winfo_height()))
                           if tree.identify_region(2, yy) in ("cell", "tree")), 30)
            self._mood_top = header
            draw_bottom = self._table_draw_bottom()
            canvas.place(x=x+2, y=header, width=max(1,width-3),
                         height=max(1, draw_bottom-header))
            canvas.delete("all")
            selected = set(tree.selection())
            size = max(7, min(19, round(self.zoom_level * 0.87)))
            font = tkfont.Font(family=self.ui_font, size=self.zoom_level)
            for i, item in indexed_items:
                box = tree.bbox(item)
                if not box:
                    continue
                top, rh = box[1]-header, box[3]
                if top+rh <= 0 or top >= draw_bottom-header:
                    continue
                background = (ROW_PLAYING if item == self.active_track and self.playing
                              else ROW_SELECTED if item in selected else ROW_HOVER
                              if item == self.hovered_row else "#23133E" if i%2 else "#110A28")
                canvas.create_rectangle(0, top, width, top+rh, fill=background, outline="")
                mood = str(tree.set(item, "mood") or "").strip()
                if not mood:
                    continue
                primary = mood.split(" · ")[0].strip()
                cy = top+rh/2
                canvas.create_text(7, cy, text=mood, anchor="w",
                                   fill=YELLOW if item in selected else TEXT,
                                   font=font)
                offset = min(width-size-7, 12 + font.measure(mood))
                if offset < 0:
                    continue
                radius = size/2
                color = MOOD_COLORS.get(primary, "#8a86bb")
                canvas.create_oval(offset, cy-radius, offset+size, cy+radius,
                                  fill=color, outline="")
                if primary == "Energetisch":
                    cx = offset+radius
                    bolt = [(cx+size*.07, cy-size*.35), (cx-size*.21,cy+size*.03),
                            (cx+size*.02,cy+size*.03), (cx-size*.09,cy+size*.34),
                            (cx+size*.24,cy-size*.10), (cx+size*.02,cy-size*.10)]
                    canvas.create_polygon(*[coord for pair in bolt for coord in pair],
                                          fill="#101010", outline="")
            tk.Misc.lift(canvas)  # Raise widget, not Canvas item (tag_raise needs an ID)
        except (tk.TclError, ValueError):
            return

    def _mask_partial_row(self):
        """An opaque baseline overlay clips all fragments of a final song row."""
        tree,mask=self.tree,self.table_bottom_mask
        if not tree.winfo_exists():return
        bottom=tree.winfo_height()
        draw_bottom=self._table_draw_bottom()
        if draw_bottom<bottom:
            mask.configure(bg="#0F0825")
            mask.place(x=0,y=draw_bottom,width=tree.winfo_width(),
                       height=bottom-draw_bottom)
            mask.lift()
        else:
            mask.place_forget()

